INSERT INTO `sp_pd_wticket_base` VALUES ('1864aeb209fa423ab5c4fd8554309b01', NULL, '11', '110F4942CE05522AE05336050A0A2485', NULL, NULL, '2', '1、500kV #2站用变500kV侧5002开关三相不一致时间继电器更换及离散性试验；\\r\\n2、500kV #2站用变500kV侧5002开关防拒动检查及机械特性分析；\\r\\n3、500kV #2站用变非电气量保护继电器检查；\\r\\n4、35kV #2站用变非电气量保护继电器检查；\\r\\n5、500kV #2站用变B1修（3年期）；\\r\\n6、500kV #2站用变进线避雷器B1修（3年期）及排水口堵塞锈蚀检查；\\r\\n7、35kV 321低压电抗器321开关、35kV 322低压电抗器322开关、35kV #2站用变35kV侧 327开关防拒动检查、CT接线盒检查及分合闸划线标识检查；\\r\\n8、35kV #2M母线避雷器A、B、C三相排水口堵塞锈蚀检查； \\r\\n9、35kV 321低压电抗器、35kV 322低压电抗器风道清理、汇流排引出线检查（反措执行）；\\r\\n10、500kV #2站用变500kV侧500217地刀、500227地刀分合闸划线标识检查；\\r\\n11、35kV #2站用变现场油温表检查及处理。', NULL, '2', NULL, '25902', NULL, '8', NULL, NULL, '2021-12-C1-006', NULL, '1', '金官换流站', '0110', '2', NULL, '4', '0CE72F6E82114FAFBA74E3749FD9E95F', '潘东省', '超高压', NULL, '2', NULL, '25659', NULL, NULL, '01100307', '01100301', '01100307', '95b7d9b3e1b845cda9be789426f0abf1_108', '011003', '2', NULL, NULL, '2', NULL, '01100301', NULL, '2022-01-01 16:22:11', NULL, NULL, NULL, NULL, '2021-12-16 11:30:00', NULL, '25902', '00035096_cgy', '赵银山', '01100307', '梁晨', NULL, NULL, '0CE72F6E82114FAFBA74E3749FD9E95F', '2021-12-18 19:44:00', '01100301', NULL, '25902', '1', '1', '01100301', NULL, '01', '±500kV金官换流站', '超高压输电公司大理局', NULL, NULL, '1、500kV #2站用变本体；\\r\\n2、500kV #2站用变本体端子箱及冷却器汇控箱；\\r\\n3、500kV #2站用变500kV侧5002开关A、B、C三相；\\r\\n4、500kV #2站用变500kV侧5002开关汇控箱；\\r\\n5、500kV #2站用变进线避雷器A、B、C三相本体；\\r\\n6、35kV 321低压电抗器321开关、35kV 322低压电抗器322开关、35kV #2站用变35kV侧327开关；\\r\\n7、35kV 321低压电抗器、35kV 322低压电抗器；\\r\\n8、35kV #2M母线避雷器A、B、C三相本体；\\r\\n9、35kV #2站用变本体；\\r\\n10、35kV #2站用变本体端子箱；\\r\\n11、500kV #2站用变500kV侧500217地刀、500227地刀。', '马鸿波', '25381', '2', NULL, '1', '2021-12-20 22:02:00', NULL, NULL, '变电一次班', NULL, NULL, '2021-12-10 17:03:34', '25659', '2021-12-19 20:20:00', NULL, '2021-12-13 20:56:00', NULL, '110F4942CC7D522AE05336050A0A2485', NULL, NULL, '18213308996', '马越、王兴、刘皞天。', NULL, NULL, '赵银山', '2021-12-20 18:00:00', '赵宏', NULL, '2021-12-14 10:00:00', '金官换流站', NULL, NULL,