INSERT INTO `sp_pd_wticket_base` VALUES ('2dc89f1c192945ba8e54c5aedf3b1ccf', NULL, '21', '24D3BDB422F4452C987B6656345DEB49', NULL, NULL, '2', '1、模拟、运行及饱和系数绝缘子盐密采样共12基;\\r\\n2、导线、地线磨损、断股、破股、严重锈蚀、放电损伤外层铝股、松动等走线检查共41档;\\r\\n3、金具锈蚀、磨损、裂纹、变形检查共79基;\\r\\n4、复合绝缘子憎水性检测共37基;\\r\\n5、间隔棒检查共7档;\\r\\n6、塔上异物清理共17基;\\r\\n7、塔材锈蚀位置防锈处理共3基;\\r\\n8、金具锈蚀位置防锈处理共10基;\\r\\n9、地线线夹补装R销及螺栓松动处理共4基;\\r\\n10、直线塔内串塔头端金具R销补装共1基;\\r\\n11、图像监控终端检查共8基;\\r\\n12、光缆接续盒检查共26基;\\r\\n13、导线耐张线夹裂纹金具补强共1基;\\r\\n14、复检验收耐张串盘型悬式绝缘子清扫（抽检30%验收塔位）共9基;\\r\\n15、复检验收复合绝缘子抽样更换共6基;\\r\\n16、检修所到塔位均需开展人工巡视，同步开展普侨直流线路防外力破坏、防山火、重要交叉跨越和大跨越区段、同走廊人工巡视;\\r\\n17、元蔓高速公路穿越±800kV普侨直流线路385#-387#涉及区段迁改项目验收详见专项方案。', NULL, '2', NULL, '8adc55c77e3478fe017ee782678f6ef0', NULL, '7', NULL, NULL, '2021-12-S1-003', NULL, '0', '800kV楚雄换流站', '0109', '2', NULL, '17', '00035111_cgy', '东广正', '超高压', NULL, '2', NULL, '25839', NULL, NULL, '01090618', '01090704', '01090618', '6fb6991e77ab4a96acf0a3231b904982_179', '010907', '2', NULL, NULL, '2', NULL, 'af2f9e393fcf4238bf63f6f8f716def9', NULL, '2022-01-02 12:07:13', NULL, NULL, NULL, NULL, '2021-12-06 08:44:00', NULL, '8adc55c77e3478fe017ee782678f6ef0', '00031360_cgy', '王彦国', '01090618', '廖纪瑞', NULL, NULL, '00035111_cgy', '2021-12-13 20:47:00', '01090704', NULL, '8adc55c77e3478fe017ee782678f6ef0', '1', '1', '010907', NULL, '01', '±800kV普侨直流线', '超高压输电公司昆明局', NULL, NULL, '±800kV普侨直流线路0001#-0682#塔。', '梅琦龙', '24220', '2', NULL, '2', '2021-12-24 18:33:00', NULL, NULL, '线路四班', NULL, NULL, '2021-12-03 08:05:27', '25839', '2021-12-14 15:09:00', NULL, '2021-12-04 16:50:00', NULL, '00035034_cgy', NULL, NULL, '15908802830', '邵洪良（4人）、刘宇洋（4人）、张瑜琪（4人）、赵庆鹏（4人）。', NULL, NULL, '王彦国', '2021-12-14 18:00:00', '徐根堂', NULL, '2021-12-06 08:30:00', '800kV楚雄换流站', NULL, NULL, '线路四班', NULL, '1', '24220', NULL, '800kV楚雄换流站', '89', '01090704', '01092527849', NULL, '2', '输电管理所', '25839', '1', NULL, '2021-12-04 14:56:00', '输电管理所', NULL, '2', '2021-12-14 07:22:00', '00032470_cgy', NULL, NULL, '输电管理所/线路四班', NULL, '±800kV普侨直流线', NULL