INSERT INTO `sp_pd_wticket_base` VALUES ('60b994cd08c143988e4be965132aac81', NULL, '11', '77BC347138D84931BCD81310808A0513', NULL, NULL, '2', '1、极2低端023B、024B换流变A、B、C相B修(6年项目)。\\r\\n2、极2低端023B、024B换流变中性点CT停电维护。\\r\\n3、极2低端023B、024B换流变A、B、C相冷却器控制箱维护。\\r\\n4、极2低端023B、024B换流变A、B、C相有载调压开关控制箱维护。\\r\\n5、极2低端阀厅地网导通测试。\\r\\n6、极2低端换流变进线PT SF6测试。\\r\\n7、极2低端换流变进线GIL母线B5、G41气室SF6测试。\\r\\n8、极2低端024B换流变C相分接头控制故障检查处理。\\r\\n9、极2低端024B换流变A相分接头控制故障检查处理。\\r\\n10、极2低端023B换流变C相从右往左第一组、从上往下第一个冷却器风扇AN631更换。\\r\\n11、极2低端023B换流变C相有载分接开关控制箱内H1信号指示灯熄灭检查处理。\\r\\n12、极2低端023B换流变B相有载调压开关控制箱观察窗内侧有少量水汽凝露检查处理。\\r\\n13、极2低端024B换流变C相有载调压开关控制箱观察窗内侧有少量水汽凝露检查处理。\\r\\n14、极2低端023B换流变B相冷却器交流进线电源运行消失、冷却器远控消失、冷却器风扇运行消失、PLC OK消失、极2低端阀组解锁信号消失故障检查处理。\\r\\n15、极2低端023B、024B换流变A、B、C相阀侧套管感温试纸及一次整体的连接状况分析。\\r\\n16、极2低端023B、024B换流变A、B、C相散热器蝶阀螺栓连接状况检查。\\r\\n17、极2低端023B、024B换流变A、B、C相瓦斯继电器防误动检查。\\r\\n18、极2低端023B、024B换流变A、B、C相防范变压器交直流串电风险检查处理。\\r\\n19、极2低端023B、024B换流变A、B、C相强油循环型设备油泵及油流方向指示器隐患排查。\\r\\n20、极2低端023B换流变A、B、C相，024B换流变A、B相南瓷网侧套管将军帽检查。\\r\\n21、极2低端023B、024B换流变A、B、C相油色谱在线漏油隐患排查及油枕油位信号排查处理。\\r\\n22、极2低端023B换流变A相、024B换流变C相换流变分接开关吊芯后直流电阻测试。\\r\\n23、极2低端023B、024B换流变A、B、C相振动传感器加装。', NULL, '2', NULL, '8adc55c77e3478fe017ee78059d46ee5', NULL, '8', NULL, NULL, '2021-12-C1-108', NULL, '0', '800kV普洱换流站', '0109', '2', NULL, '4', '00030679_cgy', '王小岭', '超高压', NULL, '2', NULL, '8af935017bcf2919017ca0af66ce137d', NULL, NULL, '01090616', '01090623', '01090616', '2443dbe018cb48c8a5687b09316fb40c_518', '010906', '2', NULL, NULL, '2', NULL, '01090623', NULL, '2022-01-06 08:44:34', NULL, NULL, NULL, NULL, '2021-12-14 14:59:00', NULL, '8adc55c77e3478fe017ee78059d46ee5', '00031901_cgy', '薛庆会', '01090616', '陈光亚', NULL, NULL, '00030679_cgy', '2021-12-20 12:36:00', '01090623', NULL, '8adc55c77e3478fe017ee78059d46ee5', '1', '1', '01090609', NULL, '01', '±800kV普洱换流站', '超高压输电公司昆明局', NULL, NULL, '1、极2低端023B、024B换流变A、B、C相本体处；\\r\\n2、极2低端023B、024B换流变A、B、C相冷却器控制箱处；\\r\\n3、极2低端023B、024B换流变中性点CT处。\\r\\n4、极2低端阀厅内；\\r\\n5、极2低端换流变进线PT A、B、C相处；\\r\\