INSERT INTO `sp_pd_wticket_base` VALUES ('6a0ea3ba56c947b98b06455282018e96', NULL, '12', '00035038_cgy', NULL, NULL, '2', '（一）电气部分\\r\\n1、交流场、交流滤波场、融冰区域、500kV高抗区域提升GB50169接地“明显、可靠、直接、顺直、服帖”要求，排查处理接地缺失、不可靠、串联、无效、焊接搭接面积不足、标识不规范、接地螺栓与扁铁尺寸不匹配等问题处理。\\r\\n2、交流滤波器场区域电缆夹层穿墙处电缆展放、标识、防火封堵不规范排查处理。\\r\\n3、交流场、交流滤波场、融冰区域、500kV高抗区域OPGW光缆需要进一步规整整齐，穿管封堵不严密处理。\\r\\n4、综合楼照明灯具槽盒吊杆不顺直检查处理。\\r\\n5、综合水泵房电缆穿墙未封堵，消防泵接地工艺不规范，管道法兰未跨接，消防设施安装工艺不佳处理。\\r\\n6、交流滤波器场就地汇控箱铜排未与地网连接检查处理。\\r\\n7、500kV高抗区域事故排油管玻璃罩不便于击破检查处理。\\r\\n8、51、52蓄电池小室蓄电池电缆引出线缺正、负极性标识处理。\\r\\n9、综合水泵房穿墙电缆未封堵及涂刷防火涂料处理，电缆夹层入口模块封堵防火墙两侧未刷防火涂料处理。\\r\\n10、500kV#1、#2站用变区变压器事故排油阀口离格栅太近，不便于操作处理。\\r\\n11、交流滤波器场构支架螺栓无防松措施检查处理。\\r\\n12、综合水泵房检修电源箱无电源进线处理。\\r\\n（二）土建部分\\r\\n1、专用品库房靠围墙侧窗户墙壁渗水，消防泡沫间四个窗户墙壁均有不同程度的渗水，GIS综合楼侧大门处、G\\r\\nIS室、站公用400V进门左侧空调、站公用400V侧门空调、备用平抗靠交流滤波器侧、备用平抗室围墙侧窗户墙壁\\r\\n渗水、51小室门口。10kV配电室进门右侧墙角处漏水处理。\\r\\n2、综合楼84N04消防栓自救盘检修阀与软管连接处漏水；41N07消防栓水带差接口；61N01、61N03、61N04消\\r\\n防栓水带绑扎处和消火栓扳手生锈，交流滤波器场靠563围栏旁41N07消火栓箱内其中一盘消防水带缺少一个接\\r\\n头，一次备品库靠综合楼侧围墙少一只灭火器处理。\\r\\n3、融冰区域电缆沟积水处理。\\r\\n4、高抗区由于地基下陷出现问题未处理，场地灯杆歪斜、地面塌陷等处理。\\r\\n5、综合楼二楼男卫生间右一、二楼左一便坑堵塞，综合楼休息室卫生间玻璃损坏3块，二楼公共卫生间墙体出\\r\\n水、门框下脚损坏，321热水器损坏、319浴霸灯损坏、楼期间声控灯损坏，综合楼部分木质贴皮的门、门框贴皮\\r\\n脱落处理。\\r\\n6、站区部分门钥匙未移交，导致无法打开处理。\\r\\n7、站区大量屏蔽门窗未灌浆或灌浆过程中堵塞门锁孔处理。\\r\\n8、52继电器室门口台阶地砖缺失处理。\\r\\n9、综合水泵房的“手动明杆闸阀DN”铭牌缺失处理。\\r\\n10、综合水泵房内，消防水池与吸水井之间的两个启闭阀门关闭不严实，无法将各消防蓄水池分隔，缺陷处理。', NULL, '2', NULL, '8adc55c77e3478fe017ee77e33e66edd', NULL, '7', NULL, NULL, '2021-12-C2-008', NULL, '0', '500kV禄劝换流站', '0109', '2', NULL, '6', 'F8A59E6A9B5B440FB065B89AB3F549D9', '张万成', '超高压', NULL, '2', NULL, '40220A66F9F14250B7A86E2DC14FE309', NULL, NULL, '01090615', 'EXtCTU1n', '01090615', '8e3e4d90579a4fcaa74a1f5355eef31d_147', '010906', '2', NULL, NULL, '1', NULL, 'EXtCTU1n', NULL, '2022-01-24 00:36:21', NULL, NULL, NULL, NULL, '2021-12-28 16:50:00', NULL, '8adc55c77e3478fe017ee77e33e66edd', 'ECB7D9D741AB416A8137B8BBDFA86290', '张青礼', '01090615', '李荣涛', NULL, NULL, 'F8A59E6A9B5B440FB065B89AB3F549D9', '2022-01-20 17:56:00', 'EXtCTU1n', NULL, '8adc55c77e3478fe017ee77e33e66edd', '1', '1', 'EXtCTU1n', NULL, '01', '±500kV禄劝换流站', '超高压输电公司昆明局', NULL, NULL, '1、综合楼区域、51继电小室、52继电小室、备用平波电抗器室、综合水泵房区域、500kV GIS室区域、35kV #1融冰装置区域、500kV高抗区域、500kV交流滤波场区域、 2、500kV #1站用变区域、500kV #2站用变区域。', '李荣涛', '24212', '2', '00031901_cgy', '1', NULL, NULL, NULL, '云南省送变电工程公司', NULL, NULL, '2021-12-25 15:39:36', '40220A66F9F14250B7A86E2DC14FE309', '2022-01-21 19:00:00', NULL, '2021-12-28 15:40:00', NULL, '00035038_cgy', NULL, '王小岭', '15288281264', '蒋正元、杨加远、杨茂君、杨绍华、杨义琴。', NULL, NULL, '张青礼', '2022-01-20 18:00:00', '杨大生', NULL, '2021-12-28 08:00:00', '500kV禄劝换流站', NULL, NULL, '云南省送变电工程公司', '2021-12-28 11:44:00', '1', '40220A66F9F14250B7A86E2DC14FE309', NULL, '500kV禄劝换流站', '117', 'EXtCTU1n', '6250956ee20543a6a18ac46f7729b1cf', '2022-01-25 18:00:00', '2', '云南省送变电工程公司', '40220A66F9F14250B7A86E2DC14FE309', '1', NULL, '2021-12-28 11:35:00', '变电管理所', NULL, '2', '2022-01-21 09:48:00', '240203B00DAF4C129C42B53B3FC0D256', NULL, NULL, '云南省送变电工程公司', NULL, '±500kV禄劝换流站', NULL, NULL, '2');
