INSERT INTO `sp_pd_wticket_base` VALUES ('6df71c1512524557afab2c23c057a074', NULL, '21', '00030639_cgy', NULL, NULL, '2', '利用±500kV天广直流极1、极2线路停电检修的机会，开展以下改迁工作任务：\\r\\n1、在±500kV天广直流极1、极2线路1006#、1016#装设极1、极2保护接地线；\\r\\n2、新1008+1#、新1013#共2基铁塔组立及防坠落安装；\\r\\n3、新1008+1#～新1013#架设新导地线紧线、附件安装，1008#～新1008+1#段及新1013#～1014#段更换间隔棒，1008#大号侧、1014#小号侧导线、地线、防震锤、金具和绝缘子利旧进行紧线、附件安装；\\r\\n4、安装安全备份线夹：本工程跨越在建六宾高速公路新1010#-新1010+1#档内、跨越贵隆高速公路新1012#-新1013#档内所有的导、地线耐张线夹均安装备份线夹；\\r\\n5、新1010#大号侧、新1010+1#小号侧、新1012#大号侧、新1013#塔小号侧各安装1套在线监测装置，共4套视频在线监测装置；\\r\\n6、新建 7基铁塔三牌、直升机巡视牌安装；\\r\\n7、X 光检测：本工程跨越在建六宾高速新1010#-新1010+1#档内、跨越贵隆高速公路新1012#-新1013#档内，导、地线耐张线夹进行 X 光无损检测，共40处；\\r\\n8、拆除1009#～1013#塔段5基旧塔以及相应的导线、地线、金具；\\r\\n9、在±500kV天广直流极1、极2线路1006#、1016#拆除极1、极2保护接地线。', NULL, '2', NULL, '24084', NULL, '7', NULL, NULL, '2021-12-S1-009', NULL, '0', '500kV平果变电站', '0103', '2', NULL, '42', 'DD41B19B92F846DE9AE737334BE4AB36', '陈仕能', '超高压', NULL, '2', NULL, '64DDCB8A3EEC477698ECDC7BD73FBC52', NULL, NULL, '01031144', 'EXtCuSDn', '01031144', '19c5401f9a4a452996ece7c97c03bbd3_942', '010310', '2', NULL, NULL, '1', NULL, 'EXtCuSDn', NULL, '2022-01-07 16:08:27', NULL, NULL, NULL, NULL, '2021-12-15 09:45:00', NULL, '24084', 'E6639D4E988B4C9C98119EB2CB99F52C', '陈斌', '01031144', '李启胜', NULL, NULL, 'DD41B19B92F846DE9AE737334BE4AB36', NULL, 'EXtCuSDn', NULL, '24084', '1', '1', 'EXtCuSDn', NULL, '01', '±500kV天广直流极1、极2线路', '超高压输电公司南宁局', NULL, NULL, '±500kV天广直流极1、极2线路1006#塔至1016#塔。', '李启胜', '24104', '2', '00034763_cgy', '2', '2022-01-06 17:00:00', NULL, NULL, '广西恒都输变电工程有限公司', NULL, NULL, '2021-12-14 16:09:31', '64DDCB8A3EEC477698ECDC7BD73FBC52', '2021-12-30 17:30:00', NULL, '2021-12-14 20:50:00', NULL, '00030639_cgy', NULL, '方刚', '15678885814', '陈斌（11人），陈俊桦（20人），韦校民（11人）', NULL, NULL, '陈斌', '2022-01-06 18:00:00', '廖远', NULL, '2021-12-15 09:30:00', '500kV平果变电站', NULL, NULL, '广西恒都输变电工程有限公司', '2021-12-14 20:48:00', NULL, '64DDCB8A3EEC477698ECDC7BD73FBC52', NULL, '500kV平果变电站', '49', 'EXtCuSDn', '01031792509', NULL, '2', '广西恒都输变电工