INSERT INTO `sp_pd_wticket_base` VALUES ('a23fafa668dd4e22973b3535773c1bba', NULL, '21', '110F4942CE17522AE05336050A0A2485', NULL, NULL, '2', '利用±500kV天广直流线极1、极2线路停电检修的机会，开展以下改迁工作任务： \\r\\n1、两极保护接地线装设：0814#（小号侧）、0826#（大号侧）共2基；\\r\\n2、新建铁塔2基耐张塔，共计2基；完成铁塔防坠落装置、安健环安装；\\r\\n3、原0815#～原0825#架设新导地线紧线、间隔棒、防震锤、金具和绝缘子利旧进行紧线、附件安装；\\r\\n4、X 光检测：本工程跨越平南高速路 JB1（新0818#）～JB2（新0819#）档内导、地线耐张线夹进行 X 光无损检测，共 20处； \\r\\n5、安装安全备份线夹：JB1（新0818#）大号侧、JB2（新0819#）小号侧所有的导、地线耐张线夹均安装备份线夹； \\r\\n6、JB1（新0818#）塔大号侧共1套视频在线监测装置安装和JB2（新0819#）小号侧导线安装1套故障定位在线监测装置；\\r\\n7、安装 2 基铁塔三牌更换及直升机巡视牌安装；\\r\\n8、拆除旧塔0818#、0819#共2基，以及旧0815#~旧0825#塔相应的导线、地线、金具绝缘子；\\r\\n9、两极保护接地线拆除：0814#（小号侧）、0826#（大号侧）共2基。', NULL, '2', NULL, '24084', NULL, '7', NULL, NULL, '2021-12-S1-011', NULL, '0', '500kV平果变电站', '0103', '2', NULL, '69', 'B41A23CE5C5F45158AD8CD3A57394B15', '程小凯', '超高压', NULL, '2', NULL, '8af935015360a8c601537d056dfc0170', NULL, NULL, '01031144', 'EXtCv5dl', '01031144', '4d3357e2503b40f68bc6ff84b109d812_333', '010310', '2', NULL, NULL, '1', NULL, 'EXtCv5dl', NULL, '2022-01-07 16:15:02', NULL, NULL, NULL, NULL, '2021-12-15 09:38:00', NULL, '24084', '6A9E128E9D81457797F85D3322ADC820', '谢承志', '01031144', '李彦宏', NULL, NULL, 'B41A23CE5C5F45158AD8CD3A57394B15', NULL, 'EXtCv5dl', NULL, '24084', '1', '1', 'EXtCv5dl', NULL, '01', '±500kV天广直流线极1、极2线路', '超高压输电公司南宁局', NULL, NULL, '±500kV天广直流线极1、极2线路0814#塔至0826#塔。', '李启胜', '24104', '2', '00034763_cgy', '2', '2022-01-06 17:00:00', NULL, NULL, '湖南湘江电力建设集团有限公司', NULL, NULL, '2021-12-14 14:25:32', '8af935015360a8c601537d056dfc0170', '2021-12-25 17:48:00', NULL, '2021-12-14 22:03:00', NULL, '00030639_cgy', NULL, '方刚', '13607389638', '蒋中平（11人）、蒋开明（17人）、蒋先涛（18人）、刘成银（22人）', NULL, NULL, '谢承志', '2022-01-06 18:00:00', '宋名晔', NULL, '2021-12-15 09:30:00', '500kV平果变电站', NULL, NULL, '湖南湘江电力建设集团有限公司', '2021-12-14 21:58:00', NULL, '8af935015360a8c601537d056dfc0170', NULL, '500kV平果变电站', '39', 'EXtCv5dl', '01031792509', NULL, '2', '湖南湘江电力建设集团有限公司', '8af935015360a8c601537d056dfc0170', NULL, NULL, '2