INSERT INTO `sp_pd_wticket_base` VALUES ('a4d7a40e03d0410fa0a73cfbb96ef6c8', NULL, '21', '110F4942CC92522AE05336050A0A2485', NULL, NULL, '2', '利用500kV平来Ⅱ线线路停电检修机会，开展以下施工任务：\\r\\n1、三相保护接地线装设：旧064#（小号侧）、旧090#（大号侧）共2基；\\r\\n2、新建JA2（新081#）、JA3（新082+1#）耐张塔2基，A2（新082#）直线塔1基，共计3基；完成铁塔防坠落装置、安健环安装；\\r\\n3、原065#～原089#塔架设新导地线紧线、安装间隔棒和防震锤、更换金具和绝缘子进行紧线、附件安装；\\r\\n4、X 光检测：本工程跨越平南高速路新081#～新082+1#档内导、地线耐张线夹进行 X 光无损检测，共 26处； \\r\\n5、安装安全备份线夹：新081#大号侧、新082#+1小号侧所有的导、地线及光缆的耐张线夹均安装备份线夹； \\r\\n6、在新081#大号侧和新082#小号侧导线处安装视频在线监测装置共2套；\\r\\n7、新081#、新082+1#、新082#共 3 基铁塔三牌更换及直升机巡视牌安装；\\r\\n8、拆除旧081#、082#塔2基旧塔，以及旧081#~旧082#塔相应的导线、地线、金具绝缘子；\\r\\n9、三相保护接地线拆除：旧064#（小号侧）、旧090#（大号侧）共2基。', NULL, '2', NULL, '24084', NULL, '7', NULL, NULL, '2021-12-S1-024', NULL, '0', '500kV平果变电站', '0103', '2', NULL, '100', 'B41A23CE5C5F45158AD8CD3A57394B15', '程小凯', '超高压', NULL, '2', NULL, '8af935015360a8c601537d056dfc0170', NULL, NULL, '01031144', 'EXtCv5dl', '01031144', '5a4fcb09b3e740f09dfcca89206ca51c_892', '010310', '2', NULL, NULL, '1', NULL, 'EXtCv5dl', NULL, '2022-01-31 09:01:25', NULL, NULL, NULL, NULL, '2022-01-01 09:52:00', NULL, '24084', '6A9E128E9D81457797F85D3322ADC820', '谢承志', '01031144', '宋名晔', NULL, NULL, 'B41A23CE5C5F45158AD8CD3A57394B15', NULL, 'EXtCv5dl', NULL, '24084', '1', '1', 'EXtCv5dl', NULL, '01', '500kV平来Ⅱ线', '超高压输电公司南宁局', NULL, NULL, '500kV平来Ⅱ线064#塔至090#塔。', '宋名晔', '24104', '2', '00034763_cgy', '2', '2022-01-20 15:58:00', NULL, NULL, '湖南湘江电力建设集团有限公司', NULL, NULL, '2021-12-25 17:41:35', '8af935015360a8c601537d056dfc0170', '2022-01-20 11:00:00', NULL, '2021-12-31 20:07:00', NULL, '110F4942CC92522AE05336050A0A2485', NULL, '方刚', '13607389638', '蒋中平（23人）、蒋开明（18人）、蒋先涛（18人）、刘成银（22人）、段善林（18人）', NULL, NULL, '谢承志', '2022-01-20 18:00:00', '李启胜', NULL, '2022-01-01 09:30:00', '500kV平果变电站', NULL, NULL, '湖南湘江电力建设集团有限公司', '2021-12-31 17:40:00', '1', '8af935015360a8c601537d056dfc0170', NULL, '500kV平果变电站', '42', 'EXtCv5dl', '01031864815', NULL, '2', '湖南湘江电力建设集团有限公司', '8af935015360a8c601537d056dfc0170', '1', N