INSERT INTO `sp_pd_wticket_base` VALUES ('a5131a877fc14da886fd46de490684c3', NULL, '11', '00035081_cgy', NULL, NULL, '2', '1、500kV 571、572、573、574 交流滤波器围栏内设备 B 修（1 年项目）；\\r\\n2、500kV 572 交流滤波器 C 相 C1 电容器高压塔的南侧从上往下第 4 层从左往右第二、三个电容器之间鸟窝清理；\\r\\n3、500kV 571 交流滤波器 A 相 C1 电容器高压塔的南侧从上往下第 4 层从左往右第二、三个电容器之间鸟窝清理；\\r\\n4、500kV 571 交流滤波器 B 相 C1 电容器低压塔的南侧从上往下第 5 层从左往右第二、三个电容器之间鸟窝清理；\\r\\n5、500kV 571、572、573、574 交流滤波器围栏内干式电抗器风道清理，上下汇流排每个引出线头断开及开焊等损伤检查；\\r\\n6、500kV 571、572、573、574 交流滤波器围栏内地网导通测试。', NULL, '2', NULL, '8adc55c77e3478fe017ee78059d46ee5', NULL, '8', NULL, NULL, '2021-12-C1-111', NULL, '0', '800kV普洱换流站', '0109', '2', NULL, '2', '00035085_cgy', '王小岭', '超高压', NULL, '2', NULL, '8af935017bcf2919017ca0af66ce137d', NULL, NULL, '01090616', '01090623', '01090616', 'd3b3b2cc578d497c832407b344c5a261_519', '010906', '2', NULL, NULL, '2', NULL, '0a2d1e05f7ff49dbb5dea783d4cb4a31', NULL, '2022-01-06 08:44:34', NULL, NULL, NULL, NULL, '2021-12-15 09:15:00', NULL, '8adc55c77e3478fe017ee78059d46ee5', '00031901_cgy', '梁迪团', '01090616', '谭佳', NULL, NULL, '00035085_cgy', '2021-12-15 16:16:00', '01090623', NULL, '8adc55c77e3478fe017ee78059d46ee5', '1', '1', '01090609', NULL, '01', '±800kV普洱换流站', '超高压输电公司昆明局', NULL, NULL, '500kV 571、572、573、574交流滤波器围栏内。', '乔柱桥', '24212', '2', NULL, '1', '2021-12-24 21:25:00', NULL, NULL, '高压试验二班', NULL, NULL, '2021-12-12 21:03:40', '8af935017bcf2919017ca0af66ce137d', '2021-12-22 16:41:00', NULL, '2021-12-12 22:47:00', NULL, '00035087_cgy', NULL, NULL, '13629408923', '罗宗圣。', NULL, NULL, '梁迪团', '2021-12-23 18:00:00', '陈思奇', NULL, '2021-12-13 08:00:00', '800kV普洱换流站', NULL, NULL, '高压试验二班', NULL, '1', '8adc55c77e3478fe017ee75009216ead', NULL, '800kV普洱换流站', '27', '01090623', '01099052', NULL, '2', '变电一次二班', '8af935017bcf2919017ca0af66ce137d', '1', NULL, '2021-12-12 21:28:00', '变电管理所', NULL, '2', '2021-12-22 09:02:00', '110F4942CB4F522AE05336050A0A2485', NULL, NULL, '变电管理所/高压试验二班', NULL, '±800kV普洱换流站', NULL, NULL, '2');
