INSERT INTO `sp_pd_wticket_base` VALUES ('bc1083b3e4de4bb9af21d59d7820b2a1', NULL, '11', '00035081_cgy', NULL, NULL, '2', '1、极1高端 011B、012B 换流变A、B、C 三相 B修（1年项目)；\\r\\n2、极1高端 011B、012B 换流变中性点CT B修（6年项目）；\\r\\n3、极1高端011B、012B 换流变A、B、C 三相冷却器控制箱维护；\\r\\n4、极1高端011B、012B 换流变A、B、C 三相有载调压开关控制箱维护；\\r\\n5、极1高端阀厅地网导通测试；\\r\\n6、极1高端011B换流变A相分接头控制故障检查处理；\\r\\n7、极1高端011B换流变B相本体油位显示异常检查处理；\\r\\n8、极1高端011B换流变C相 2.1 套管接头处发热处理；\\r\\n9、极1高端011B换流变A相主油箱呼吸器告警处理；\\r\\n10、极1高端 011B、012B 换流变A、B、C 三相阀侧套管感温试纸及一次整体的连接状况分析；\\r\\n11、极1高端 011B、012B 换流变A、B、C 三相散热器蝶阀螺栓连接状况检查；\\r\\n12、极1高端 011B、012B 换流变A、B、C 三相瓦斯继电器防误动检查；\\r\\n13、极1高端 011B、012B 换流变A、B、C 三相防范变压器交直流串电风险检查、处理；\\r\\n14、极1高端 011B、012B 换流变A、B、C 三相强油循环型设备油泵及油流方向指示器隐患排查；\\r\\n15、极1高端 011B、012B 换流变A、B、C 三相油色谱在线漏油隐患排查及油枕油位信号排查。', NULL, '2', NULL, '8adc55c77e3478fe017ee78059d46ee5', NULL, '8', NULL, NULL, '2021-12-C1-006', NULL, '1', '800kV普洱换流站', '0109', '2', NULL, '4', '00035953_cgy', '王小岭', '超高压', NULL, '2', NULL, '8af935017bcf2919017ca0af66ce137d', NULL, NULL, '01090616', '01090623', '01090616', '7f7be9148423422d84d8199f8dd2b5a9_321', '010906', '2', NULL, NULL, '2', NULL, '01090623', NULL, '2022-01-06 08:44:34', NULL, NULL, NULL, NULL, '2021-12-05 20:34:00', NULL, '8adc55c77e3478fe017ee78059d46ee5', '00031901_cgy', '张绍伟', '01090616', '谭佳', NULL, NULL, '00035953_cgy', '2021-12-08 18:45:00', '01090623', NULL, '8adc55c77e3478fe017ee78059d46ee5', '1', '1', '01090609', NULL, '01', '±800kV普洱换流站', '超高压输电公司昆明局', NULL, NULL, '1、极1高端 011B、012B 换流变 A、B、C 三相本体处； \\r\\n2、极1高端 011B、012B 换流变 A、B、C 三相冷却器控制箱处； \\r\\n3、极1 高端 011B、012B 换流变中性点 CT 处；\\r\\n4、极1高端阀厅内。', '蒋新华', '24212', '2', NULL, '1', '2021-12-25 01:33:00', NULL, NULL, '高压试验二班', NULL, NULL, '2021-12-04 20:01:21', '8af935017bcf2919017ca0af66ce137d', '2021-12-18 19:10:00', NULL, '2021-12-05 20:06:00', NULL, '00035072_cgy', NULL, NULL, '15887254421', '瞿发富、杨锐雄、徐友。', NULL, NULL, '张绍伟', '2021-12-08 22:00:00', '梁显润', NULL, '2021-12-05 08:30:00', '800kV普洱换流站', NULL, NULL, '高压试验二班', NULL, '1', '8adc55c7