INSERT INTO `sp_pd_wticket_base` VALUES ('e2c29aa5356a4e06b8b9cfd76aa7ed69', NULL, '21', '110F4942CC2B522AE05336050A0A2485', NULL, NULL, '2', '利用500kV永南甲线停电检修的机会，对500kV永南甲线开展以下工作：\\r\\n1、三相保护接地线装设：243#（小号侧）、247#（大号侧）、255#（大号侧）共3基；\\r\\n2、新建XJC2（新245#）、XJC3（新246#）共2基塔以及防坠落安装；\\r\\n3、新建XJC2（新245#）～XJC3（新246#）架设新导地线紧线、附件安装；244#～XJC2（新245#）段及XJC3（新246#）～247#段导线、地线、间隔棒、防震锤、金具和绝缘子利旧进行紧线、附件安装；\\r\\n4、拆除245#塔、246#塔2基旧塔以及相应的导线、地线、金具；\\r\\n5、X 光检测：本工程跨越高速路 XJC2（新245#）～XJC3（新246#） 档内导、地线耐张线夹进行 X 光无损检测，共26处；6、安装安全备份线夹：XJC2（新245#）、XJC3（新246#）大小号侧所有的导、地线耐张线夹均安装备份线夹；\\r\\n7、XJC2（新245#）、XJC3（新246#）塔共2套视频在线监测装置安装和在255#小号侧安装1套故障定位在线监测装置；\\r\\n8、 244#~XJC2（新245#） 及 XJC3（新246#）~247#档间隔棒全部更换；\\r\\n9、新建 2 基铁塔三牌更换及直升机巡视牌安装；\\r\\n10、三相保护接地线拆除：243#（小号侧）、247#（大号侧）、255#（大号侧）共3基。', NULL, '2', NULL, '24084', NULL, '7', NULL, NULL, '2021-12-S1-005', NULL, '0', '500kV平果变电站', '0103', '2', NULL, '36', 'FEE7F96ACC3C4BE3A9B5B0E9FB0FCCCE', '李东城', '超高压', NULL, '2', NULL, '8af93501534ec92001534ee618c4002c', NULL, NULL, '01031144', 'EXtCuSjn', '01031144', 'b0137f1e87c0430ba1268336e88469d5_422', '010310', '2', NULL, NULL, '1', NULL, 'EXtCuSjn', NULL, '2022-01-07 16:15:50', NULL, NULL, NULL, NULL, '2021-12-11 15:15:00', NULL, '24084', '80F48D97E31B4974B374D873ED08F79C', '李春柯', '01031144', '廖远', NULL, NULL, 'FEE7F96ACC3C4BE3A9B5B0E9FB0FCCCE', NULL, 'EXtCuSjn', NULL, '24084', '1', '1', 'EXtCuSjn', NULL, '01', '500kV永南甲线', '超高压输电公司南宁局', NULL, NULL, '500kV永南甲线243#塔至255#塔。', '李启胜', '24104', '2', '00034763_cgy', '2', '2021-12-23 17:48:00', NULL, NULL, '广西建宁输变电工程有限公司', NULL, NULL, '2021-12-10 15:18:27', '8af93501534ec92001534ee618c4002c', '2021-12-23 15:05:00', NULL, '2021-12-10 20:06:00', NULL, '00030639_cgy', NULL, '方刚', '18249934116', '韦大剑（12人）、韦世问（13人）、吴先任（10人）', NULL, NULL, '李春柯', '2021-12-25 18:00:00', '廖远', NULL, '2021-12-11 10:00:00', '500kV平果变电站', NULL, NULL, '广西建宁输变电工程有限公司', '2021-12-10 18:45:00', NULL, '8af93501534ec92001534ee618c4002c', NULL, '500kV平果变电站', '64', 'EXtCuSjn', '01031887202', NULL, '2', '