INSERT INTO `sp_pd_wticket_base` VALUES ('fc1bce40371843c5af8b44cca6afd694', NULL, '21', '110F4942CC92522AE05336050A0A2485', NULL, NULL, '2', '利用±500kV兴安直流极1、极2线路停电检修机会，开展以下施工任务：\\r\\n1、两极保护接地线装设：1282#（小号侧）、1286#（大号侧）共2基；\\r\\n2、新建铁塔3基耐张塔1283+1#、1284#、1284+1#，共计3基；完成铁塔防坠落装置、安健环安装；\\r\\n3、新塔1283+1#～新塔1284+1#架设新导地线紧线、间隔棒、防震锤、金具和绝缘子利旧进行紧线、附件安装；调整1283#～XJ1283+1#档旧线弧垂、防振锤、间隔棒；\\r\\n4、X 光检测：本工程跨越平武高速路新1283+1#～新1284#档内导、地线耐张线夹进行 X 光无损检测，共 20处；\\r\\n5、安装安全备份线夹：新1283+1#大号侧、新1284#小号侧所有的导、地线耐张线夹均安装备份线夹； \\r\\n6、新1283+1#塔大号侧和新1284#塔小号侧共2套视频在线监测装置安装；\\r\\n7、在1283+1#、1284#、1284+1#安装3基铁塔安健环更换及直升机巡视牌安装；\\r\\n8、拆除旧1284#塔1基旧塔，以及新1283+1#~新1284+1#塔段相应的导线、地线、金具绝缘子；\\r\\n9、两极保护接地线拆除：1282#（小号侧）、1286#（大号侧）共2基。', NULL, '2', NULL, '24084', NULL, '7', NULL, NULL, '2021-12-S1-021', NULL, '0', '500kV平果变电站', '0103', '2', NULL, '40', 'D1737E27554A4453AD0547B75393D4B9', '杨峰', '超高压', NULL, '2', NULL, '8af935015360a8c601537d056dfc0170', NULL, NULL, '01031144', 'EXtCv5dl', '01031144', '1a74049a961a4fe29794c779d79e1001_167', '010310', '2', NULL, NULL, '1', NULL, 'EXtCv5dl', NULL, '2022-01-31 09:01:25', NULL, NULL, NULL, NULL, '2021-12-26 15:25:00', NULL, '24084', '20CC2CEE1EA54703A7A88A2401BFDF22', '赵纯彬', '01031144', '宋名晔', NULL, NULL, 'D1737E27554A4453AD0547B75393D4B9', NULL, 'EXtCv5dl', NULL, '24084', '1', '1', 'EXtCv5dl', NULL, '01', '±500kV兴安直流线极1、极2线路', '超高压输电公司南宁局', NULL, NULL, '±500kV兴安直流线极1、极2线路1282#塔至1286#塔。', '宋名晔', '24104', '2', '00034763_cgy', '2', '2022-01-12 16:07:00', NULL, NULL, '湖南湘江电力建设集团有限公司', NULL, NULL, '2021-12-25 10:57:51', '8af935015360a8c601537d056dfc0170', '2022-01-06 17:36:00', NULL, '2021-12-25 20:10:00', NULL, '110F4942CC92522AE05336050A0A2485', NULL, '方刚', '13973818240', '蒋先涛（18人）、杨小平（21人）。', NULL, NULL, '赵纯彬', '2022-01-12 18:00:00', '宋名晔', NULL, '2021-12-26 09:30:00', '500kV平果变电站', NULL, NULL, '湖南湘江电力建设集团有限公司', '2021-12-25 18:40:00', '1', '8af935015360a8c601537d056dfc0170', NULL, '500kV平果变电站', '35', 'EXtCv5dl', '01031815514', NULL, '2', '湖南湘江电力建设集团有限公司', '8af935015360a8c