INSERT INTO `sp_pd_wticket_base` VALUES ('fc712a4557f741ab89305c8686fd8a0d', NULL, '21', '110F4942CBAE522AE05336050A0A2485', NULL, NULL, '2', '1、500kV贺罗Ⅰ线001#、240#塔共2基装、拆永久接地线；\\r\\n2、500kV贺罗Ⅰ线017#、065#、075#塔等共6基，补装销钉；\\r\\n3、500kV贺罗Ⅰ线102#、140#塔共2基，螺栓紧固；\\r\\n4、500kV贺罗Ⅰ线090#、123#塔共2基，导线、光缆断股补修；\\r\\n5、500kV贺罗Ⅰ线188#、236#塔共2基，自爆玻璃绝缘子更换；\\r\\n6、500kV贺罗Ⅰ线009+1#塔共1基，引流板发热处理；\\r\\n7、500kV贺罗Ⅰ线014#塔共1基，绝缘子清扫；\\r\\n8、500kV贺罗Ⅰ线121塔共1基，导线防振锤位移调整；\\r\\n9、500kV贺罗Ⅰ线240#塔共1基，耐张线夹变形处理；\\r\\n10、500kV贺罗Ⅰ线004#、004+1#、008+1#塔等共8基，导线、地线（不含OPGW）悬垂线夹打开检查；\\r\\n11、500kV贺罗Ⅰ线001#、005#、007#塔共3基，RTV（PRTV）涂层外观及憎水性检测；\\r\\n12、500kV贺罗Ⅰ线001#、003#、005#塔等共28基，陶瓷绝缘子零值检测；\\r\\n13、500kV贺罗Ⅰ线002#、056#、059#、129#塔等共6基，盐密、灰密检测(ESDD和NSDD)；\\r\\n14、500kV贺罗Ⅰ线009#、010#塔共2基，塔头端均压螺栓紧固；\\r\\n15、结合检修所到塔位进行人工巡视；\\r\\n16、缺陷消缺前后要拍相片，所到杆塔检查是否有其它新增缺陷；\\r\\n17、所登铁塔进行检查金具锈蚀、磨损、裂纹、变形等情况，并拍照片做好详细记录；\\r\\n18、所登杆塔复合绝缘子及基础附属设施检查拍照。', NULL, '2', NULL, '24400', NULL, '7', NULL, NULL, '2022-01-S1-003', NULL, '0', '梧州变电站', '0105', '2', NULL, '17', '110F4942CBF6522AE05336050A0A2485', '全浩', '超高压', NULL, '2', NULL, '24396', NULL, NULL, '01050202', '01050109', '01050202', 'f35e74fcce3a42399ef3f863c8469f83_489', '010501', '2', NULL, NULL, '2', NULL, 'ce42b2d8b88a4e86bebe146f23e53166', NULL, '2022-01-12 18:24:40', NULL, NULL, NULL, NULL, '2022-01-08 10:42:00', NULL, '24400', '00031429_cgy', '李洪文', '01050202', '黄小朋', NULL, NULL, '110F4942CBF6522AE05336050A0A2485', NULL, '01050109', NULL, '24400', '1', '1', '010501', NULL, '01', '500kV贺罗Ⅰ线', '超高压输电公司梧州局', NULL, NULL, '500kV贺罗Ⅰ线001#-240#塔', '黄永丰', '24386', '2', NULL, '2', '2022-01-12 18:12:00', NULL, NULL, '线路运检九班', NULL, NULL, '2022-01-06 08:46:42', '24396', '2022-01-12 16:35:00', NULL, '2022-01-07 20:26:00', NULL, '110F4942CDF6522AE05336050A0A2485', NULL, NULL, '18377456362', '李晨（4人）、罗宇（4人）、甘瑜（2人）、徐嘉健（2人）、刘波洋（4人）', NULL, NULL, '李洪文', '2022-01-12 18:00:00', '马英杰', NULL, '2022-01-08 08:00:00', '梧州变电站', NULL, NULL, '线路运检九班', NULL, NULL, '24386', NULL, '梧州变电站', '31', '01050109', '01051464986