INSERT INTO `sp_pd_wticket_base` VALUES ('fd7b7404e835411d8974f4251915fee3', NULL, '21', '110F4942CDAF522AE05336050A0A2485', NULL, NULL, '2', '（一）缺陷消除工作：\\r\\n1.验电、装设拆除永久接地线：1699#、1700#塔。\\r\\n2.检查地线挂点紧固情况：1699#塔左右地线大号侧地线挂点。\\r\\n3.检查地线挂点紧固情况：1700#塔左右地线小号侧地线挂点。\\r\\n4.补修1699#极1大号侧3-4间隔棒上方右地线断1股，散股约2米。\\r\\n5.补修1699#极2大号侧9-10间隔棒上方左地线断1股，散股约3米。\\r\\n（二）其他工作：1.结合停电检修所登铁塔进行检查金具锈蚀、磨损、裂纹、变形等情况，并拍照片做好详细记录。 2.按正常巡视和监察巡视要求，对所到杆塔开展巡视工作。', NULL, '2', NULL, '24400', NULL, '7', NULL, NULL, '2022-01-S1-002', NULL, '0', '梧州变电站', '0105', '2', NULL, '14', '00031381_cgy', '全浩', '超高压', NULL, '2', NULL, '24395', NULL, NULL, '01050202', '01050107', '01050202', 'ddc6027a5f604d8989a3affd8fc1c039_577', '010501', '2', NULL, NULL, '2', NULL, 'f7faca3cdd1e49009656b5b04e6e7120', NULL, '2022-01-07 10:38:07', NULL, NULL, NULL, NULL, '2022-01-05 08:30:00', NULL, '24400', '00031429_cgy', '申余彪', '01050202', '陈瑞龙', NULL, NULL, '00031381_cgy', NULL, '01050108', NULL, '24400', '1', '1', '010501', NULL, '01', '±500kV天广直流线', '超高压输电公司梧州局', NULL, NULL, '±500kV天广极1、极2直流线1699#-1700#塔', '黄小朋', '24386', '2', NULL, '2', '2022-01-06 19:18:00', NULL, NULL, '线路运检七班', NULL, NULL, '2022-01-04 14:37:27', '24395', '2022-01-06 19:00:00', NULL, '2022-01-04 20:00:00', NULL, '110F4942CBAE522AE05336050A0A2485', NULL, NULL, '13877409899', '郑沁（11人）、吴志远（2人）', NULL, NULL, '申余彪', '2022-01-06 18:00:00', '马英杰', NULL, '2022-01-05 08:00:00', '梧州变电站', NULL, NULL, '线路运检八班', NULL, NULL, '24386', NULL, '梧州变电站', '28', '01050108', '01051333707', '2022-01-06 19:30:00', '2', '输电管理所', '24394', NULL, NULL, '2022-01-04 18:30:00', '输电管理所', NULL, '2', NULL, '110F4942CE22522AE05336050A0A2485', NULL, NULL, '输电管理所/线路运检八班、一班、二班', NULL, '±500kV天广直流线', NULL, NULL, NULL);
