INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('009935d8c630456d887e5d579b6c4b5b', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 15:26:29', '0109', '无。', NULL, '1、分别在500kV铜昆甲线、铜昆乙线、仁昆甲线、仁昆乙线、乌昆甲线、乌昆乙线、乌昆丙线、龙昆甲线、鲁昆甲线、鲁昆乙线线路进线GIL处悬挂“在此工作！”标示牌； 2、分别在极1低端换流变进线GIL、极2低端换流变进线GIL、极1高端换流变进线GIL、极2高端换流变进线GIL处悬挂“在此工作！”标示牌；3、分别在500kV第一大组交流滤波器ACF1进线GIL、第二大组交流滤波器ACF2进线GIL、第三大组交流滤波器ACF3进线GIL、第四大组交流滤波器ACF4进线GIL处悬挂“在此工作！”标示牌；4、分别在500kV #1站用变、#2站用变进线GIL处悬挂“在此工作！”标示牌；5、在500kV #2M母线高抗进线GIL处悬挂“在此工作！”标示牌。\\r\\n', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交代：完成500kV GIL运行中带电局部放电测试工作，试验结果满足规程要求，无异常。', '01200800', '2022-01-21 15:26:29', NULL, '40', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0368bedca29b43caa2c4b90ec9b6c3c1', NULL, '无。', NULL, NULL, '不停电。');
