INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('07c2761d38344f09a5c62dd3664343fc', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 11:55:50', '0103', '无。', NULL, '在204二楼通信机房C07 广西ODF配线屏、C14 南网网B烽火780B光设备（二）前后分别悬挂“在此工作！”标示牌，将工作屏柜内非工作设备的面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-07 11:55:50', NULL, '28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2ff98ca00ee44ea5915bee4c51281a1c', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('07e4ccedfeb442f4a444be2594a436d2', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-17 08:42:23', '0103', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-17 08:42:23', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '1f7c3275bb614af182a5aaa880036f1b', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('07e894d146fc403f93a8d1f6674f9f0e', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '（1）柳北换流站侧：极I08702，极II08802隔离开关。 （2）龙门换流站侧：极I08105、08121，极II08205、08122隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-29 15:59:09', '0101', NULL, NULL, '（1）柳北换流站侧：极I08702，极II08802隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作”标示牌。 （2）龙门换流站侧：极I08105、08121，极II08205、08122隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '广州局线路工作组组长：郑武略13925168187  工作负责人：李斌明13710020829', '0101100702', '2022-01-29 15:59:09', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, '（1）柳北换流站侧：极I0870217，极II0880217接地刀闸。 （2）龙门换流站侧：极I081217、极II081227接地刀闸。', NULL, 'f1ea948d90564bd6a73463e899a5c7b8', NULL, '1、攀登铁塔时应检查脚钉是否牢固；2、注意观察杆塔上是否有蚂蜂窝，发现后必须立即停止该塔位的所有工作，待蚂蜂窝清除后方可继续开展工作；3、人员在高空作业过程中不得失去安全带的保护；4、现场所有作业人员必须正确佩戴安全帽；5、雷雨、大风不得开展登塔作业；6、登塔作业前，必须做好监护，核对线路名称及塔号；7、在涉及地线上作业时需可靠接地，作业人员离未接地架空地线的距离不得小于0.6米。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('080887fc4b6549d5992eb8947f49c13b', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 17:16:25', '0103', '无。', NULL, '在108通信室A03 #1高频开关电源屏前后分别悬挂“在此工作！”标示牌，将工作屏柜内非工作设备的面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-20 17:16:25', NULL, '14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '41a824446c3b423fbe98fd02e922a380', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('0813171354144ac9beb0646510ff791c', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-01 10:18:56', '0101', '无。', NULL, '在±500kV从西换流站综合楼一楼、二楼、三楼处；主控楼一楼、三楼处；主控楼和综合楼通信机房处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-09-C0-009]', 'EXtClmyc', '2022-01-01 10:18:56', NULL, '52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0bf6284a56bf4e71a05e2d70103f7b23', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('089a354af8484fad985c8ad779c4bc33', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 21:48:35', '0103', '断开380V中央Ⅰ/备用段联络3ZK开关，并摇出至“分离”位置。', NULL, '1、在站用配电室：1P 380V中央Ⅰ段交流配电屏380V中央Ⅰ/备用段联络3ZK开关处悬挂“在此工作！”标示牌；2、将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, '安措变更：因工作需要，工作负责人申请将380V中央Ⅰ/备用段联络3ZK开关并摇至“试验”位置，工作许可人：郭强生，工作负责人：郑和，2022-01-18 17:00。\\r\\n安措恢复：已将380V中央Ⅰ/备用段联络3ZK开关并摇至“分离”位置，工作许可人：郭强生，工作负责人：郑和，2022-01-18 17:20。', '01031102', '2022-01-18 21:48:35', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0020b5441db24828994459cfc67099d3', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('08a4ef2da9a541f9b81b76f65ce7f34d', NULL, '1、高空作业人员不得失去安全带的保护，工作现场应有专人监护； 2、严禁上下抛掷物品；3、现场所有作业人员必须正确佩戴安全帽； 4、线路作业应在良好的天气下进行，遇有雷雨、6级及以上大风、强对流等恶劣气象条件时，应停止工作； 5、邻近或交叉跨越带电线路施工需满足安全作业距离：10kV不小于1米，35kV不小于2.5米，110kV不小于3米，220kV不小于4米，500kV不小于6米，±500kV不小于7.8米；6、±500kV兴安直流线2182#与35kV兴安直流安侧接地极线327#同塔架设，在同塔架设杆塔上开展作业，应保证工器具、传递绳等物品与接地极导线不少于3米的安全距离，如无法保证，应在接地极线路上挂设临时接地线。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 10:16:00', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '0101100502', '2022-01-25 10:16:00', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ee25adcd9cd74b04b720566ce82ead81', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('08b08da93c6046989e75ecadc11e68c1', NULL, NULL, '50512、50521、05105、00102、00102A、05111、00111、05112、00112。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 11:28:47', '0101', '断开50512刀闸控制电源空开MCB4和电机电源空开MCB53、断开50521刀闸控制电源空开MCB4和电机电源空开MCB52、断开05111刀闸控制电源空开F231和电机电源空开F182、断开00111刀闸控制电源空开F231和电机电源空开F182、断开05112刀闸控制电源空开F232和电机电源空开F183、断开00112刀闸控制电源空开F232和电机电源空开F183、断开00102刀闸控制电源F231和电机电源空开F184、断开00102A刀闸控制电源F231和电机电源空开F184、断开05105刀闸控制电源F231和电机电源空开F184，断开极1换流变馈线PT端子箱（=20B05+U1T5）内：送极1直流保护系统1空开F711、送极1换流变保护系统1空开F712、送极1极控系统1空开F713、送极1直流保护系统2空开F721、送极1换流变保护系统2空开F722、送极1极控系统2空开F723、送5051间隔接地控制接口屏空开F725、送极1直流保护系统3空开F731、送极1故障录波空开F732、送20X83+S1谐波装置空开F733、送20Q10+Q2电能计量装置空开F734。', NULL, '1、在50512、50521、05111、00111、05112、00112、00102、00102A、05105刀闸操作机构箱门把手处悬挂“禁止合闸，有人工作”标示牌；在50512刀闸控制电源空开MCB4和电机电源空开MCB53、50521刀闸控制电源空开MCB4和电机电源空开MCB52、05111刀闸控制电源空开F231和电机电源空开F182、00111刀闸控制电源空开F231和电机电源空开F182、05112刀闸控制电源空开F232和电机电源空开F183、00112刀闸控制电源空开F232和电机电源空开F183、00102刀闸控制电源F231和电机电源空开F184、00102A刀闸控制电源F231和电机电源空开F184、05105刀闸控制电源F231和电机电源空开F184处悬挂“禁止合闸，有人工作”标示牌；在极1换流变馈线PT端子箱（=20B05+U1T5）内：送极1直流保护系统1空开F711、送极1换流变保护系统1空开F712、送极1极控系统1空开F713、送极1直流保护系统2空开F721、送极1换流变保护系统2空开F722、送极1极控系统2空开F723、送5051间隔接地控制接口屏空开F725、送极1直流保护系统3空开F731、送极1故障录波空开F732、送20X83+S1谐波装置空开F733、送20Q10+Q2电能计量装置空开F734处分别悬挂“禁止合闸，有人工作”标示牌；2、在极1阀厅、极1换流变、极1平波电抗器、综合水泵房、极1雨淋阀站处悬挂“在此工作”标示牌；在主控楼304房间火灾报警主控屏（＝20XR10+X1）处悬挂“在此工作”标示牌，并在相邻运行设备屏柜粘贴“运行设备”警示带。3、在极1换流变、极1平波电抗器四周装设围栏，并向内悬挂“止步，高压危险”标示牌，并在围栏入口处悬挂“从此进出”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-002]', 'EX03TG', '2022-01-18 11:28:47', NULL, '36', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '01a1526b9c364bd69619e3d808abc813', NULL, '无。', '505167、050127、050117、001207、051107、051057。', NULL, NULL);
