INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('08d218480b85403898eac51e1536bb72', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 17:34:03', '0103', '1、断开380V交流Ⅰ段进线1ZK开关；2、断开380V交流母线联络3ZK开关。', NULL, '1、在380V交流Ⅰ段进线1ZK开关、380V交流母线联络3ZK开关处挂“禁止合闸，有人工作！”标示牌；2、在A4交流配电室：1P 380V交流Ⅰ段配电屏1、2P 380V交流Ⅰ段配电屏2、4P 380V交流母线联络屏悬挂“在此工作！”标示牌，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031102', '2022-01-21 17:34:03', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '22d2c988e2914b1eac84b169868bec37', NULL, '在380V交流Ⅰ段进线1ZK开关靠500kV玉林变电站的串补站Ⅰ 415DL开关来电侧装设一组0.4kV三相短路接地线。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('090386d04f50480b8d6f3ce983fc813e', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 15:11:35', '0109', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '检修交待：已完成部分操作台补漆工作，待后续新油漆到站后开票处理剩余部分。', '01090604', '2022-01-26 15:11:35', NULL, '22', NULL, '1、在普洱换流站主控室、系统分析室悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '6eaa0293256d49eaa46f4fecd51b0257', NULL, NULL, NULL, NULL, NULL);
