INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('0bce0d820d9740bb9108f5db91f99227', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-08 20:38:30', '0107', '无。', NULL, '1、#1继电器室：分别在P69 500kV西罗乙线保护屏1、43P 500kV天西乙线第一套线路保护屏上悬挂“运行设备”标示牌；\\r\\n2、#1继电器室：分别在P65 500kV云南侧第一串测控屏A1、P66 500kV云南侧第一串测控屏A2、P67 500kV云南侧第一串测控屏B1、P68 500kV云南侧第一串测控屏B2、P39 500kV云南侧第三串测控屏A1、P40 500kV云南侧第三串测控屏A2、P41 500kV云南侧第三串测控屏B1、P42 500kV云南侧第三串测控屏B2上悬挂“在此工作！”标示牌； \\r\\n3、#2继电器室：在P29 500kV 5061断路器保护屏上悬挂“运行设备”标示牌； \\r\\n4、#2继电器室：分别在P25 500kV云南侧第六串测控屏A1、P26 500kV云南侧第六串测控屏A2、P27 500kV云南侧第六串测控屏B1、P28 500kV云南侧第六串测控屏B2上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01070102', '2022-01-08 20:38:30', NULL, '13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '96b0c5c8eb984de6b72aa169a35ca924', NULL, '无。', NULL, NULL, '不需要停电。');
