INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('14f7cfb658f54531b8325487654f7766', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-08 21:03:23', '0107', '无。', NULL, '1、中控楼三楼控制设备室 301：分别在P80 A套稳控装置主机屏、P81 B套稳控装置主机屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；\\r\\n2、中控楼二楼载波光纤通信室 209：在D03 稳控装置通信接口屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；\\r\\n3、#1继电器室：分别在P80 A套稳控装置#4从机屏、P81 B套稳控装置#4从机屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；\\r\\n4、#2继电器室：分别在P30 A套稳控装置#3从机屏、P31 B套稳控装置#3从机屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；\\r\\n5、#4继电器室：分别在P8 B套稳控装置#2从机屏、P9 A套稳控装置#2从机屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01070101', '2022-01-08 21:03:23', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ec4aeb9a44d24a4cb6fdbe3b11da8dbe', NULL, '无。', NULL, NULL, '不需要停电。');
