INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('16575f499a254160bad5ea35823c22c4', NULL, NULL, '50831、50832、50822', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-31 10:59:21', '0101', '1、断开5083开关的直流控制电源空开4K1、4K2； 2、断开50831、50832刀闸的电机电源空开SA，断开50822刀闸电机电源空开SA；3、断开500kV穗横甲线线路电压互感器端子箱（=20B08.C+UT5）内以下二次电压空开：穗橫甲线保护2及远跳2 PT小空开A相1MCBa、穗橫甲线保护2及远跳2 PT小空开B相1MCBb、穗橫甲线保护2及远跳2 PT小空开C相1MCBc、穗橫甲线保护1及远跳1 PT小空开A相2MCBa、穗橫甲线保护1及远跳1 PT小空开B相2MCBb、穗橫甲线保护1及远跳1 PT小空开C相2MCBc、穗橫甲线故障录波PT小空开A相4MCBa、穗橫甲线故障录波PT小空开B相4MCBb、穗橫甲线故障录波PT小空开C相4MCBc、穗橫甲线断路器保护PT小空开A相5MCBa、穗橫甲线断路器保护PT小空开B相5MCBb、穗橫甲线断路器保护PT小空开C相5MCBc、穗橫甲线计量PT空开A相6MCBa、穗橫甲线计量PT空开B相6MCBb、穗橫甲线计量PT空开C相6MCBc、穗橫甲线测量PT空开A相7MCBa、穗橫甲线测量PT空开B相7MCBb、穗橫甲线测量PT空开C相7MCBc。', NULL, '（1）在50832刀闸操作把手处悬挂“禁止合闸，有人工作”标示牌；（2）在50831、50822刀闸操作把手处悬挂“禁止合闸，线路有人工作”标示牌； （3）在50832刀闸电机电源空开SA，5083开关的直流控制电源空开4K1、4K2处悬挂“禁止合闸，有人工作”标示牌；（4）在50831、50822刀闸电机电源空开SA，穗横甲线线路电压互感器端子箱（=20B08.C+UT5）内：穗橫甲线保护2及远跳2 PT小空开A相1MCBa、穗橫甲线保护2及远跳2 PT小空开B相1MCBb、穗橫甲线保护2及远跳2 PT小空开C相1MCBc、穗橫甲线保护1及远跳1 PT小空开A相2MCBa、穗橫甲线保护1及远跳1 PT小空开B相2MCBb、穗橫甲线保护1及远跳1 PT小空开C相2MCBc、穗橫甲线故障录波PT小空开A相4MCBa、穗橫甲线故障录波PT小空开B相4MCBb、穗橫甲线故障录波PT小空开C相4MCBc、穗橫甲线断路器保护PT小空开A相5MCBa、穗橫甲线断路器保护PT小空开B相5MCBb、穗橫甲线断路器保护PT小空开C相5MCBc、穗橫甲线计量PT空开A相6MCBa、穗橫甲线计量PT空开B相6MCBb、穗橫甲线计量PT空开C相6MCBc、穗橫甲线测量PT空开A相7MCBa、穗橫甲线测量PT空开B相7MCBb、穗橫甲线测量PT空开C相7MCBc处悬挂“禁止合闸，线路有人工作”标示牌； （5）在500kV穗橫甲线开关5083、500kV 穗橫甲线5083开关电流互感器T1、500kV穗橫甲线线路电压互感器T5、500kV穗橫甲线线路避雷器F1体处悬挂“在此工作”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '在500kV穗横甲线线路避雷器进线处装设一组500kV临时接地线。工作过程中由于试验需要，需运行人员配合分合508317、508327接地刀闸。', '01012007', '2022-01-31 10:59:21', NULL, '29', NULL, NULL, NULL, NULL, '5083', NULL, NULL, NULL, 'c2407fdbf20248429a199d004d574214', NULL, '无。', '508367、508317、508327。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('1657fa5b463942f1b3caab71f8890c72', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 21:31:44', '0101', '无。', NULL, '分别在主控制楼极一设备室（207 室）、极二设备室（205 室）、控制楼一楼极二阀冷室（101 室）、控制楼一楼极一阀冷室（102 室）、控制楼一楼低压2 室（103 室）、控制楼一楼中压2 室（104 室）、控制楼一楼中压1 室（105 室）、控制楼一楼低压1 室（106 室）、控制楼一楼充电机2 室（107 室）、控制楼一楼蓄电池3 室（109 室）、控制楼一楼蓄电池1 室（110 室）、控制楼一楼蓄电池2 室（111 室）、控制楼一楼充电机室1（112 室）、控制楼一楼充电机室1（113 室）、#1继保室、#2 继保室、#3继保室、#4 继保室、#5 继保室内所有控制保护和低压直流相关屏柜前后悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。在#1继保室、#2 继保室、#3继保室蓄电池室悬挂“在此工作”标示牌。在主控楼阀厅过道阀厅车停放处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012001', '2022-01-21 21:31:44', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7a52c18284274a7fb16182e8bdea7014', NULL, '无。', NULL, NULL, '不需要停电。');
