INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('1e5e095c3c0e4a8e9d1ae1b4294884df', NULL, NULL, '95444。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 10:34:08', '0101', '1、断开95444控制电源DK23及电机电源DK43；2、断开220kV东象甲线电容式互感器T5的二次侧空开DK31。', NULL, '1、在95444刀闸就地操作把手处悬挂“禁止合闸，有人工作”标示牌；\\r\\n2、在95444控制电源DK23及电机电源DK43空开处悬挂“禁止合闸，有人工作”标示牌；\\r\\n3、在220kV东象甲线电容式互感器T5的二次侧空开DK31空开处悬挂“禁止合闸，有人工作”标示牌；\\r\\n4、在220kV东象甲线GIS出线套管、线路电压互感器、避雷器处分别悬挂“在此工作”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、在220kV东象甲线电容式互感器出线侧装设一组220kV临时接地线；[交底单号：2022-01-C0-001]', 'EXtClm04', '2022-01-11 10:34:08', NULL, '47', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'c5d9f3d03c614fcfaf131ad319efd81d', NULL, '无。', '954440。', NULL, NULL);
