INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('2eded163dbc74ce9b2032cc49160010b', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 10:49:50', '0109', '无。', NULL, '1、分别在51继电保护小室、52继电保护小室、直流继电器室门口悬挂“在此工作！”标示牌；2、分别在主控楼一楼极1阀冷控制保护室、极2阀冷控制保护室门口悬挂“在此工作！”标示牌；3、分别在主控楼二楼站公用控制保护设备室、通信机房、极1控制保护设备室、极2控制保护设备室门口悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交代：完成直流控制专业设备巡视工作，设备均正常运行。', '01090621', '2022-01-19 10:49:50', NULL, '30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1eb4e33670ef44258325239d78276e4e', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('2efe94bd7c0645f7b20ebf49e1903b26', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 18:38:45', '0104', '1、在极2控制保护室：12P 极2直流母线联络屏：合上14ZK 联络开关、断开22ZK B段母线进线开关； 2、在极2控制保护室：15P 极2直流充电机屏2：断开21ZK #2充电机输出转换开关； 3、在极2控制保护室：8P 极2直流充电机屏3：断开31ZK #3充电机输出转换开关。', NULL, '1、分别在极2控制保护室：12P 极2直流母线联络屏、15P 极2直流充电机屏2前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识； 2、在极2蓄电池室2门把手处悬挂“在此工作”标示牌； 3、分别在极2控制保护室：12P 极2直流母线联络屏：22ZK B段母线进线开关，15P 极2直流充电机屏2：21ZK #2充电机输出转换开关，8P 极2直流充电机屏3：31ZK #3充电机输出转换开关上悬挂“禁止合闸，有人工作”标示牌;4、分别在极2控制保护室：12P 极2直流母线联络屏:14ZK联络开关、12ZK A段母线进线开关操作把手、13ZK#1蓄电池充放电开关上用红色标签粘贴“禁止操作”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-020]', 'EXtCv5RF', '2022-01-12 18:38:45', NULL, '41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '22b23dcf6ad74b2cb1d652b440fabb84', NULL, '无。', NULL, NULL, '不需要停电。');
