INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('36e6fd1a2f0e46b499a09296aaebbfd9', NULL, NULL, '50411、50432、5041DK1、5041RJ。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-03 22:52:10', '0104', '1、断开50411、50432、5041DK1隔离开关电机电源QF1空气开关及控制电源QF3空气开关。 2、断开500kV龙河甲线5041RJ融冰隔离开关电机电源F1空气开关及控制电源F3空气开关。 3、断开500kV 龙河甲线线路CVT端子箱内：第一套线路保护二次电压MCB1空气开关、测量回路二次电压MCB2空气开关、第二套线路保护二次电压MCB3空气开关、测控回路二次电压MCB4空气开关、录波二次电压MCB5空气开关、融冰五防闭锁MCB9空气开关。', NULL, '1、分别在50411、50432、5041DK1、5041RJ隔离开关现场操作机构处悬挂“禁止合闸， 有人工作”标示牌，并在后台监控界面相应位置作“禁止合闸， 有人工作”标识； 2、在500kV 龙河甲线线路CVT端子箱内：第一套线路保护二次电压MCB1空气开关、测量回路二次电压MCB2空气开关、第二套线路保护二次电压MCB3空气开关、测控回路二次电压MCB4空气开关、录波二次电压MCB5空气开关、融冰五防闭锁MCB9空气开关设置“禁止合闸 有人工作”标识。 3、在相关停电设备工作区域周围装设安全围栏，围栏内设备包括500kV龙河甲线线路CVT本体及端子箱，并在围栏上向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌。 4、在50411、50432、5041DK1、5041RJ隔离开关装设“检修隔离”锁。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-014]', 'EXtCuSGl', '2022-01-03 22:52:10', NULL, '32', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'b9a692bba54d4444992370ab134d2589', NULL, '无。', '1、504167，共1把； 2、在500kV龙河甲线5041RJ融冰隔离开关静触头导线处装设500kV接地线1组，共1组。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('371aaa3a8c6f4fe5befe0229bc45f78f', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-02 16:20:27', '0107', '无。', NULL, '1、400V开关室106： 在P30=10NE02+NE07 404M 400V动力中心2负荷屏7右侧预留空位放置“在此工作！”标示牌；\\r\\n2、在#1继电器室电缆层门上悬挂“在此工作！”标示牌；\\r\\n3、在#2继电器室电缆层门上悬挂“在此工作！”标示牌；\\r\\n4、在#3继电器室电缆层门上悬挂“在此工作！”标示牌；\\r\\n5、在#4继电器室电缆层门上悬挂“在此工作！”标示牌；\\r\\n6、在传达室门上悬挂“在此工作！”标示牌；\\r\\n7、分别在#1继电器室电缆层、#2继电器室电缆层、#3继电器室电缆层、#4继电器室电缆层、传达室至主控楼电缆层电缆沟处放置“在此工作！”标示牌；\\r\\n8、在中控楼电缆层门把手上悬挂“在此工作！”标示牌；\\r\\n9、在P30=10NE02+NE07 404M 400V动力中心2负荷屏7上悬挂“运行屏柜”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-032]\\r\\n补充安全交代：杨武，陈光文，程世科，罗福全 2021.12.19 08:40\\r\\n补充安全交代：汪启和、黄军、陈涛，易德飞，任永学，左应隆，王永文、黄应松，易德海，易德新，金武启，成先国 2021.12.25 07:44\\r\\n补充安全交代：王万坤，李斌 2021.12.28 08:10', 'EX03GS', '2022-01-02 16:20:27', NULL, '117', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a7476b431287428c8e5d6544f8059ff0', NULL, '无。', NULL, NULL, '不需要停电。');
