INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('37b58167e7c54813b5e1d905d2828476', NULL, NULL, '50911、50912。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 14:38:39', '0109', '1、分别断开500kV极2高端换流变5091断路器汇控箱内50911隔离开关电机电源空气开关8A41和控制电源空气开关8A31； 2、分别断开500kV极2高端换流变5091断路器汇控箱内50912隔离开关电机电源空气开关8A43和控制电源空气开关8A33； 3、分别断开51保护小室=10B09.A+R1极2高端换流变5091断路器保护屏上第一路操作电源空气开关4K1、第二路操作电源空气开关4K2。', NULL, '1、分别在500kV极2高端换流变5091断路器汇控箱内50911隔离开关电机电源空气开关8A41和控制电源空气开关8A31上悬挂“禁止合闸，有人工作！”标示牌； \\r\\n2、分别在500kV极2高端换流变5091断路器汇控箱内50912隔离开关电机电源空气开关8A43和控制电源空气开关8A33上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、分别在51保护小室=10B09.A+R1极2高端换流变5091断路器保护屏上第一路操作电源空气开关4K1 、第二路操作电源空气开关4K2上悬挂“禁止合闸，有人工作！”标示牌； \\r\\n4、在500kV极2高端换流变5091断路器四周装设遮栏，遮栏上向内悬挂“止步，高压危险！”标示 牌，遮栏出入口处悬挂“从此进出！”、“在此工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '检修交代：已完成测试，测试数据无异常。 ', '01090601', '2022-01-07 14:38:39', NULL, '24', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'b46134c9352c48388643c157a20b6dd9', NULL, '无。', '509117、509127。', NULL, NULL);
