INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('399a442dc4b24ff8892fc5d93364f01d', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 16:58:14', '0102', '无。', NULL, '1、分别在通信机房17P 软交换系统设备屏、 25P 核心网络设备屏、4P 贵阳生产指挥中心ODF配线屏1、5P 贵阳生产指挥中心ODF配线屏2悬挂“在此工作！”标示牌； 2、分别在通信机房16P B套高频开关电源屏、26P 汇聚网络设备屏、18P 视频会议设备屏、3P南网调度程控交换机设备屏、6P 南网ODF光纤配线屏前后悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人联系电话：13985524423。 ', '01020704', '2022-01-20 16:58:14', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '96febe4792294ebfa693d2f01c1ea1de', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('39d03b04f7574fb18e5c05b37cb27617', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-16 21:32:20', '0104', '退出2P 220kV桂渡Ⅰ线主二保护屏以下连接片：1LP13（主二保护PSL602GCN 投光纤纵联保护）。', NULL, '1、在21保护小室：2P 220kV桂渡Ⅰ线主二保护屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识。 2、分别在通信机房：B08 广西综合配线架、C06 220kV保护通信接口柜（二）前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；在C06 200kV保护通信接口柜（二）内的220kV桂渡Ⅱ线主二通道一光纤接口装置GXC-64/2M、220kV桂木Ⅱ线主二通道光纤接口装置MUX-2MC、220kV桂木Ⅰ线主二通道光纤接口装置MUX-2MD、220kV桂大Ⅰ线主二通道光纤接口装置MUX-2MD、220kV桂大Ⅱ线主二通道光纤接口装置MUX-2MD、220kV桂渡Ⅲ线主二通道二光纤接口装置OTEC-2M前后粘贴“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040813', '2022-01-16 21:32:20', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4017293d779545d685f1c484b62cac3d', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('39eb4c224e424244803d9f4c8579ba19', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、拉开兴仁换流站±500kV兴安直流线极1 05105、05121隔离开关； 2、拉开兴仁换流站±500kV兴安直流线极2 05205、05122隔离开关。 3、拉开宝安换流站±500kV兴安直流线极1 05105、05121隔离开关； 4、拉开宝安换流站±500kV兴安直流线极2 05205、05122隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-11 21:11:16', '0106', NULL, NULL, '1、在兴仁换流站±500kV兴安直流线极1 05105、05121隔离开关现场机构箱及其主控室计算机监控系统操作处分别悬挂“禁止合闸，线路有人工作！”标示牌； 2、在兴仁换流站±500kV兴安直流线极2 05205、05122隔离开关现场机构箱及其主控室计算机监控系统操作处分别悬挂“禁止合闸，线路有人工作！”标示牌。 3、在宝安换流站±500kV兴安直流线极1 05105、05121隔离开关现场机构箱及其主控室计算机监控系统操作处分别悬挂“禁止合闸，线路有人工作！”标示牌； 4、在宝安换流站±500kV兴安直流线极2 05205、05122隔离开关现场机构箱及其主控室计算机监控系统操作处分别悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '百色局现场跟踪监护负责人： 梁飞标   联系电话：18778674408； 500kV砚山串补站值班联系电话：18276668076；[交底单号：2022-01-S0-003]', 'EX0315', '2022-01-11 21:11:16', NULL, '67', NULL, NULL, NULL, NULL, NULL, NULL, '1、合上兴仁换流站±500kV兴安直流线极1 051217接地刀闸； 2、合上兴仁换流站±500kV兴安直流线极2 051227接地刀闸。 3、合上宝安换流站±500kV兴安直流线极1 051217接地刀闸； 4、合上宝安换流站±500kV兴安直流线极2 051227接地刀闸。', NULL, 'b3eedec81e764702a64bbb76ceabe7ae', NULL, '① 、得到±500kV兴安直流线停电许可工作命令后，方可开始工作；②、登塔前，必须核对线路名称、塔号无误方可登塔作业，防止误登带电线路；③、验电、装设、拆除接地线时，应戴绝缘手套，工作监护人必须对工作人员的安全认真监护，及时纠正不安全因素；④、现场所有工作人员必须戴安全帽，塔上人员应使用安全带，塔上、线上转位时，不得失去安全带的保护；⑤、同一塔上作业时，不允许同一垂直线多人上、下塔或作业，以防掉物伤人，上下塔过程中及塔上作业严禁吸烟；⑥、塔上有蜂窝、浓雾，天空有雷云、雨天、大风严禁登塔作业；⑦、高空作业所用的工器具和材料，应放在工具包中或用传递绳绑牢后上下传递，严禁抛物。上下传递工器具材料时应将材料绑扎牢固，传递工器具材料时，地面人员必须站离所传递物垂直点下方，防止坠物伤人；⑧、防止感应电伤害：根据《安规》7.4.1.4条规定，工作地段有临近、平行、交叉跨越及同杆塔线路，需要接触或接近停电线路的导线工作时，应装设接地线或使用个人保安线（作业结束后拆除）；⑨、工作完工后，小组负责人确认工作地点所装设接地线已全部拆除，线路上无异物、无本小组工作人员，已具备送电条件后，向工作总负责人汇报终结工作。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a12c7a59bf34768a7bcaae1bb3f03c4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-04 16:36:24', '0108', '无。', NULL, '1、在500kV #1通信机房113 C12 调度数据网设备屏上悬挂“在此工作！”标示牌，并在与C12 调度数据网设备屏相邻的屏柜前后悬挂“运行设备！”标示牌并粘贴红色胶带；\\r\\n2、在主控楼计算机室311 10P 主控楼计算机室站控层网络设备及公用测控屏、2P 500kV智能远动机屏上分别悬挂“在此工作！”标示牌，并在与10P 主控楼计算机室站控层网络设备及公用测控屏、2P 500kV智能远动机屏相邻的屏柜前后分别悬挂“运行设备！”标示牌并粘贴红色胶带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01080806', '2022-01-04 16:36:24', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1edb68a2212f4be2a5b9de5a648a1a77', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a1417d30ab84390bda02ba321b88a39', NULL, NULL, '50721、50722、50731、50732。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 00:25:04', '0101', '1、退出500kV 5073断路器保护屏（20P）内以下压板：15LP16（PSL 632C保护失灵启动#2M母线A套保护1）、15LP176（PSL 632C保护失灵启动#2M母线B套保护1）、15LP18PSL（632C保护失灵启动#2M母线A套保护2）、15LP19（PSL 632C保护失灵启动#2M母线B套保护2）、将重合闸方式切换把手15QK切换至“停用”位置；2、断开50721、50722、50731、50732刀闸控制电源8D3和电机电源Q1 ；', NULL, '1、分别在500kV #2继保室：500kV 5073断路器保护屏（20P）、500kV电度表屏2（58P） 屏柜前后悬挂“在此工作！”标示牌，并在相邻屏柜粘贴“运行设备”警示带；2、在500kV交流场：500kV曲花乙线5073开关就地汇控柜处悬挂“在此工作！”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险！”标示牌，围栏围至附近道路并预留出入口，在围栏入口处悬挂“从此进出！”标示牌；3、在50721、50722、50731、50732刀闸操作把手、控制电源8D3和电机电源Q1上悬挂“禁止合闸，有人工作！”标示牌； ', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作过程中需多次分合5073开关。', '01012009', '2022-01-25 00:25:04', NULL, '21', NULL, NULL, NULL, NULL, '5072、5073。', NULL, NULL, NULL, '8c69082b3ed64395b8534411c87eb8db', NULL, '将50721、50732刀闸实施机构闭锁。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a2b6795e88f423f954c7806479567ec', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 14:55:49', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-021]', 'EXtClm04', '2022-01-07 14:55:49', NULL, '40', NULL, '在35kV福山线户外共沟部分新建电缆专沟处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '75e604f3cf7a40d8b8e0c7e5dec2da35', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a32af4c3cb148eda8c3b5c27589a5b2', NULL, NULL, '50111、50211、50311、50421、50511、50611、50711、50821、50921。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-29 09:08:37', '0101', '1、断开50111、50211、50311、50611、50711、50921、50821刀闸控制电源8D3以及电机电源Q1；\\r\\n2、断开50421刀闸控制电源8D1以及电机电源Q1；\\r\\n3、断开50511刀闸控制电源Q811D及电机电源Q812；\\r\\n4、断开500kV#1M母线CVT二次端子箱内以下二次空开：#1M监控交流电压1ZKK、#1M保护交流电压1 2ZKK、#1M保护交流电压2 3ZKK、5011断路器保护交流电压8MCBa1、5021断路器保护交流电压8MCBa2、5031断路器保护交流电压8MCBa3、5042断路器保护交流电压8MCBa4、5051断路器保护交流电压8MCBa5、5061断路器保护交流电压8MCBa6、5071断路器保护交流电压8MCBa7、5082断路器保护交流电压8MCBa8、5092断路器保护交流电压8MCBa9。', NULL, '1、在5081 5091开关安装处四周装设安全围栏，安全围栏延伸至50821刀闸处，在围栏入口处悬挂“在此工作!”、“从此进出!”标示牌，并向内悬挂“止步，高压危险!”标示牌；在50821套管处悬挂“在此工作!”标示牌。\\r\\n2、分别在50111、50211、50311、50421、50511、50611、50711、50821、50921刀闸操作把手处分别悬挂“禁止合闸，有人工作!”标示牌，分别在50111、50211、50311、50421、50511、50611、50711、50821、50921刀闸控制电源空开8D3以及电机电源Q1处分别悬挂“禁止合闸，有人工作!”标示牌，分别在50421刀闸控制电源8D1以及电机电源Q1处分别悬挂“禁止合闸，有人工作!”标示牌；在50511刀闸控制电源Q811D及电机电源Q812处分别悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、分别在500kV#1M母线CVT二次端子箱内以下二次空开：#1M监控交流电压1ZKK、#1M保护交流电压1 2ZKK、#1M保护交流电压2 3ZKK、5011断路器保护交流电压8MCBa1、5021断路器保护交流电压8MCBa2、5031断路器保护交流电压8MCBa3、5042断路器保护交流电压8MCBa4、5051断路器保护交流电压8MCBa5、5061断路器保护交流电压8MCBa6、5071断路器保护交流电压8MCBa7、5082断路器保护交流电压8MCBa8、5092断路器保护交流电压8MCBa9处分别悬挂“禁止合闸，有人工作!”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-026]', 'EXtCIfT3', '2022-01-29 09:08:37', NULL, '58', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'ae90d4ff0a0d4874a80a9f29313ba7b8', NULL, '1、提前核对设备名称和编号，严禁擅入非工作区域；2、室外作业或有磕碰、坠落、坠物危险时提前戴好安全帽；3、在指定地点工作，严禁扩大工作范围，严禁未经许可擅自改变安全措施；4、作业过程中，工作人员需全程佩戴口罩，确保有效监护下保持适当距离；5、吊车使用过程中应注意与带电设备的安全距离。6、吊车接地，严格执行起吊“十不准”。', '5117、5127、5137。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a428d14bbd14b2b8fffae24d4831d75', NULL, NULL, 'S20612、S20613。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 23:53:21', '0106', '1、断开220kV百松Ⅱ线S20612、S20613刀闸机构箱内电机电源Q1空气开关；\\r\\n2、断开220kV百松Ⅱ线综合端子箱内S20612刀闸控制电源QF2空气开关、S20613刀闸控制电源QF1空气开关、S20616刀闸控制电源QF4空气开关；\\r\\n3、断开220kV百松Ⅱ线S2061开关A、B、C相机构箱电机电源F1空气开关；\\r\\n4、断开220kV保护小室20P 220kV百松Ⅱ线主一保护屏S2061开关第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关；\\r\\n5、断开220kV保护小室19P 220kV百德Ⅱ线/百松Ⅱ线测控屏220kV百松Ⅱ线遥信电源21MCB空气开关；\\r\\n6、断开220kV百松Ⅱ线CVT端子箱内如下二次空开：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关。', NULL, '1、在S20612、S20613刀闸机构箱分别悬挂“禁止合闸，有人工作”标示牌，并在主控室计算机监控系统S20612、S20613刀闸操作处分别设置“禁止合闸，有人工作”标示；\\r\\n2、在S20612、S20613刀闸机构箱电机电源Q1空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n3、在220kV百松Ⅱ线综合端子箱内S20612刀闸控制电源QF2空气开关、S20613刀闸控制电源QF1空气开关、S20616刀闸控制电源QF4空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n4、在220kV百松Ⅱ线S2061开关A、B、C相机构箱电机电源F1空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n5、在220kV保护小室20P 220kV百松Ⅱ线主一保护屏S2061开关第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n6、在220kV保护小室19P 220kV百德Ⅱ线/百松Ⅱ线测控屏220kV百松Ⅱ线遥信电源21MCB空气开关粘贴“禁止合闸，有人工作”警示标签；\\r\\n7、在220kV百松Ⅱ线CVT端子箱内如下二次空开：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n8、在220kV百松Ⅱ线CVT、S2061开关、S2061CT、S20612刀闸、S20613刀闸、S206127地刀、S20616刀闸、S206167地刀、S2061617地刀分别悬挂“在此工作”标示牌，并在其四周装设向内标示“止步，高压危险”的安全遮栏，在安全遮栏的出入口处悬挂“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '补充安全交代：黄文祥    时间：2022年01月04日14时40分\\r\\n杨盛、梁飞耀、王金宏 时间：2022年01月09日10时11分  \\r\\n陈超辉  时间：2022年01月09日10时14分\\r\\n韦桂喜、赵叙森 2022年01月10日14时36分\\r\\n安措变更：\\r\\n1、因工作需要，①、申请拉开S206127、S206167、S2061617地刀；②、合上220kV百松Ⅱ线S2061开关A、B、C相机构箱电机电源F1空气开关； ③、合上220kV保护小室20P 220kV百松Ⅱ线主一保护屏S2061开关第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关； ④、合上220kV保护小室19P 220kV百德Ⅱ线/百松Ⅱ线测控屏220kV百松Ⅱ线遥信电源21MCB空气开关。\\r\\n工作负责人： 农文辉   工作许可人：王杰     执行时间： 2022年01月04日17时19分\\r\\n2、工作结束，①、申请合上S206127、S206167、S2061617地刀；②、断开220kV百松Ⅱ线S2061开关A、B、C相机构箱电机电源F1空气开关； ③、断开220kV保护小室20P 220kV百松Ⅱ线主一保护屏S2061开关第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关； ④、断开220kV保护小室19P 220kV百德Ⅱ线/百松Ⅱ线测控屏220kV百松Ⅱ线遥信电源21MCB空气开关。\\r\\n工作负责人： 杨录乐   工作许可人：岑梦杰     执行时间： 2022年01月10日17时40分', '01060405', '2022-01-10 23:53:21', NULL, '58', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '91f7413b5d6d48999d0ab4a4c210da4a', NULL, '无。', 'S206127、S206167、S2061617，在220kV百松Ⅱ线CVT一次导线处装设一组220kV三相短路接地线。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a482044876f4ed299d0ffe5a5a6db9e', NULL, NULL, 'S20551、S20552。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 21:51:48', '0106', '1、断开220kV百老Ⅱ线S20551、S20552刀闸机构箱内电机电源QF1空气开关和控制电源QF3空气开关；\\r\\n2、断开220kV百老Ⅱ线S20556刀闸机构箱内控制电源QF3空气开关；\\r\\n3、断开220kV百老Ⅱ线S2055开关A、B、C相机构箱内电机电源F1空气开关；\\r\\n4、断开220kV保护小室28P 220kV百老Ⅱ线主一保护屏S2055第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关；\\r\\n5、断开220kV百老Ⅱ线CVT端子箱内如下二次空开：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关。', NULL, '1、在S20551、S20552刀闸机构箱分别悬挂“禁止合闸，有人工作”标示牌，并在主控室计算机监控系统S20551、S20552刀闸操作处分别设置“禁止合闸，有人工作”标示；\\r\\n2、在S20551、S20552刀闸机构箱内电机电源QF1空气开关和控制电源QF3空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n3、在S20556刀闸机构箱内控制电源QF3空气开关粘贴“禁止合闸，有人工作”警示标签；\\r\\n4、在220kV百老Ⅱ线S2055开关A、B、C相机构箱内电机电源F1空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n5、在220kV保护小室28P 220kV百老Ⅱ线主一保护屏S2055第一组操作回路电源4K1空气开关和第二组操作回路电源4K2空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n6、在220kV百老Ⅱ线CVT端子箱内如下二次空开：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关分别粘贴“禁止合闸，有人工作”警示标签；\\r\\n7、在220kV百老Ⅱ线CVT、S2055开关、S2055CT、S20551刀闸、S20552刀闸、S20556刀闸、S205527地刀、S205567地刀、S2055617地刀分别悬挂“在此工作”标示牌，并在其四周装设向内标示“止步，高压危险”的安全遮栏，在安全遮栏的出入口处悬挂“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '010604', '2022-01-18 21:51:48', NULL, '25', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '1b275b70c8674c9887ec7514da823f11', NULL, '无。', 'S205527、S205567、S2055617，在220kV百老Ⅱ线CVT一次导线处装设一组220kV三相短路接地线。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a4d6f2f4faa414cad6414b2759a80ee', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 17:38:38', '0107', '无。', NULL, '1、极1及公用电子设备间303：分别在P3 极1极控系统1、P4 极1极控系统2上悬挂“在此工作！”标示牌；\\r\\n2、极1及公用电子设备间303：分别在P2 极1保护接口屏、P5 极1阀基电子设备屏1上悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '已进行安全交代：周仁伟  2022.01.14  09：00', '01070111', '2022-01-14 17:38:38', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fa123b3a08214b1596128e7dde610b78', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a6da6adb1214b2ea3f61b18bddd0459', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-18 14:12:59', '0104', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-18 14:12:59', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '3789b0bf0c544cfeb62e37f03dccebb6', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3a7a2b671fbc46398b5a759de0fb81ef', NULL, NULL, '50521、50532、50536。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 21:28:17', '0104', '1、断开50521隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n2、断开50532隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n3、断开50536隔离开关控制电源空气开关QF2、电机电源空气开关QF1。', NULL, '1、在工作区域装设安全围栏，围栏内的设备包括：500kV平来Ⅱ线5053断路器、500kV第五串联络5052断路器三相本体，围栏向内悬挂“止步，高压危险！”标示牌，围栏内面向围栏入口明显处悬挂“在此工作”标示牌，在围栏入口处悬挂“从此进出”标示牌。\\r\\n2、分别在50521、50532、50536隔离开关现场操作机构处悬挂“禁止合闸，有人工作”标示牌，并在监控界面对应位置作“禁止合闸，有人工作”标识；\\r\\n3、将50521、50532、50536隔离开关机构箱常规锁更换为“检修隔离”锁。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-008]安全教育补充签名：文鑫2022-01-18 19:30', 'EXtCuSGl', '2022-01-22 21:28:17', NULL, '43', NULL, NULL, NULL, NULL, '无', NULL, NULL, NULL, '37a86e567a1a4ad49a5eedfb535065f4', NULL, '无', '505217、505327、505367接地刀闸，共3把。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3aab40be49e3474d887b86257b469cd5', NULL, '1、本项工作是在线路带电运行情况下进行，本项工作可以不退出再启动装置。2、作业人员在作业前应被告知作业现场和工作岗位存在的危险因素、防范措施及应急措施。 3、登塔作业前，检查人员精神状态是否良好，核对线路名称和工作地点杆塔号是否正确。攀登杆塔前，应检查基础是否牢固。攀登杆塔及塔上移位过程中，应检查脚钉、爬梯、防坠装置、塔材是否牢固。 4、作业人员应正确使用安全帽和安全带。安全带应采用高挂低用的方式，不应系挂在移动、锋利或不牢固的物件上。攀登杆塔和转移位置时不应失去安全带的保护。作业过程中，应随时检查安全带是否拴牢。5、在进行高处作业时，除有关人员外，不准他人在工作地点的垂直下方及坠物可能落到的地方通行或逗留，防止落物伤人。 6、塔上作业人员应穿全套合格的屏蔽服，登塔前应检查屏蔽服各部位连接是否良好且导电鞋的电阻值不得大于500Ω，塔上作业人员与带电导线保持大于10.1米的安全距离。7、绝缘架空地线（包括OPGW）应视为带电体，作业人员与绝缘架空地线（包括OPGW光缆）保持大于0.4米的安全距离，在绝缘架空地线上作业，应用接地线或个人保安地线将其可靠接地。8、带电作业应在良好天气下进行。如遇雷电、雪、雹、雨、雾等，不应进行带电作业。风力大于5级，或湿度大于80%时，不宜进行带电作业。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 13:20:39', '0107', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01070208', '2022-01-07 13:20:39', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '607745e9e1f745d685280323c19c2662', NULL, '①登塔作业前，应核对线路名称和工作地点杆塔号是否正确；②安全带应采用高挂低用的方式，不应系挂在移动、锋利或不牢固的物件上。攀登杆塔和转移位置时不应失去安全带的保护；③高空作业不得失去监护人的监护。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3abe7ef3efec4885acc4917dfaa38c56', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 16:54:16', '0101', '无。', NULL, '在5821刀闸就地操作机构箱处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作过程中需临时分合5821刀闸电机电源空开SA及控制电源空开F212。', '01012004', '2022-01-26 16:54:16', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a2042e2494d44796b97d78a4cff7572a', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3ad2690d65c04e408ad5e400b754936a', NULL, NULL, '20583、20584。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-03 09:22:12', '0104', '1、断开20583、20584隔离开关电机电源空气开关QF1及控制电源空气开关QF2；\\r\\n2、断开220kV桂挡Ⅱ线线路CVT端子箱：电度表A相电压空气开关MCB11、电度表B相电压空气开关MCB12、电度表C相电压空气开关MCB13、第一套保护和测控A相电压空气开关MCB21、第一套保护和测控B相电压空气开关MCB22、第一套保护和测控C相电压空气开关MCB23、第二套保护和录波A相电压空气开关MCB31、第二套保护和录波B相电压空气开关MCB32、第二套保护和录波C相电压空气开关MCB33；\\r\\n3、退出3P 220kV桂挡Ⅱ线主一保护屏中以下连接片：1LP10（主一保护RCS-931AM启动2058断路器A相失灵）、1LP11（主一保护RCS-931AM启动2058断路器B相失灵）、1LP12（主一保护RCS-931AM启动2058断路器C相失灵）、4LP1（2058断路器操作箱启动#3M、#4M第一套母线保护失灵）、4LP2（2058断路器操作箱启动#3M、#4M第二套母线保护失灵）；\\r\\n4、退出4P 220kV桂挡Ⅱ线主二保护屏中以下连接片：1LP10（主二保护RCS-902CFZV启动2058断路器A相失灵）、1LP11（主二保护RCS-902CFZV启动2058断路器B相失灵）、1LP12（主二保护RCS-902CFZV启动2058断路器C相失灵）。', NULL, '1、在20583、20584隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，并在监控系统监控界面对应位置作“禁止合闸 有人工作”标识；\\r\\n2、在20583、20584隔离开关机构箱正门处装设检修隔离锁；\\r\\n3、在220kV桂挡Ⅱ线线路CVT端子箱：电度表A相电压空气开关MCB11、电度表B相电压空气开关MCB12、电度表C相电压空气开关MCB13、第一套保护和测控A相电压空气开关MCB21、第一套保护和测控B相电压空气开关MCB22、第一套保护和测控C相电压空气开关MCB23、第二套保护和录波A相压空气开关MCB31、第二套保护和录波B相电压空气开关MCB32、第二套保护和录波C相电压空气开关MCB33上粘贴“禁合闸 有人工作”标识；\\r\\n4、分别在22保护小室：3P 220kV桂挡Ⅱ线主一保护屏、4P 220kV桂挡Ⅱ线主二保护屏、5P 220kV线路测控屏（四）、6P 220kV线路测控屏（五）、15P PMU同步相量测量装置屏、17P 22小室公用测控及监控通信屏、18P 110V直流分屏（一）、19P 110V直流分屏（二）、20P 220kV公用测控及监控通信屏、21P GPS扩展屏、23P 220kV保护信息管理屏、28P 220kV桂挡Ⅰ线、桂挡Ⅱ线测控屏、31P 220kV同步相量测量装置屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n5、在22保护小室：28P 220kV桂挡Ⅰ线、桂挡Ⅱ线测控屏内220kV桂挡Ⅰ线线路测控装置PCS-9705-G-1-N-1A前后粘贴“运行设备”标识；\\r\\n6、在51保护小室：32P 相角监测屏、33P PMU同步相量测量屏前悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；\\r\\n7、在通信机房 E04 220kV桂挡Ⅰ、Ⅱ线载波机屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；\\r\\n8、在通信机房：E04 220kV桂挡Ⅰ、Ⅱ线载波机屏内 220kV桂挡Ⅰ线ETL641载波机装置前后粘贴“运行设备”标识；\\r\\n9、在主控室：新监控工作站1、新监控工作站2、500kV #1监控主机、五防系统主机放置“在此工作”标示牌；\\r\\n10、在计算机室：1P 网络设备屏、2P 公用设备屏、3P 远动通信屏（一）、4P 远动通信屏（二）、6P 调度数据网交换机屏、8P 信息子站屏、12P 公用测控及监控通信屏、13P 监控系统服务器屏、14P 串补监控/数据服务器屏、15P 远动通信屏（三）前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n11、在相关停电设备工作区域装设安全围栏，围栏内的设备包括220kV桂挡Ⅱ线2058断路器三相机构箱、220kV桂挡Ⅱ线20586隔离开关机构箱、220kV桂挡Ⅱ线205847接地刀闸机构箱、220kV桂挡Ⅱ线205867接地刀闸机构箱、220kV桂挡Ⅱ线2058617接地刀闸机构箱、220kV桂挡Ⅱ线联锁端子箱、220kV桂挡Ⅱ线2058CT端子箱、220kV桂挡Ⅱ线线路CVT端子箱,并在围栏上向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌；\\r\\n12、在电缆沟：220kV桂挡Ⅱ线间隔至22保护小室电缆沟、22保护小室至主控室通信机房电缆沟两端放置“在此工作”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-08-C0-008]\\r\\n陈海龙，2021-08-08 16:20\\r\\n郭兴顺、周贞萍、周真兵、曹清海、杨君会、郭龙、查明翠，2021-08-09 08:16\\r\\n吴硕，2021-08-11 10:41', 'EXtCuSGl', '2022-01-03 09:22:12', NULL, '64', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '7d89eb423f854cc39243f00353e69dcb', NULL, '1、本任务中如有其它班组作业的，工作负责人需向工作总协调人提出工作申请，由工作总协调人现场安排，确保现场工作安全有序。\\r\\n2、遥控试验前，要向运维人员申请同意后进行。遥控试验过程如需拉开接地刀闸等，由运维值班员进行操作，当天试验结束后，由值班员进行恢复。', '在220kV桂挡Ⅱ线线路避雷器靠线路侧装设220kV三相短路接地线1组，共1组。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3ad2cb1c8b064a26ad5ac7ee08ecf87a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-16 12:57:42', '0108', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '无', 'EXtCTU2Z', '2022-01-16 12:57:42', NULL, '9', NULL, '1、在53保护室、52保护室、51保护室、主变及35kV保护室、站用电室、融冰保护室、220kV保护室内入口处悬挂“在此工作！”标示牌；2、在阀厅、发电机室入口处悬挂“在此工作！”标示牌；3、在主控楼电缆井、500kV通信机房、220kV通信机房、主控制室、主控楼运行办公室、综合楼各办公室、门卫室入口处悬挂“在此工作！”标示牌；4、在备品备件库房及报废物资临时库房入口处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'de6778ebd7c5466aae4ae7e6e976bb6d', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3ae975c7c9824ced95029dc43ed1574d', NULL, NULL, '50631、50632、50731、50732。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 01:53:30', '0101', '1、退出69P 500kV #2M母线B套保护屏内以下压板：1LP1 PCS-915C跳500kV 花从乙线5013开关出口II、1LP2 PCS-915C 跳#3主变500kV侧5023开关出口II、1LP3 PCS-915C跳500kV 花从甲线5033开关出口II、1LP4 PCS-915C跳#4主变500kV侧5043开关出口II、1LP5 PCS-915C跳 500kV清花甲线5053开关出口II、1LP8 PCS-915C跳500kV山花甲线5083开关出口II、1LP9 PCS-915C跳500kV山花乙线5093开关出口II；\\r\\n2、断开50631、50731刀闸控制电源8D3和电机电源Q1；断开50632、50732刀闸控制电源8D3和电机电源Q2。', NULL, '1、分别在500kV #2继保室：7P 500kV 5063断路器保护屏、20P 500kV 5073断路器保护屏、69P 500kV #2M母线B套保护屏放置“在此工作！”标示牌，并在相邻屏柜粘贴“运行设备”警示带；\\r\\n2、分别在50631、50731刀闸操作把手、控制电源8D3和电机电源Q1、50632、50732刀闸操作把手、控制电源8D3和电机电源Q2处悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、分别在500kV交流场：500kV 5063开关就地控制柜、500kV 5073开关就地控制柜悬挂“在此工作！”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险！”标示牌，遮栏出入口围至临近道路旁边，并设有“从此进出”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作中需要多次分合5063、5073开关。[交底单号：2022-01-C0-018]', 'EXtClm04', '2022-01-25 01:53:30', NULL, '51', NULL, NULL, NULL, NULL, '5063、5073。', NULL, NULL, NULL, 'a3724990dd9a4a7f8d84799eb5cfb8d9', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3af53fa2706a4066944cca5b57cbad72', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 19:36:21', '0103', '无。', NULL, '在电子围栏第十三防区主机悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031145', '2022-01-27 19:36:21', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '504f2a3847664f70ad400116bffd3cc7', NULL, '无。', NULL, NULL, '不停电。');
