INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3b0faedad4854ccaa4ad1855e87b5cb4', NULL, NULL, '20613、20614、20616。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-02 22:14:38', '0104', '断开20613、20614、20616隔离开关电机电源空气开关QF1、控制电源空气开关QF2。', NULL, '1、分别在20613、20614、20616隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，在监控系统主接线20613、20614、20616隔离开关上作“禁止合闸 有人工作”的标识；\\r\\n2、在相关工作区域装设安全围栏，围栏内设备包括220kV桂凯线2061CT本体三相及端子箱，并在围栏上向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌；\\r\\n3、在20613、20614隔离开关机构箱三相正门装设“检修隔离锁”。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-09-C0-010]\\r\\n苏明龙，2021-09-16 09:46', 'EXtCuSGl', '2022-01-02 22:14:38', NULL, '30', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '52bade66f8ab44949795be2a34189651', NULL, '无。', '206147、206167接地刀闸，共2把。', NULL, NULL);
