INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('3f78301b052d453d8a8d4b879c2a5cce', NULL, NULL, '1、5651；2、将10kV 12DL断路器操作到试验位置。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 22:32:12', '0107', '1、分别断开5651隔离开关电机电源空开QM1和操作电源空开QF1；\\r\\n2、#2继电器室：断开P28 35/10kV站用变压器保护屏内的直流电源空开4K。\\r\\n3、站用变间隔交流配电箱2：断开329断路器汇控箱交流电源空开10MCB。', NULL, '1、分别在5651隔离开关电机电源空开QM1和操作电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n2、#2继电器室：在P28 35/10kV站用变压器保护屏内的直流电源空开4K上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、在10kV 12DL断路器操作把手上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、在329断路器四周设置安全围栏，并向内悬挂“止步，高压危险！”标示牌，在围栏出入口处悬挂“从此进出！”和“在此工作！”标示牌；\\r\\n5、#2继电器室：分别在P28 35/10kV站用变保护屏、P20 高压站用变就地控制接口屏上悬挂“在此工作！”标示牌并在相邻屏柜前后悬挂“运行设备”标示牌；\\r\\n6、站用变间隔交流配电箱2：在329断路器汇控箱交流电源空开10MCB上悬挂“禁止合闸，有人工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-012]因工作票回退，未提前一天接收。\\r\\n补充安全交代：梁云付，2021-12-28 09:45；彭衍，2022-01-02 08:24；陈培龙，2022-01-02 16:03。', 'EXtCIf40', '2022-01-21 22:32:12', NULL, '61', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '326e73bfd0494e08bb9ec98ecf4762de', NULL, '无。', '32927、32967。', NULL, NULL);
