INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('4127eda557b74be9a61acee2b7391835', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 16:02:02', '0102', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-006]。工作负责人：15885656780。', 'EXtCIf40', '2022-01-19 16:02:02', NULL, '64', NULL, '分别在500kV黎平变电站主控楼、21小室、22小室、31小室、380小室、51小室、52小室、直流融冰室、#1B主变泡沫喷淋室、#1B主变消防小室、#1B主变消防沙池、#2B主变泡沫喷淋室、#2B主变消防小室、#2B主变消防沙池处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'dadee7a44d2d46779e103c72ef7cb1b1', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('41323093d5884cb5bbe3cb5e4a970cce', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 11:25:41', '0101', '无。', NULL, '在±500kV肇庆换流站500kV交流场、交流滤波器场、±500kV 双极直流场、双极换流变及平抗、站用电区域悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012004', '2022-01-14 11:25:41', NULL, '29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '62475b588af045ff839bb0e55f13c724', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('414c801031e04893a71e68b970e78ab6', NULL, '本次作业无需退出线路重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 14:08:10', '0108', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01080906', '2022-01-19 14:08:10', NULL, '23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'b68b42d16f364cf08a36a6a483f56f16', NULL, '1、本次高空作业人员必须穿全套合格的静电防护服，作业人员与带电体保持5米以上的安全距离。如遇雷电、雪、雹、雨、雾天气，风力大于5级或湿度大于80%时，严禁进行登塔作业。\\r\\n2、作业前，工作负责人必须得到线路许可人许可，工作班成员得到工作负责人许可后方可开展作业。登塔作业必须履行审批手续。\\r\\n3、严格执行“工作票制度”，工作负责人负责组织召开现场班前会，对所有参加作业人员进行交底并签字确认，严格执行“个人安全防护措施互检制”、“工作安全措施现场确认制”。\\r\\n4、登塔前必须认真核对线路名称、塔号（核对必须由2人进行），核对无误后方可登塔作业，防止误登杆塔。\\r\\n5、现场所有工作人员必须戴安全帽，攀登杆塔及在杆塔上作业时，严格执行“关于防止高空坠落”的规定，塔上作业人员必须按要求使用全身式双保险安全带，在上、下塔、转位、作业过程中交替使用，任何时刻均不得失去安全带的保护，安全带应高挂低用，系在牢固的构件上，防止被尖锐物割伤，且随时检查安全带是否拴牢。\\r\\n6、高空人员必须穿全套合格的屏蔽服，且各部件连接要牢靠，严禁使用不合格的屏蔽服。\\r\\n7、作业过程中，工器具及材料均应保持在横担以上，人员、工器具及材料时刻与带电体保持5米以上安全距离。\\r\\n8、在作业过程中如遇设备突然停电，作业人员应视设备仍然带电，在工作负责人与线路工作许可人取得联系前，停止作业。\\r\\n9、工作结束后，应认真清理现场，清点人数，确认塔上无遗留物后方可撤离现场，做到人走物清。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('41ad3716a51a4200bc667c736fad3937', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 21:07:45', '0104', '无。', NULL, '在220kV第三保护小室：1P 220kV河陈Ⅰ线主一保护屏、2P 220kV河陈Ⅰ线主二保护屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-021]', 'EXtCuSGl', '2022-01-25 21:07:45', NULL, '44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cf9088f257e04a73ad7ca6dadf122965', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('41b9864ba863459d8d5cc4e3bd631804', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 11:22:07', '0101', '无。', NULL, '在工业水池进水阀门处、综合水泵房生产给水泵控制柜处悬挂“在此工作”标示牌，在相邻运行屏柜粘贴运行设备警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作中需要多次分合综合水泵房：综合水泵房生产给水泵控制柜二次进线保险“FU1、FU2”。', '01012005', '2022-01-21 11:22:07', NULL, '35', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'e978c47f35e74c1b87276788e5b26de7', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('41ce61f8613a42eb962b97ae0f3f9aff', NULL, NULL, '50111、50122、00102、00102A、05105。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 10:34:00', '0107', '1、分别断开50111、50122刀闸电机电源开关QF1；2、分别断开10B10+V1直流场中性母线就地汇控箱1内00102刀闸电机电源开关F184-3、00102A刀闸电机电源开关F184-4，断开11B00+V1直流场极1就地汇控箱1内05105刀闸电机电源开关F184-2；3、分别断开极1换流变进线PT汇控箱内二次开关F711（至极1直流保护1电压回路）、F712（至极1换流变保护1电压回路）、F713（至极1极控系统1电压回路）、F714（至5011断路器保护电压回路）、F721（至极1直流保护2电压回路）、F722（至极1换流变保护2电压回路）、F723（至极1极控系统2电压回路）、F724（至500kV 第一串就地控制接口屏电压回路）、F731（至极1直流保护3电压回路）、F732（至极1故障录波屏电压回路）、F733（至交流谐波监视屏电压回路）、F734（极1换流变电度表屏电压回路）、F735（极1套管在线监测电压回路）。', NULL, '1、分别在50122、50111刀闸就地控制箱内电机电源开关QF1上悬挂“禁止合闸，有人工作！”标示牌； 2、分别在10B10+V1直流场中性母线就地汇控箱1内00102刀闸电机电源开关F184-3，00102A刀闸电机电源开关F184-4，11B00+V1直流场极1就地汇控箱1内05105刀闸电机电源开关F184-2上悬挂“禁止合闸，有人工作！”标示牌； 3、分别在极1换流变进线PT汇控箱内二次开关F711（至极1直流保护1电压回路）、F712（至极1换流变保护1电压回路）、F713（至极1极控系统1电压回路）、F714（至5011断路器保护电压回路）、F721（至极1直流保护2电压回路）、F722（至极1换流变保护2电压回路）、F723（至极1极控系统2电压回路）、F724（至500kV 第一串就地控制接口屏电压回路）、F731（至极1直流保护3电压回路）、F732（至极1故障录波屏电压回路）、F733（至交流谐波监视屏电压回路）、F734（极1换流变电度表屏电压回路）、F735（极1套管在线监测电压回路）上悬挂“禁止合闸，有人工作！”标示牌；4、分别在极1 011B和012B换流变四周设置围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏出入口处悬挂“在此工作！”和“从此进出！”标示牌； 6、分别在极1换流变进线避雷器、PLC电抗器、PLC电容器四周设置围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏出入口处悬挂“在此工作！”和“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-029]', '01200802', '2022-01-22 10:34:00', NULL, '32', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '875d572270864de189057649e6d49d22', NULL, '无。', '501117、501227、501167、050117、050127。', NULL, NULL);
