INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('424fe9a18f4942b98b844c25c7d7dd57', NULL, NULL, '50721、50722、50731、50732。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-01 10:13:54', '0101', '1、分别断开5072、5073第一跳闸电源开关4DK1和第二跳闸电源开关4DK2；\\r\\n2、分别断开50721刀闸控制电源空开QF3和电机电源空开QF1；\\r\\n3、分别断开50722、50731、50732刀闸控制电源空开QF2和电机电源空开QF1；\\r\\n4、分别断开500kV从木丁线PT端子箱内二次空开：A相计量电压二次空气开关1MCBa、B相计量电压二次空气开关1MCBb、C相计量电压二次空气开关1MCBc、主一保护、安稳A、断路器保护、功角测量电压二次空气开关2MCB、主二保护、安稳B、故障录波、选相合闸电压二次空气开关3MCB、监控测量A电压二次空气开关4MCB、监控测量B电压二次空气开关5MCB。', NULL, '1、分别在5072、5073开关、50721、50722、50731、50732刀闸的操作把手处悬挂“禁止合闸，有人工作”标示牌； \\r\\n2、分别在5072、5073第一跳闸电源开关4DK1和第二跳闸电源开关4DK2上悬挂“禁止合闸，有人工作”标示牌；\\r\\n3、分别在50721刀闸控制电源空开QF3和电机电源空开QF1上悬挂“禁止合闸，有人工作”标示牌；\\r\\n4、分别断开50722、50731、50732刀闸控制电源空开QF2和电机电源空开QF1上悬挂“禁止合闸，有人工作”标示牌；\\r\\n5、分别在500kV从木丁线PT端子箱内二次空开：A相计量电压二次空气开关1MCBa、B相计量电压二次空气开关1MCBb、C相计量电压二次空气开关1MCBc、主一保护、安稳A、断路器保护、功角测量电压二次空气开关2MCB、主二保护、安稳B、故障录波、选相合闸电压二次空气开关3MCB、监控测量A电压二次空气开关4MCB、监控测量B电压二次空气开关5MCB上悬挂“禁止合闸，有人工作”标示牌；\\r\\n6、分别在500kV从木丁线5073开关、500kV 第七串联络5072开关、500kV 第七串联络5072开关电流互感器T1、500kV从木丁线5073开关电流互感器T1、500kV 第七串联络开关Ⅱ母侧50722刀闸、500kV 第七串联络开关Ⅱ母侧507227地刀、500kV 从木丁线开关Ⅰ母侧50731刀闸、500kV 从木丁线开关Ⅰ母侧507317地刀、500kV 从木丁线线路507367地刀、500kV从木丁线线路电压互感器、避雷器、支柱绝缘子及悬式绝缘子处装设遮栏，在遮栏上向内悬挂“止步，高压危险”标示牌，在遮栏入口处悬挂“在此工作”及“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-012]', 'EXtClm04', '2022-01-01 10:13:54', NULL, '99', NULL, NULL, NULL, NULL, '5072、5073。', NULL, NULL, NULL, '467174df18d04eb7959791fcedb904d5', NULL, '将50721、50722、50731、50732实施机构上锁。', '507217、507227、507317、507327、507367，在500kV从木丁线避雷器F1靠线路侧装设一组500kV分相短路式接地线。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('42530ffe61db4d83930be5d367066475', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-01 17:31:03', '0108', '无。', NULL, '1、在主控楼A组合式空调处理机、主控楼B组合式空调处理机处悬挂“在此工作！”标示牌；2、在牛从甲直流极1空调A组合式空调处理机、牛从甲直流极1空调B组合式空调处理机处悬挂“在此工作！”标示牌；3、在牛从甲直流极2空调A组合式空调处理机、牛从甲直流极2空调B组合式空调处理机处悬挂“在此工作！”标示牌；4、在牛从乙直流极1空调A组合式空调处理机、牛从乙直流极1空调B组合式空调处理机处悬挂“在此工作！”标示牌；5、牛从乙直流极2空调A螺杆机组、在牛从乙直流极2空调A组合式空调处理机、牛从乙直流极2空调B组合式空调处理机处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-013]', 'EXtClmtg', '2022-01-01 17:31:03', NULL, '61', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a0b15f36d4e7469ea59aa61c34a30f9d', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('4264be10491b47b08073301de180e54c', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-08 13:55:03', '0101', '无。', NULL, '1、在主控楼系统分析维护及培训室：工程师工作站EWS（=30P12+P1）悬挂“在此工作！”标示牌； 2、分别在辅控楼极1低端换流器控制保护室：极1低端换流器测量接口屏B（=31QG20+Q2）前后悬挂“在此工作！”标示牌，并在相邻运行屏柜粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012012', '2022-01-08 13:55:03', NULL, '33', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '536899fb00534dabaaa7453e85b0598f', NULL, '无。', NULL, NULL, '不需要停电。');
