INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('45100eb1ca3c452ba3a8c50063c02d76', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-23 17:32:06', '0109', '1、断开极1高端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0；2、断开极1低端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0；3、断开极2高端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0；4、断开极2低端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0；5、断开主控楼中央空调系统空气处理机组A套就地配电屏内总电源空开QF0。', NULL, '1、在极1高端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0处悬挂“禁止合闸，有人工作！”标示牌；2、在极1低端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0处悬挂“禁止合闸，有人工作！标示牌；3、在极2高端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0处悬挂“禁止合闸，有人工作！标示牌；4、在极2低端阀厅中央空调系统空气处理机组A套就地配电屏内总电源空开QF0处悬挂“禁止合闸，有人工作！标示牌；5、在主控楼中央空调系统空气处理机组A套就地配电屏内总电源空开QF0处悬挂“禁止合闸， 有人工作！标示牌；6、分别在极1高、低端阀厅A组中央空调系统、极2高、低端阀厅A组中央空调系统、主控楼A 组中央空调系统处悬挂“在此工作！”标示牌；7、分别在51、52直流继电小室空调处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-007]\\r\\n检修交待：已完成1、双极四阀厅、主控楼空调系统A空气处理机组更换空气过滤网；2、51直流继电小室空调消缺、极2高端空调系统水泵更换垫片、主控楼空调系统B套更换冷凝风机。存在问题：极1极2高端阀厅空调系统A效、中效过滤器型号不对、待厂家重新发货，52继电小室空调电机寄回昆明维修。', 'EX03TG', '2022-01-23 17:32:06', NULL, '51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '9af4258be5734441bb95682e89daf3f0', NULL, '无。', NULL, NULL, '不需要停电。');
