INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('4526ca9e90ca4b118306c9a7b4c4f5b7', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 18:08:12', '0108', '1、断开500kV 51711刀闸B相机构箱控制电源空开QF2，A、B、C相机构箱电机电源空开QF1；\\r\\n2、断开500kV 517117接地刀闸B相机构箱控制电源空开QF2，A、B、C相机构箱电机电源空开QF1。 ', NULL, '1、在500kV 5171开关#1M母线侧51711刀闸A、B、C相机构箱上悬挂“在此工作！”标示牌； \\r\\n2、在500kV 5171开关#1M母线侧517117接地刀闸A、B、C相机构箱上悬挂“在此工作！”标示牌；\\r\\n3、在500kV 51711刀闸B相机构箱控制电源空开QF2，A、B、C相机构箱电机电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、在500kV 517117接地刀闸B相机构箱控制电源空开QF2，A、B、C相机构箱电机电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01080805', '2022-01-07 18:08:12', NULL, '24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '171b296e149246d29ffd2986af907935', NULL, '无。', NULL, NULL, '不需要停电。');
