INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('45640bd3644e42f68956fa3630472511', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 17:53:46', '0103', '1、退出304继电保护室190P 500kV平来Ⅱ线主一/辅A保护柜主一保护RCS-931DSMM投纵联差动通道一1LP19压板；2、退出304继电保护室191P 500kV平来Ⅱ线主二/辅B保护柜主二保护PSL603GW投差动1 1LP19压板；3、退出304继电保护室192P 500kV平来Ⅱ线主三A保护柜主三保护RCS-902CDSFFV投纵联距离通道一1LP19压板；4、在304继电保护室190P 500kV平来Ⅱ线主一/辅A保护柜将“9QK辅A保护通道切换开关”切换至“通道一退出二投入”位置；5、在304继电保护室191P 500kV平来Ⅱ线主二/辅B保护柜将“9QK1辅B保护通道切换开关”切换至“通道一退出二投入”位置。', NULL, '在319通信机房E06 新网A DDF配线屏前后分别悬挂“在此工作！”标示牌，将工作屏柜内非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-10 17:53:46', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a6d2c724155345a0bb1c7b67325e3784', NULL, '无。', NULL, NULL, '不停电。');
