INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('4faa3c7370f54f3cb6ace787933bbb41', NULL, NULL, '2901。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 10:23:54', '0108', '1、断开220kV #1M母线电压互感器端子箱内隔离开关交流电源空开； 2、断开220kV #1M母线电压互感器端子箱内220kV I母保护A空开、220kV I母保护B空开、220kV I母保护C空开、220kV I母计量A空开、220kV I母计量B空开、220kV I母计量C空开及试验电压空开。', NULL, '1、在220kV #1M母线电压互感器、220kV #1M母线电压互感器端子箱上悬挂“在此工作！”标示牌； 2、在220kV #1M母线电压互感器端子箱内隔离开关交流电源空开、220kV I母保护A空开、220kV I母保护B空开、220kV I母保护C空开、220kV I母计量A空开、220kV I母计量B空开、220kV I母计量C空开及试验电压空开上悬挂“禁止合闸，有人工作！”标示牌； 3、在220kV 2901刀闸机构箱内操作处悬挂“禁止合闸，有人工作！”标示牌； 4、在主控室监控系统220kV 2901刀闸相应操作处设置“禁止合闸，有人工作！”标示； 5、在220kV #1M母线电压互感器、220kV #1M母线电压互感器端子箱周围装设安全围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏入口处悬挂“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'EX0307', '2022-01-25 10:23:54', NULL, '4', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '3a408d8b0aa0417cb63d0cf62b6e74e5', NULL, '无。', '29017。', NULL, NULL);
