INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('5fa5fa4181944edf98996b54d5af3708', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 10:54:21', '0107', '无。', NULL, '在换流变检修间、存储间大门上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-064]', 'EXtCLNtb', '2022-01-22 10:54:21', NULL, '52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '3c302a6c741343b7b463118299433c9a', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('5fcdc2aba25442d2863e5afaac06e166', NULL, '本次作业不需要退出线路两侧重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 14:16:01', '0108', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01080902', '2022-01-18 14:16:01', NULL, '29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '99691b9217b040d1812ffaef5c2925fc', NULL, '1.带电作业应在良好天气下进行，如遇雷电、雪、雹、雨、雾等，不应进行带电作业。风力大于5级（风速10m/s）或湿度大于80%时，不宜进行带电作业。 \\r\\n2.塔上作业人员及所使用的工器具材料与带电导线保持5米以上的安全距离。 \\r\\n3.高空作业人员必须穿全套合格的静电防护服或屏蔽服。 \\r\\n4.作业前，工作负责人与线路工作许可人取得联系，得到许可工作的命令后，方可开始工作。 \\r\\n5.作业前，召开班前会，宣读工作票所列安全措施及安全注意事项，并组织工作班成员检查确认现场安全措施，开展个人安全措施互检，工作结束后进行当天班后会，总结工作。 \\r\\n6.登塔前，工作负责人必须与工作班成员认真确认工作线路名称、塔号（核对必须由2人进行）无误后方可登塔作业，防止误登作业范围以外的其他带电线路杆塔。 \\r\\n7.现场所有工作人员必须戴安全帽，攀登杆塔及在杆塔上作业时，必须使用双保险安全带，在上、下塔、转位、作业过程中交替使用，任何时刻都不得失去安全带或后备保护绳的保护。现场监护人员必须认真履行监护职责，时刻做好监督提醒。 \\r\\n8.工作结束后，应认真清理现场，清点人数，确认塔上无遗留物后方可撤离现场，做到人走物清。', NULL, NULL, NULL);
