INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('6225e82c36f14bf282ba71560fd64d99', NULL, NULL, '50211、50222、08210、04220。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-01 15:36:27', '0109', '1、分别断开500kV极2高端换流变5021断路器汇控箱内50211隔离开关电机电源空气开关-F171和控制电源空气开关-F111；2、分别断开500kV第二串联络5022断路器汇控箱内50222隔离开关电机电源空气开关-F171和控制电源空气开关-F111； 3、分别断开=12B12+V1直流场汇控箱内08210、04220隔离开关电机电源空气开关-F184；4、分别断开=12B00+SW2 极2直流场就地控制接口屏2内08210、04220隔离开关控制电源空气开关-F231；5、分别断开极2高端换流变进线PT端子箱二次空开F711、F712、F713、F714、F721、F722、F723、F724、F731、F732、F733。', NULL, '1、分别在500kV极2高端换流变5021断路器汇控箱内50211隔离开关电机电源空气开关-F171和控制电源空气开关-F111及汇控箱把手上悬挂“禁止合闸，有人工作！”标示牌； 2、分别在500kV第二串联络5022断路器汇控箱内50222隔离开关电机电源空气开关-F171和控制电源空气开关-F111及汇控箱把手上悬挂“禁止合闸，有人工作！”标示牌； 3、分别在=12B12+V1直流场汇控箱内04220、08210隔离开关电机电源空气开关-F184及其机构箱把手悬挂“禁止合闸，有人工作！”标示牌；4、分别在=12B00+SW2 极2直流场就地控制接口屏2内04220、08210隔离开关控制电源空气开关-F231上悬挂“禁止合闸，有人工作！”标示牌；5、在极2高端阀厅紧急门处悬挂“在此工作”标示牌；6、分别在极2高端换流变进线PT端子箱二次空开F711、F712、F713、F714、F721、F722、F723、F724、F731、F732、F733上悬挂“禁止合闸，有人工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-052]  黄剑湘，安全交代时间：2021年12月11日14时15分\\r\\n检修交待：已完成极二高端阀厅阀塔设备清洁、检查、试验及消缺。验收合格，已具备投运条件。', 'EX0307', '2022-01-01 15:36:27', NULL, '68', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '7c785cf39cc64dadb6b165a68ae3e03b', NULL, '无。', '502167、080217、080227、082107、042207。', NULL, NULL);
