INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('673fd93cd8064a9cbb62bba7e385bf5a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 15:03:18', '0101', '无。', NULL, '分别在+800kV极1低端Y/Y换流变A相本体底部取油口，+800kV极1低端Y/Y换流变A、B、C相，+800kV极1低端Y/△换流变A、B、C相，+800kV极1高端Y/Y换流变A、B、C相，+800kV极1高端Y/△换流变A、B、C相， -800kV极2低端Y/Y换流变A、B、C相，-800kV极2低端Y/△换流变A、B、C相，-800kV极2高端Y/Y换流变A、B、C相，-800kV极2高端Y/△换流变A、B、C相油色谱在线监测装置本体、后台电脑、油色谱综合处理单元处，500kV#2主变A、B、C相，500kV#3主变A、B、C相油色谱在线监测装置本体、后台电脑处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012007', '2022-01-12 15:03:18', NULL, '14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5d62e83e20ab458cb51fc4edfad75811', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('67538432a776421b83088f5e15fbfdd9', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 19:15:31', '0102', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：18385225145。[交底单号：2021-12-C0-016]\\r\\n补充安全交代：2021年12月22日08时45分：黄元江、郑连云、郑荣华、薛仁辉、罗乾坤。12月24日15时50分：杨光国、王兴明、李小云、杨文海、高长生。12月26日09时06分：王祥海、李海水。1月1日17时05分：罗利、陈江华、唐昌文、张守坤\\r\\n01月02日10时30分：胥德书、罗玉兵、文联娣、李文知；01月06日09时00分：甯光伦、甯明洪、王善平、王文龙。', 'EXtCIf40', '2022-01-11 19:15:31', NULL, '75', NULL, '分别在21小室、51小室、52小室、35小室、380小室、雨淋阀间处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'a13d4e005faf4d42a26f4cea6abb7273', NULL, NULL, NULL, NULL, NULL);
