INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7ced2f646ace4b25b62694b2d1674f4f', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-18 16:54:05', '0120', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-18 16:54:05', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '11e10546eb34402b9e027a4b34468756', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7cf57c7c3a5b46f18892b0a5bf140498', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 17:56:11', '0104', '无。', NULL, '1、在主控楼计算机室：1P一键顺控及智能巡视系统屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识； \\r\\n2、在主控楼计算机室：7P图像监控系统屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识； \\r\\n3、在主控楼计算机室1P一键顺控及智能巡视系统屏与7P图像监控系统屏之间地板下电缆沟放置“在此工作”标示牌；\\r\\n4、在主控楼UPS电源室：1P #2 UPS电源屏、2P #1 UPS电源屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n5、在主控楼UPS电源室1P #2 UPS电源屏、2P #1 UPS电源屏至计算机室1P一键顺控及智能巡视系统屏之间地板下电缆沟施工处放置“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-007]', 'EXtC1Jnr', '2022-01-19 17:56:11', NULL, '29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '29e8885898ed4d5e90c9a061e9cb6ab1', NULL, '1、使用防火泥封堵好电缆进出口和机柜进线口；\\r\\n2、工作完毕后对检查封堵情况；\\r\\n3、设备取用电由站运维人员监护执行；\\r\\n4、放线后及时恢复防静电地板。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7cf9097a450e480cbd7f12c900c73283', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、拉开500kV鲁西换流站51511、51512、51521、51522隔离开关； \\r\\n2、拉开500kV百色变电站50211、50212、50221、50222隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-20 09:21:19', '0108', NULL, NULL, '1、在500kV鲁西换流站51512、51521隔离开关远方控制把手和现场操作箱上悬挂“禁止合闸、线路有人工作！”标示牌； 2、在500kV百色变电站50212、50221隔离开关远方控制把手和现场操作箱上悬挂“禁止合闸、线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01080902', '2022-01-20 09:21:19', NULL, '67', NULL, NULL, NULL, NULL, NULL, NULL, '1、合上500kV鲁西换流站515167接地刀闸； \\r\\n2、合上500kV百色变电站502167接地刀闸。', NULL, 'c6c9df0300c14d329873e34ab46966f4', NULL, '1、断开500kV鲁西换流站515167接地刀闸操作电源；\\r\\n2、断开500kV百色变电站502167接地刀闸操作电源。\\r\\n3、作业前与罗平变电站联系，得到许可后方可开展作业，各小组负责人必须在得到工作负责人许可后方可开始作业；\\r\\n4、所有交叉跨越及与之平行的线路均视为带电，不得靠近（注：500kV西百乙线13#-14#塔跨越220kV鲁东Ⅱ回线49#-51#塔、500kV西百乙线16#-17#塔跨越220kV鲁罗Ⅰ回线54#-56#塔、500kV西百乙线21#-22#塔跨越110kV鲁关中丹线57#-59#塔、500kV西百乙线22#-23#塔跨越35kV圭大线41#-42#塔、500kV西百乙线35#-36#塔跨越220kV鲁罗Ⅰ回线44#塔、500kV西百乙线36#-37#塔跨越220kV鲁罗II回、500kV西百乙线36#-37#塔跨越35kV圭大线57#塔、500kV西百乙线43#-44#塔跨越220kV鲁东Ⅱ回线32#-33#塔、500kV西百乙线46#-47#塔跨越35kV红大线32#-33#塔、500kV西百乙线121#-122#塔跨越35kV古马线XJB295+1-XJB296塔、500kV西百乙线145#-146#塔跨越35kV城古线B177-JB178塔、500kV西百乙线147#-148#塔跨越110kv坝西线71#-72#塔、500kV西百乙线147#-148#塔跨越35kV江古线87#-88#塔、500kV西百乙线147#-148#塔跨越35kV无名线路、500kV西百乙线148#-149#塔跨越35kV城关线B162-B163塔、500kV西百乙线171#-172#塔跨越35kV城古线JB113-B114塔、500kV西百乙线171#-172#塔跨越35kV城古线48#-49#塔、500kV西百乙线177#-178#塔跨越35kV城古线41#杆、500kV西百乙线190#-191#塔跨越35kV西林-八大线24#杆）。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7d3850e779af4b84ba9cb164448e3da8', NULL, NULL, '50121、50132、5651。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 21:58:06', '0107', '1、分别断开50121、50132隔离开关电机电源空开QF1；\\r\\n2、分别断开5651隔离开关电机电源空开QM1和控制电源空开QF1；\\r\\n3、#1继电器室：分别断开P20 500kV 5013断路器保护屏内5013操作箱电源1空开4K1、5013操作箱电源2空开4K2，P46第一大组交流滤波器保护屏1、P47第一大组交流滤波器保护屏2内=10BF11-Q0跳闸回路电源空开-F121、=10BF12-Q0跳闸回路电源空开-F122、=10BF13-Q0跳闸回路电源空开-F123、=10BF14-Q0跳闸回路电源-F124；\\r\\n4、分别断开500kV #6M母线电压互感器端子箱内直流站控屏电压回路=10XJ01+X1空开-F711、电度表屏电压回路=10Q10+Q1空开-F712、第一大组交流滤波器联线保护屏二 =10RF01+R2空开-F721、500kV交流就地控制接口屏=10B01+SW1空开-F722、500/35kV 站用变保护屏一 10T20+R1空开-F723、500/35kV 低抗及站用变测控屏 10T20+S1空开-F724、500千伏交流场就地控制接口屏=10BF01+SW1空开-F731、断路器保护屏=10B01.C+R1空开-F732、第一大组交流滤波器联线保护屏二 =10RF01+R2空开-F733、500/35kV 站用变保护屏二 10T20+R2空开-F734；\\r\\n5、分别断开交流场第一串交流电源配电箱内50122隔离开关操作加热电源=10B01.B-Q62空开F23、501227接地刀闸操作加热电源=10B01.B-Q52空开F25、501367接地刀闸操作加热电源=10B01.C-Q53空开F36、50131隔离开关操作加热电源=10B01.C-Q6空开F33、501317接地刀闸操作加热电源=10B01.C-Q52空开F35；\\r\\n6、断开=10BF11+V1 561交流滤波器就地汇控柜内操作电源 10BF11-Q1/Q51/Q52空开F183；\\r\\n7、断开=10BF12+V1 562交流滤波器就地汇控柜内操作电源10BF12-Q1/Q51/Q52空开F183；\\r\\n8、断开=10BF13+V1 563交流滤波器就地汇控柜内操作电源10BF13 Q1/Q51/Q52空开F183；\\r\\n9、断开=10BF14+V1 564交流滤波器就地汇控柜内操作电源10BF14 Q1/Q51/Q52空开F183。', NULL, '1、分别在50121、50132隔离开关电机电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n2、分别在5651隔离开关电机电源空开QM1和控制电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、#1继电器室：分别在P20 500kV 5013断路器保护屏内5013操作箱电源1空开4K1、5013操作箱电源2空开4K2，P46第一大组交流滤波器保护屏1、P47第一大组交流滤波器保护屏2内=10BF11-Q0跳闸回路电源空开-F121、=10BF12-Q0跳闸回路电源空开-F122、=10BF13-Q0跳闸回路电源空开-F123、=10BF14-Q0跳闸回路电源-F124上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、分别在500kV #6M母线电压互感器端子箱内直流站控屏电压回路=10XJ01+X1空开-F711、电度表屏电压回路=10Q10+Q1空开-F712、第一大组交流滤波器联线保护屏二 =10RF01+R2空开-F721、500kV交流就地控制接口屏=10B01+SW1空开-F722、500/35kV 站用变保护屏一 10T20+R1空开-F723、500/35kV 低抗及站用变测控屏 10T20+S1空开-F724、500千伏交流场就地控制接口屏=10BF01+SW1空开-F731、断路器保护屏=10B01.C+R1空开-F732、第一大组交流滤波器联线保护屏二 =10RF01+R2空开-F733、500/35kV 站用变保护屏二 10T20+R2空开-F734上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n5、分别在交流场第一串交流电源配电箱内50122隔离开关操作加热电源=10B01.B-Q62空开F23、501227接地刀闸操作加热电源=10B01.B-Q52空开F25、501367接地刀闸操作加热电源=10B01.C-Q53空开F36、50131隔离开关操作加热电源=10B01.C-Q6空开F33、501317接地刀闸操作加热电源=10B01.C-Q52空开F35上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n6、在=10BF11+V1 561交流滤波器就地汇控柜内操作电源 10BF11-Q1/Q51/Q52空开F183上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n7、在=10BF12+V1 562交流滤波器就地汇控柜内操作电源10BF12-Q1/Q51/Q52空开F183上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n8、在=10BF13+V1 563交流滤波器就地汇控柜内操作电源10BF13 Q1/Q51/Q52空开F183上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n9、在=10BF14+V1 564交流滤波器就地汇控柜内操作电源10BF14 Q1/Q51/Q52空开F183上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n10、在5013、561、562、563、564断路器，50122、50131、5611、5621、5631、5641隔离开关，501227、501317、501367、56117、56127、56217、56227、56317、56327、56417、56427、5617接地刀闸四周设置围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏出入口处悬挂“在此工作！”及“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '补充安全交代：梅小飞、张廷祥、张廷龙、兰朝杨、冷洪、冷福祥、龚兴隆、钱聪，2021-12-28 11:10；\\r\\n杨应强，2021-12-29 11:00；蒋东跃，2022-01-02 08:55；李典成、刘科情、安正江、陈亮、王晨，2022-01-03 14:55。', '01070103', '2022-01-21 21:58:06', NULL, '71', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '59c970ae1a8a44f1929a1fa6a32f98a1', NULL, '无。', '501217、501327、56517。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7d74b454335d4723bcd9688beb9f4328', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 20:09:14', '0109', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-002]检修交代：一次备品库、二次备品库硬件部分已完成，初步调测。剩余部分年后再开票调试。', 'EXtC1JHR', '2022-01-15 20:09:14', NULL, '87', NULL, '1、分别在昆北站一次备品库、二次备品库门上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'f732db323ec54e02bbc6ed3dad5b970c', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7d855a1273da4e7c823e63e761202696', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 17:28:20', '0107', '无。', NULL, '1、分别在500kV云南侧换流单元一010B换流变压器A、B、C相本体下部取油阀门处悬挂“在此工作！”标示牌； 2、分别在500kV广西侧换流单元一011B换流变压器A、B、C相本体下部取油阀门处悬挂“在此工作！”标示牌；3、分别在500kV云南侧换流单元二020B换流变压器A、B、C相下部取油阀门处悬挂“在此工作！”标示牌； 4、分别在500kV广西侧换流单元二021B换流变压器A、B、C相下部取油阀门处悬挂“在此工作！”标示牌；5、分别在500kV云南侧换流单元三030B联接变压器A、B、C相本体下部取油阀门处悬挂“在此工作！”标示牌；6、分别在500kV广西侧换流单元三031B联接变压器A、B、C相本体下部取油阀门处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01070109', '2022-01-26 17:28:20', NULL, '30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f4b844d9363a47ff922ebd3bcd4056cc', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7db7795a4e064fc5abe8fef7c120e3c6', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、500kV黎平变电站断开500kV施黎乙线5051开关、500kV第五串联络5052开关； 500kV黎平变电站拉开500kV施黎乙线50511刀闸、500kV施黎乙线50512刀闸、500kV第五串联络50521刀闸、500kV第五串联络50532刀闸； 2、500kV施秉变电站断开500kV施黎乙线5021开关、500kV第二串联络5022开关； 500kV施秉变电站拉开500kV施黎乙线50211刀闸、500kV施黎乙线50212刀闸、500kV第二串联络50221刀闸、500kV第二串联络50232刀闸。', NULL, NULL, '0.000000000000000', '2022-01-30 07:17:19', '0102', NULL, NULL, '1、分别在500kV黎平变电站500kV施黎乙线5051开关、500kV第五串联络5052开关、500kV施黎乙线50511刀闸、500kV施黎乙线50512刀闸、500kV第五串联络50521刀闸、500kV第五串联络50532刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 2、分别在500kV施秉变电站500kV施黎乙线5021开关、500kV第二串联络5022开关、500kV施黎乙线50211刀闸、500kV施黎乙线50212刀闸、500kV第二串联络50221刀闸、500kV第二串联络50232刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 3、分别在500kV黎平变电站500kV施黎乙线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌； 4、分别在500kV施秉变电站500kV施黎乙线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人：18798073210；线路融冰工作组组长刁望圆：15285538603。', '0102109705', '2022-01-30 07:17:19', NULL, '13', NULL, NULL, NULL, NULL, NULL, NULL, '1、500kV黎平变电站合上500kV施黎乙线505167接地刀闸； 2、500kV施秉变电站合上500kV施黎乙线502167接地刀闸。', NULL, '876ccad8e0574e909e7952c414112a17', NULL, '1、验电及挂、拆接地线时必须戴绝缘手套，人体应保持与验电器连接线、地线接地线0.4m以上安全距离并有专人监护；挂接地线时应先挂接地端，后挂导线端，拆接地线时程序与此相反； 2、工作负责人必须得到线路融冰工作组组长下达可以开展合闸工作指令后再进入工作现场，方可组织工作班人员开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路； 3、登塔前必须检查所用安全用具、工器具是否完好，操作是否灵活，严禁使用不合格的安全用具和工器具； 4、人体应保持与架空地线、操作机构箱至少0.4m以上的安全距离； 5、高空作业须严格遵守《超高压输电公司防止高空坠落的措施》的规定，工作人员上下塔、进出绝缘子串等必须使用双控全身式高空安全带交叉保护，高空作业任何时刻不得失去安全带（绳）的保护。严格遵守《超高压输电公司防止人身伤亡事故守则》，多人同时登塔或高处作业时，不能有两个及以上人员处于同一垂直面； 6、现场人员必须戴安全帽，登塔或在塔上作业时，每基杆塔均设专人监护，监护人必须始终在现场并认真监护，及时纠正不安全的行为； 7、工作班成员接到工作负责人开始融冰工作指令后，禁止靠近工作塔位15米范围内； 8、其余安全注意事项必须严格按照经批准的《500kV施黎乙线防冰工作手册（2021-2022年）》所列安全措施执行； 9、只需要操作500kV施黎乙线普通地线第034#-335#段对应的接线装置和接地刀闸； 10、工作结束后，工作负责人必须确认工作人员已全部下塔，且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7dcf08f99b244fd09ea0420ae2d129a2', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 17:51:35', '0103', '断开35kV C324低抗C3242刀闸、35kV C324低抗C32427地刀、35kV C326低抗C3262刀闸、35kV C326低抗C32627地刀加热器及照明电源QF2空气开关。', NULL, '1、在35kV C324低抗C3242刀闸机构箱、35kV C324低抗C32427地刀机构箱、35kV C326低抗C3262刀闸机构箱、35kV C326低抗C32627地刀机构箱分别悬挂“在此工作！”标示牌；2、在35kV C324低抗C3242刀闸、35kV C324低抗C32427地刀、35kV C326低抗C3262刀闸、35kV C326低抗C32627地刀加热器及照明电源QF2空气开关处粘贴“禁止合闸，有人工作”标签。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031145', '2022-01-27 17:51:35', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '688c5527d00b4664ad9732e589020468', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7dd6a985bcaa4fe9aa4319e3fe692aaa', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 18:15:36', '0101', '无。', NULL, '在主控楼201通讯机房：48P广东省网B网MSTP设备屏、47P省网DDF配线屏、46P广东省网A网MSTP设备屏、45P站外ODF配线屏、44P站内ODF配线屏、43P录音系统屏、42P程控交换机屏、41PVDF配线屏、40P广州中调PCM设备屏、39P广东中调PCM设备屏、38P南网PCM设备屏、37P态势感知设备屏、36P动力环境监控系统屏、35POTN光设备1屏、52P调度数据网接入设备屏、53P南网B网MSTP设备屏、54P南网B网DDF配线屏、55P南网A网ASON设备屏、56P南网A网DDF配线屏、57P南网A网光路子系统设备屏、1P直流配电屏1、2P高频开关电源屏1、3P交流配电屏、4P高频开关电源屏2、5P直流配电屏2、6P广东ONT设备柜1、7P广东ONT设备柜2、8P国网南延线华为光放设备屏、9P国网南延线华为SDH屏、10P南网OTN光设备屏，202站公用控制保护室：=20TX01+X1 二次安全防护屏前后悬挂“在此工作”标示牌，并在相邻屏柜粘贴“运行设备”警示带；在203通信蓄电池室1：48V 通信蓄电池组1-1、48V 通信蓄电池组1-2，204通信蓄电池室2：48V 通信蓄电池组2-1、48V 通信蓄电池组2-2，500kV从木甲线、500kV从木丁线、500kV门从乙线、500kV花从乙线、500kV库从乙线OPGW光缆引下线构架处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012099', '2022-01-18 18:15:36', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ac42cdff00f044ceb4ca4952bc903801', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7de3435336454efdb315145cb53a1aa4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、500kV桂林变电站侧：拉开50332、50311隔离开关；2、500kV贤令山变电站侧：拉开50311、50322隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-31 06:12:19', '0104', NULL, NULL, '1、500kV桂林变电站侧：在500kV桂山乙线路CVT端子箱内所有二次电压空气开关及50332、50311隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌；2、500kV 贤令山变电站侧：在500kV桂山乙线线路CVT端子箱内所有二次电压空气开关及 50311、50322隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、工作负责人张源，联系电话：15877006770； 2、输电管理所值班人员王忠国，联系电话13517807719；3、工作票签发人赵斌，联系电话：13633089013；4、确认全部接地刀闸处于打开状态。', '0104091310', '2022-01-31 06:12:19', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, '1、500kV桂林变电站侧：合上503367接地刀闸；2、500kV贤令山变电站侧：合上503167接地刀闸。', NULL, '2e6f81ad27214aacbc8b98b7b53f7d90', NULL, '1、现场为自动融冰接线装置,人员在地面操作，无需登塔。如需登塔作业，作业塔位两端必须挂接接地线；2、绝缘架空地线（含OPGW光缆）及其引线有感应电。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7de87619f8584499911f38b80aa1a5dd', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-01 15:50:21', '0108', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-01 15:50:21', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '47bb32b99aaa4a23ba9c7eb2cb0f3940', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7e01b64825774d6f9fa4de0b1fb14d90', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、500kV黎平变电站断开500kV施黎甲线5041开关、500kV第四串联络5042开关； 500kV黎平变电站拉开500kV施黎甲线50411刀闸、500kV施黎甲线50412刀闸、500kV第四串联络50421刀闸、500kV第四串联络50432刀闸； 2、500kV施秉变电站断开500kV施黎甲线5031开关、500kV第三串联络5032开关； 500kV施秉变电站拉开500kV施黎甲线50311刀闸、500kV施黎甲线50312刀闸、500kV第三串联络50321刀闸、500kV第三串联络50332刀闸。', NULL, NULL, '0.000000000000000', '2022-01-29 16:07:43', '0102', NULL, NULL, '1、分别在500kV黎平变电站500kV施黎甲线5041开关、500kV第四串联络5042开关、500kV施黎甲线50411刀闸、500kV施黎甲线50412刀闸、500kV第四串联络50421刀闸、500kV第四串联络50432刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 2、分别在500kV施秉变电站500kV施黎甲线5031开关、500kV第三串联络5032开关、500kV施黎甲线50311刀闸、500kV施黎甲线50312刀闸、500kV第三串联络50321刀闸、500kV第三串联络50332刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 3、分别在500kV黎平变电站500kV施黎甲线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌； 4、分别在500kV施秉变电站500kV施黎甲线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人：18798072837，线路融冰工作组组长：18286025058。', '0102109705', '2022-01-29 16:07:43', NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, '1、500kV黎平变电站合上500kV施黎甲线504167接地刀闸； 2、500kV施秉变电站合上500kV施黎甲线503167接地刀闸。', NULL, '4f140b58e82f4b0498de9e913c20caf3', NULL, '1、验电及挂、拆接地线时必须戴绝缘手套，人体应保持与验电器连接线、地线接地线1.5m安全距离并有专人监护。验电必须使用合格的±10kV闭合式回路验电器；挂接地线时应先接接地端，后接导线端，拆接地线时程序与此相反； 2、工作负责人必须得到线路融冰工作组组长下达可以开展分闸工作指令后进入工作现场，方可组织工作班人员开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路； 3、登塔前必须检查所用安全用具、工器具是否完好，操作是否灵活，严禁使用不合格的安全用具和工器具； 4、人体应保持与架空地线、操作机构箱应保持1.5m安全距离； 5、高空作业须严格遵守《超高压输电公司防止高空坠落的措施》的规定，工作人员上下塔、进出绝缘子串等必须使用双控全身式高空安全带交叉保护，高空作业任何时刻不得失去安全带（绳）的保护。严格遵守《超高压输电公司防止人身伤亡事故守则》，多人同时登塔或高处作业时，不能有两个及以上人员处于同一垂直面； 6、现场人员必须戴安全帽，登塔或在塔上作业时，每基杆塔均设专人监护，监护人必须始终在现场并认真监护，及时纠正不安全的行为； 7、其余安全注意事项必须严格按照经批准的《500kV施黎甲线防冰工作手册（2021-2022年）》所列安全措施执行； 8、只需要操作500kV施黎甲线普通地线第033#-176#段融冰对应的接线装置和接地刀闸； 9、工作结束后，工作负责人必须确认工作人员已全部下塔，且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7e13da84b1d9443f8ca6738dc20b2c97', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-04 15:16:08', '0103', '退出继电保护室7P #P1B主变第一套电气量保护柜  #P1B主变第一套电气量保护PRS-778S 跳P5023 #1线圈 1LP1压板、#P1B主变第一套电气量保护PRS-778S 跳P5022 #1线圈 1LP2压板、#P1B主变第一套电气量保护PRS-778S 跳P2011 #1线圈 1LP3压板、#P1B主变第一套电气量保护PRS-778S 跳P2012 #1线圈 1LP4压板、#P1B主变第一套电气量保护PRS-778S 跳P314 1LP5压板、#P1B主变第一套电气量保护PRS-778S 跳P311 1LP6压板、#P1B主变第一套电气量保护PRS-778S 跳P312 1LP7压板、#P1B主变第一套电气量保护PRS-778S 跳P313 1LP8压板、#P1B主变第一套电气量保护PRS-778S 投差动保护 1LP19压板、#P1B主变第一套电气量保护PRS-778S 投高压侧后备保护 1LP20压板、#P1B主变第一套电气量保护PRS-778S 投高压侧零序保护 1LP21压板、#P1B主变第一套电气量保护PRS-778S 投过激磁保护 1LP22压板、#P1B主变第一套电气量保护PRS-778S 投高压侧电压 1LP23压板、#P1B主变第一套电气量保护PRS-778S 投中压侧后备保护 1LP24压板、#P1B主变第一套电气量保护PRS-778S 投中压侧零序保护 1LP25压板、#P1B主变第一套电气量保护PRS-778S 投中压侧电压 1LP26压板、#P1B主变第一套电气量保护PRS-778S 投低压侧后备保护 1LP27压板、#P1B主变第一套电气量保护PRS-778S 投低压侧电压 1LP28压板、#P1B主变第一套电气量保护PRS-778S 投公共绕组后备保护 1LP29压板、#P1B主变第一套电气量保护PRS-778S 投低压侧总后备保护 1LP30压板。', NULL, '在继电保护室7P #P1B主变第一套电气量保护柜前挂“在此工作！”标示牌，将工作屏内的非工作设备面板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-001]', 'EXtCuSGl', '2022-01-04 15:16:08', NULL, '38', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4d812733a9324f469ae7079b4849c40a', NULL, '无', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7e4eef57163c4aed98fde95872296139', NULL, NULL, '50411、50422。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-06 17:14:12', '0104', '1、断开50411、50422隔离开关电机电源空气开关QF1、控制电源空气开关QF2；\\r\\n2、退出9P 500kV #1M第一套保护屏以下连接片：LP11（母差保护BP-2B跳5011断路器#1线圈）、LP12（母差保护BP-2B跳5021断路器#1线圈）、LP13（母差保护BP-2B跳5032断路器#1线圈）、LP15（母差保护BP-2B跳5051断路器#1线圈）、LP16（母差保护BP-2B跳5061断路器#1线圈）。', NULL, '1、在50411隔离开关现场操作机构处挂检修隔离锁，在50411、50422隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，并在监控系统监控界面50411、50422隔离开关处作“禁止合闸 有人工作”标识；\\r\\n2、在主控室：新监控工作站1放置“在此工作”标示牌；\\r\\n3、51保护小室：9P 500kV #1M第一套保护屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n4、在52保护小室：26P 500kV第四串联络5042断路器保护屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n在相关停电设备工作区域装设安全围栏，围栏内的设备包括：500kV第四串联络5042断路器汇控箱及三相机构箱，并在围栏上向内悬挂“止步 高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-005]\\r\\n秦先坤，2021年12月02日10时00分', 'EXtCuSGl', '2022-01-06 17:14:12', NULL, '35', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'b14dc6aa640f44b48b1d62c69bad4a9a', NULL, '本任务中工作地点如有其它班组交叉作业而影响安全作业的，工作负责人需向工作总协调人提出工作申请，由工作总协调人现场安排，确保现场工作安全有序。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7e57a76ca0e64705b2d14687a51815e8', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 10:00:49', '0104', '无。', NULL, '在500kV来宾变电站微波机房：E02 调度数据网设备前后悬挂“在此工作”标示牌，并在相邻运行屏柜设置“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040810', '2022-01-18 10:00:49', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a7e2ed117cc2459e87e4d2581f0c0460', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7eb96ecc0e2d4fbbad9ed50caa98588b', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 16:51:18', '0103', '无。', NULL, '在105通信机房B7 广西ODF配线屏前后悬挂“在此工作！”标示牌，将工作屏柜内非工作设备的面板、背板用红色绝缘胶布封贴，将与工作屏柜同一排和相邻排的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-14 16:51:18', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fa3c685389cd42a3b15758ffe2381999', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f0b4c03f0474d0792f6c165ae2c4371', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 17:54:14', '0103', '无。', NULL, '在105通信机房B7 广西ODF配线屏前后悬挂“在此工作！”标示牌，将工作屏柜内非工作设备的面板、背板用红色绝缘胶布封贴，将与工作屏柜同一排和相邻排的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-10 17:54:14', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'e6870443e44a4a2894b055158ee52e00', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f15912cd2044126bd51008ccf8bee6a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、500kV黎平变电站断开500kV施黎乙线5051开关、500kV第五串联络5052开关； 500kV黎平变电站拉开500kV施黎乙线50511刀闸、500kV施黎乙线50512刀闸、500kV第五串联络50521刀闸、500kV第五串联络50532刀闸； 2、500kV施秉变电站断开500kV施黎乙线5021开关、500kV第二串联络5022开关； 500kV施秉变电站拉开500kV施黎乙线50211刀闸、500kV施黎乙线50212刀闸、500kV第二串联络50221刀闸、500kV第二串联络50232刀闸。', NULL, NULL, '0.000000000000000', '2022-01-28 09:28:29', '0102', NULL, NULL, '1、分别在500kV黎平变电站500kV施黎乙线5051开关、500kV第五串联络5052开关、500kV施黎乙线50511刀闸、500kV施黎乙线50512刀闸、500kV第五串联络50521刀闸、500kV第五串联络50532刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 2、分别在500kV施秉变电站500kV施黎乙线5021开关、500kV第二串联络5022开关、500kV施黎乙线50211刀闸、500kV施黎乙线50212刀闸、500kV第二串联络50221刀闸、500kV第二串联络50232刀闸远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 3、分别在500kV黎平变电站500kV施黎乙线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌； 4、分别在500kV施秉变电站500kV施黎乙线电压互感器端子箱主一保护A相电源MCB21空气开关、B相电源MCB22空气开关、C相电源MCB23空气开关，主二保护A相电源MCB31空气开关、B相电源MCB32空气开关、C相电源MCB33空气开关，测量及计量A相MCB11空气开关、B相MCB12空气开关、测量及计量C相MCB13空气开关悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人：18798073210；线路融冰工作组组长崔健：18286025058。', '0102109705', '2022-01-28 09:28:29', NULL, '36', NULL, NULL, NULL, NULL, NULL, NULL, '1、500kV黎平变电站合上500kV施黎乙线505167接地刀闸； 2、500kV施秉变电站合上500kV施黎乙线502167接地刀闸。', NULL, 'eb8f2c53d8454a83a48c60e3bbfebf23', NULL, '1、验电及挂、拆接地线时必须戴绝缘手套，人体应保持与验电器连接线、地线接地线1.5m以上安全距离并有专人监护。验电必须使用35kV专用合格闭合式回路验电器；挂接地线时应先挂接地端，后挂导线端，拆接地线时程序与此相反； 2、工作负责人必须得到线路融冰工作组组长下达可以开展分闸工作指令后再进入工作现场，方可组织工作班人员开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路； 3、登塔前必须检查所用安全用具、工器具是否完好，操作是否灵活，严禁使用不合格的安全用具和工器具； 4、人体应保持与架空地线、操作机构箱至少1.5m以上的安全距离； 5、高空作业须严格遵守《超高压输电公司防止高空坠落的措施》的规定，工作人员上下塔、进出绝缘子串等必须使用双控全身式高空安全带交叉保护，高空作业任何时刻不得失去安全带（绳）的保护。严格遵守《超高压输电公司防止人身伤亡事故守则》，多人同时登塔或高处作业时，不能有两个及以上人员处于同一垂直面； 6、现场人员必须戴安全帽，登塔或在塔上作业时，每基杆塔均设专人监护，监护人必须始终在现场并认真监护，及时纠正不安全的行为； 7、其余安全注意事项必须严格按照经批准的《500kV施黎乙线防冰工作手册（2021-2022年）》所列安全措施执行； 8、只需要操作500kV施黎乙线普通地线第034#-335#段对应的接线装置和接地刀闸； 9、工作结束后，工作负责人必须确认工作人员已全部下塔，且塔上无遗留物，方可办理工作票终结手续；10、工作结束后，工作负责人必须确认工作人员已全部下塔，且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f28618c530e420ab9c50451c22c1bc4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 11:15:40', '0104', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-024]', 'EXtCuSGl', '2022-01-19 11:15:40', NULL, '52', NULL, '1、在户外直流场沥青路安健环标识划线补充区域施工处设置安全围栏，在围栏上向内设置“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌。2、在户外直流场绿化养护施工区域、直流场区域设备基础保护帽施工区域、电子器件备品库及车库施工区域、直流继电器小室施工区域、2个备用直流电抗室施工区域悬挂“在此工作”标识牌。3、工作人员进入生产场所必须正确佩戴安全帽。4、工作时必须全程有人监护，不得扩大工作范围，工作人员带电保持足够的安全距离：±800kV保持10.1米以上的安全距离、±50kV及以下保持1.5米以上的安全距离。', NULL, NULL, NULL, NULL, NULL, NULL, '8764d9a26b334afdbdd3c0ca72002ca3', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f39fb92606a4e8ab610cad57ddab28e', NULL, '无。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 21:48:36', '0102', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人：18798073210。', '0102109705', '2022-01-18 21:48:36', NULL, '11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0f701343fc04420396177f4ba3563995', NULL, '1、所有工作人员须保持良好的精神状态；2、工作前必须检查工器具、资料等，确保准备齐全，工器具检查合格后可使用；3、登塔前，必须核对线路名称、塔号无误后，方可登塔作业，防止误登杆塔；4、登塔前，应观察塔上有无危及人员安全的隐患，若有需采取安全措施后才能作业；5、现场所有工作人员必须正确佩戴安全帽，穿全套合格的屏蔽服，且各部件连接要牢靠，上下塔使用双控全身式高空安全带,在转位或作业过程中时，不得失去安全带的保护；安全带应采用环绕主材方式系在牢固的构件上，采用高挂低用的方式进行作业； 6、工作过程中，严格执行工作监护制度：作业时，监护人必须对工作人员的安全认真监护，及时纠正、制止不安全行为；7、同一塔上作业时，不允许同一垂直线多人上、下塔或作业，以防掉物伤人；上下塔过程中及塔上作业严禁吸烟；8、工作过程中如遇到雷、雨、雪、雾、风力大于5级等恶劣天气、塔上有蜂窝或其他威胁人员及设备安全的情况时，必须立即停止工作并向工作负责人汇报；9、杆塔上作业时必须与带电体保持5米以上的安全距离；10、在带电登塔过程中，如遇线路突然停电，作业人员应视线路仍然带电；11、杆塔上作业时必须与绝缘架空地线（含OPGW）保持0.4米以上的安全距离，如需在架空地线上进行作业，需使用架空地线短接线将绝缘架空地线进行短接，挂设接地线时，必须先挂接地端，后挂地线端；12、人员操作刀闸必须带绝缘手套，不得直接接触刀闸任何部位；13、工作结束后，工作负责人必须确认工作人员已全部下塔，地线接地线已拆除且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f3d7c25fe8042d2b57d1872f8fcf81a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 16:40:59', '0104', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01040808', '2022-01-25 16:40:59', NULL, '25', NULL, '1、在35kV设备区旁的备用CT存放处装设安全围栏，并在围栏上向内悬挂“止步 高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌；2、进入设备区必须正确佩戴安全帽和穿戴长袖棉质工作服；3、严禁触碰与工作无关的设备；3、高空车必须接地良好，设置限高绳，满足高空车使用的的安全距离220kV设备 6.00米，35kV设备4.00米），防止高空车作业转动中误碰存放物资；4、工作结束后清理现场及带出使用的工具；5、工作负责人全程做好监护；6、工作过程中人员要与带电设备保持足够的安全距离：220kV设备3.00米，35kV设备1.00米。', NULL, NULL, NULL, NULL, NULL, NULL, '4017001492aa417c82a72351540a4b25', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f4a8d3b6fc046148e87b90625b4cc23', NULL, NULL, '20711、20722。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 15:36:23', '0107', '1、分别断开20711、20722隔离开关电机电源空开QF1和控制电源空开QF2； \\r\\n2、分别断开鲁马I线电压互感器端子箱内空开MCB1：至第七串测控屏A、鲁马I线保护屏一；MCB2：至第七串测控屏B、鲁马I线保护屏二；MCB3：至220kV关口电度表屏三；MCB5：至2071断路器保护屏空开； \\r\\n3、#2继电器室：分别断开P12=CBP71 220kV 2071断路器保护屏中2071断路器CZX-22G操作箱第一路直流电源空开4K1和2071断路器CZX-22G操作箱第二路直流电源空开4K2；\\r\\n4、#2继电器室：分别断开P13=CBP72 220kV 2072断路器保护屏中2072断路器CZX-22G操作箱第一路直流电源空开4K1和2072断路器CZX-22G操作箱第二路直流电源空开4K2；\\r\\n5、#2继电器室：P12 220kV 2071断路器保护屏：退出RCS-921A重合闸出口3LP4压板，并将2071断路器重合闸切换把手切至“停用”位置；\\r\\n6、#2继电器室：P13 220kV 2072断路器保护屏：退出RCS-921A保护重合闸出口3LP4压板，并将2072断路器重合闸切换把手切至“停用”位置；\\r\\n７、分别断开#2继电器室内交流电源分配屏-F107：2071开关间隔交流电源、-F108：2072开关间隔交流电源空开。', NULL, '1、分别在20711、20722隔离开关电机电源QF1和控制电源QF2上悬挂“禁止合闸，有人工作！”标示牌； \\r\\n2、分别在鲁马I线电压互感器端子箱内空开MCB1：至第七串测控屏A、鲁马I线保护屏一；MCB2：至第七串测控屏B、鲁马I线保护屏二；MCB3：至220kV关口电度表屏三；MCB5：至2071断路器保护屏空开上悬挂“禁止合闸，有人工作！”标示牌； \\r\\n3、#2继电器室：分别在P12=CBP71 220kV 2071断路器保护屏中2071断路器CZX-22G操作箱第一路直流电源空开4K1和2071断路器CZX-22G操作箱第二路直流电源空开4K2上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、#2继电器室：分别在P13=CBP72 220kV 2072断路器保护屏中2072断路器CZX-22G操作箱第一路直流电源空开4K1和2072断路器CZX-22G操作箱第二路直流电源空开4K2上悬挂“禁止合闸，有人工作！”标示牌； \\r\\n5、分别在#2继电器室内交流电源分配屏-F107：2071开关间隔交流电源、-F108：2072开关间隔交流电源空开上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n6、分别在监控系统20711、20722隔离开关上装设“禁止合闸，有人工作！”电子标示牌； \\r\\n7、在2071、2072断路器，20712、20716、20721隔离开关，207127、207167、2071617、207217接地刀闸四周设置围栏，并在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏出入口悬挂“在此工作！”和“从此进出！”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01070103', '2022-01-20 15:36:23', NULL, '24', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '671b9e8e7c91480d8469c5b0aeaa1bf3', NULL, '无。', '1、207117、207227； 2、分别在220kV鲁马Ⅰ线线路电压互感器 A、B、C相出线处装设1组220kV单相接地线。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7f8f366359b842dab1ddd0ba09cf6cd6', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-08 07:21:01', '0102', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-08 07:21:01', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '7af9bdc7ecbc4e44a04f8693f29ed88e', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('7fac0d2b9fa547a981cac6860ab5b4d4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 02:11:41', '0104', '无。', NULL, '1、在22保护小室：15P PMU同步相量测量装置屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n2、在23保护小室：5P 220kV桂渡Ⅲ线测控屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识；\\r\\n3、在51保护小室：33P PMU同步相量测量屏前悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-004]', 'EXtCuSGl', '2022-01-15 02:11:41', NULL, '32', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '94a01e02381b43939dcd59074f31a2ba', NULL, '无。', NULL, NULL, '不停电。');
