INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('826d1475a56f47fabfa2957710ed3a42', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-08 18:48:17', '0102', '无。', NULL, '1、在通信室B04 南网综合（ODF+网A DDF）配线屏处悬挂“在此工作！”标示牌； 2、分别在通信室B03南网烽火PCM设备屏、B05南网网A（OMS1684）光传输屏前后悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人联系电话：13595011534。', '01020704', '2022-01-08 18:48:17', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7051f4529f004aa08de310b772aa48c3', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('8286cf26604f422eaf6ab98c5fc00f28', NULL, NULL, '50421、50422、50431、50432。 ', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 18:26:31', '0101', '（1）分别断开50421、50422、50431、50432刀闸控制电源空开QF3和电机电源空开QF1。\\r\\n（2）分别断开5042、5043开关第一跳闸电源开关4DK1和第二跳闸电源开关4DK2。 \\r\\n（3）断开500kV从木甲线PT端子箱（20B04.C+UT5）内二次空开：A相计量电压二次空气开关1MCBa、B相计量电压二次空气开关1MCBb、C相计量电压二次空气开关1MCBc、主一保护、安稳A、断路器保护、功角测量电压二次空气开关2MCB、主二保护、安稳B、故障录波、选相合闸电压二次空气开关3MCB、监控测量A电压二次空气开关4MCB、监控测量B电压二次空气开关5MCB。', NULL, '（1）分别在50421、50422、50431、50432刀闸控制电源空开QF3及电机电源空开QF1和操作把手处悬挂“禁止合闸，有人工作！”标示牌。\\r\\n（2）分别在5042、5043开关第一跳闸电源4DK1开关和第二跳闸电源4DK2开关处悬挂“禁止合闸，有人工作！”标示牌。\\r\\n（3）分别在500kV从木甲线PT端子箱（20B04.C+UT5）内二次空开：A相计量电压二次空气开关1MCBa、B相计量电压二次空气开关1MCBb、C相计量电压二次空气开关1MCBc、主一保护、安稳A、断路器保护、功角测量电压二次空气开关2MCB、主二保护、安稳B、故障录波、选相合闸电压二次空气开关3MCB、监控测量A电压二次空气开关4MCB、监控测量B电压二次空气开关5MCB处悬挂“禁止合闸，有人工作！”标示牌。\\r\\n（4）在5042、5043开关本体、机构箱、就地控制柜，50422刀闸、50431刀闸、504217地刀、504227地刀、504317地刀、504327地刀、504367地刀本体及其操作机构箱、500kV从木甲线避雷器F1本体四周装设围栏，向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”和“在此工作”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '（1）工作过程中需多次分合5042、5043开关。（2）工作过程中需多次分合5042、5043开关第一跳闸电源4DK1开关和第二跳闸电源4DK2开关。（3）工作过程中需多次分合50422、50431刀闸控制电源空开QF3和主电源空开QF1。（4）工作过程中需多次分合50422刀闸、50431刀闸、504217地刀、504227地刀、504317地刀、504327地刀、504367地刀。 \\r\\n', '01012006', '2022-01-20 18:26:31', NULL, '30', NULL, NULL, NULL, NULL, '5042、5043。', NULL, NULL, NULL, '03269bc646cb45239758b4c34c6074e2', NULL, '对50421、50422、50431、50432刀闸实施机构上锁。', '504217、504227、504317、504327、504367，在500kV从木甲线避雷器F1靠线路侧装设一组500kV分相短路式接地线。', NULL, NULL);
