INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('8612b5ad6c964837a47d7fedd319560e', NULL, '本工作不需退出500kV梧罗II线线路重合闸装置 。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 14:44:21', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '无', '0101100202', '2022-01-14 14:44:21', NULL, '14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'b8612da6e1ec4d488dbf16e4e3e1864b', NULL, '1、登塔人员应穿全套合格的屏蔽服或静电防护服，且各部分连接可靠； 2、塔上作业人员与绝缘架空地线的安全距离不得小于0.4m； 3、塔上作业人员、工具、材料与带电体安全距离不得小于5m； 4、塔上作业人员转移及作业过程中不得失去安全带的保护，现场所有工作人员须正确佩戴安全帽； 5、作业应在良好天气下进行，遇雷、雨、雾、5级及以上大风时，不得进行作业。', NULL, NULL, NULL);
