INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('92ff1531f3f74be49f643f7be5986846', NULL, '无', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 09:03:20', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '0101100202', '2022-01-26 09:03:20', NULL, '12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '8435a5b907ac4691ab5a5c2508c39bab', NULL, '1、高处作业应正确使用安全带，攀登杆塔和转移位置时不应失去安全带的保护； 2、严禁上下抛掷物品； 3、现场所有作业人员必须正确佩戴安全帽； 4、登塔人员应穿全套合格的屏蔽服或静电防护服，且各部分连接可靠； 5、作业应在良好天气下进行，遇雷、雨、雾、雹不应进行带电作业，5级及以上大风时，应停止在带电线路杆塔上的作业； 6、工作人员、工具和材料与带电体之间的安全距离不小于1m。', NULL, NULL, NULL);
