INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('935cc71f1a0f4b2195220e8f488ecf30', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-13 11:47:18', '0101', '无。', NULL, '分别在±800kV直流场、500kV换流变区域、500kV交流场、500kV交流滤波器场、500kV #2主变区域、500kV站用电区域、220kV GIS区域、110kV站用电区域、35kV站用电区域处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012004', '2022-01-13 11:47:18', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0e3252baa66f4c40a4a1c159a55303e4', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('93cdffee377d4fb289344b3804034bba', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 18:19:12', '0101', '退出500kV增穗甲线主二/辅B保护屏（=20B05+R12）内以下压板：1LP1 主二保护RCS-931DMM跳5051 A相#2线圈压板；1LP2 主二保护RCS-931DMM跳5051 B相#2线圈压板；1LP3 主二保护RCS-931DMM跳5051 C相#2线圈压板；1LP5 主二保护RCS-931DMM跳5052 A相#2线圈压板；1LP6 主二保护RCS-931DMM跳5052 B相#2线圈压板；1LP7 主二保护RCS-931DMM跳5052 C相#2线圈压板；1LP9 主二保护RCS-931DMM启动5051开关A相失灵及重合闸压板；1LP10 主二保护RCS-931DMM启动5051开关B相失灵及重合闸压板；1LP11 主二保护RCS-931DMM启动5051开关C相失灵及重合闸压板；1LP12 主二保护RCS-931DMM启动5052开关A相失灵及重合闸压板；1LP13 主二保护RCS-931DMM启动5052开关B相失灵及重合闸压板；1LP14 主二保护RCS-931DMM启动5052开关C相失灵及重合闸压板；1LP15 主二保护RCS-931DMM闭锁5051重合闸压板；1LP16 主二保护RCS-931DMM闭锁5052重合闸压板；1LP17主二保护RCS-931DMM投入零序保护压板；1LP18主二保护RCS-931DMM投入距离保护压板；1LP19主二保护RCS-931DMM投入通道A差动保护压板；1LP20主二保护RCS-931DMM投入通道B差动保护压板；1LP21主二保护RCS-931DMM投入检修状态压板在退出位置；9LP1辅B保护RCS-925A投入检修状态压板；9LP2辅B保护RCS-925A投入过电压保护压板；9LP3 辅B保护RCS-925A跳5051三相#2线圈压板；9LP4 辅B保护RCS-925A跳5052三相#2线圈压板；9LP8 辅B保护RCS-925A过压启动增穗甲线通道一发信二压板；9LP9 辅B保护RCS-925A过压启动增穗甲线通道二发信二压板；9LP10 辅B保护RCS-925A通道一收信输入压板；9LP11 辅B保护RCS-925A通道二收信输入压板。', NULL, '在500kV #2继保室：500kV 增穗甲线主二/辅B保护屏（=20B05+R12）前后悬挂“在此工作”标示牌，并在相邻运行屏柜粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012002', '2022-01-07 18:19:12', NULL, '36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a7145dcd00cf49499fbbb72cb98f67ec', NULL, '无', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('93e334e50af041ee8b64a09e4ba0a627', NULL, NULL, '5841。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 18:55:31', '0108', '1、断开RH3-709J 500kV 584交流滤波器第一套保护柜内4K1 584开关第一组控制电源空开、4K2 584开关第二组控制电源空开； \\r\\n2、断开500kV 584交流滤波器584开关汇控箱内8MA 584断路器A相电机空开、8MB 584断路器B相电机空开、8MC 584断路器C相电机空开；\\r\\n3、断开500kV 584交流滤波器5841刀闸A、B、C相机构箱电机电源空开F1，B相机构箱5841刀闸就地控制电源空开F3。', NULL, '1、在500kV 5841刀闸A、B、C相机构箱内相应操作处悬挂“禁止合闸，有人工作！”标示牌； \\r\\n2、在主控室监控系统后台上500kV 5841刀闸相应操作处设置“禁止合闸，有人工作！”标示； \\r\\n3、在500kV 584开关A、B、C相本体及开关汇控箱上悬挂“在此工作！”标示牌； \\r\\n4、在500kV 584开关A、B、C相本体及开关汇控箱周围装设安全围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏入口处悬挂“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01080805', '2022-01-27 18:55:31', NULL, '23', NULL, NULL, NULL, NULL, ' 584。', NULL, NULL, NULL, '20e87ea640b8481fb3cdc63e1dce2f41', NULL, '无。', '无。', NULL, NULL);
