INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('9598df02b33f4990ab2bde0b0a422564', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 11:02:21', '0102', '无。', NULL, '1、分别在主控楼主控室视频监控系统，门卫室视频监控系统，主控楼通信机房4 A07 图像监控系统控制柜，门卫室电子围栏总控制箱，电子围栏分区控制箱，水泵房2P 消防电源切换柜、3P 消防泵控制柜、4P 消防泵应急启动柜、5P 消防稳压泵控制柜、#1消防泵、#2消防泵、#3消防泵、#4消防泵、#5稳压泵，雨淋间#1B主变A、B、C相雨淋阀，#2B主变A、B、C相雨淋阀，#3B主变A、B、C相雨淋阀，大门防冲撞桩、主控楼安稳及监控室1P 火灾报警系统控制屏处悬挂“在此工作！”标示牌；2、在主控楼通信机房4 A06 交流配电屏处悬挂“运行设备” 红布；3、分别在安稳及监控室0P 综合处理单元屏、2P 南网总调智能远动屏处悬挂“运行设备”红布。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13765099883。', '01021422', '2022-01-27 11:02:21', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ca4305aae1454f0d8ca490d054dcc9e1', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('95a1067e91994f40b8de9a52a93003f9', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 16:36:56', '0102', '无。', NULL, '1、在31小室2P 31小室公共测控装置屏2处悬挂“在此工作！”标示牌；\\r\\n2、分别在31小室1P 31小室时钟同步扩展屏处悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13985598292。', '01020703', '2022-01-21 16:36:56', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '8be5c3b0c788430e8b04bcd938c6047a', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('95a67e875f224d37bf93ac4cef3fac6d', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 16:38:17', '0101', '无', NULL, '在通信机房B02（5P）南网A网马可尼光纤传输屏、B01（4P）ODF配线单元屏、#1通信直流系统电源屏、#2通信直流系统电源屏前后悬挂“在此工作！”标示牌，并在相邻屏粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '0101111202', '2022-01-12 16:38:17', NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0f2fd671991c4fe3ba0b1ecf2da39fc4', NULL, '1、工作负责人必须严格执行工作票制度，现场对安全措施、技术措施和作业任务及操作危险点和控制措施交底。 2、工作负责人确认作业人员应具备良好的精神状态，工作时要精力集中，睡眠不好、精神不佳者，禁止作业。 3、工作负责人必须严格、认真执行现场监护。 4、工作开始前须认真检查工器具，发现异常或不满足要求者严禁使用。4、在工作现场装设移动监控平台。', NULL, NULL, '不停电');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('95a8cef008d8404cbfda1a8101c9ca16', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 19:28:25', '0102', '无。', NULL, '在机器人服务器、主控室办公电脑、调度指挥网络交互终端、#1操作员工作站、#2操作员工作站、调度台、五防系统工作站、融冰系统工作站、视频监控系统工作站、主控室主控桌悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13985550991。', '01021421', '2022-01-21 19:28:25', NULL, '28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'd056a5b2a06c4fc484cd5433b6c0df64', NULL, '无。', NULL, NULL, '不需要停电。');
