INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('963c91a639b246b4bf09166330b053b8', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、500kV桂林变电站侧：拉开50332、50311隔离开关；2、500kV贤令山变电站侧：拉开50311、50322隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-31 02:08:53', '0104', NULL, NULL, '1、500kV桂林变电站侧：在500kV桂山乙线路CVT端子箱内所有二次电压空气开关及50332、50311隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌；2、500kV 贤令山变电站侧：在500kV桂山乙线线路CVT端子箱内所有二次电压空气开关及 50311、50322隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、工作负责人张源，联系电话：15877006770； 2、输电管理所值班人员王忠国，联系电话13517807719；3、工作票签发人赵斌，联系电话：13633089013；4、确认全部接地刀闸处于打开状态。', '0104091310', '2022-01-31 02:08:53', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, '1、500kV桂林变电站侧：合上503367接地刀闸；2、500kV贤令山变电站侧：合上503167接地刀闸。', NULL, '3a4efd0f9f384fd1841958ba14c606e9', NULL, '1、现场为自动融冰接线装置,人员在地面操作，无需登塔。如需登塔作业，作业塔位两端必须挂接接地线；2、绝缘架空地线（含OPGW光缆）及其引线有感应电。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('9647b1ec5ec74fddac81cccc5a91f32d', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 18:15:31', '0104', '无。', NULL, '在500kV #1站用变500kV侧避雷器、500kV #2站用变500kV侧避雷器、500kV #2站用变35kV侧避雷器、500kV换如甲线避雷器、500kV换如乙线避雷器、500kV换柳甲线避雷器、500kV换柳乙线避雷器、500kV极1低端换流变网侧避雷器F1、500kV极1高端换流变网侧避雷器F1、500kV极2低端换流变网侧避雷器F1、500kV极2高端换流变网侧避雷器F1三相动作计数器处；500kV #1站用变500kV侧CVT端子箱、500kV #2站用变500kV侧CVT端子箱、35kV #2M母线CVT端子箱、500kV换如甲线CVT端子箱、500kV换如乙线CVT端子箱、500kV换柳甲线CVT端子箱、500kV换柳乙线CVT端子箱、500kV极1低端换流变网侧CVT端子箱、500kV极1高端换流变网侧CVT端子箱、500kV极2低端换流变网侧CVT端子箱、500kV极2高端换流变网侧CVT端子箱本体处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040818', '2022-01-21 18:15:31', NULL, '28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ef09d118ac8341cabf829e98de06d0b7', NULL, '无。', NULL, NULL, '不停电。');
