INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('9844947e732a49478015e403d1242883', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 15:50:31', '0104', '无。', NULL, '在继电保护室：62P 集控站通讯装置屏、166P 220kV 02高备变测控屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040809', '2022-01-30 15:50:31', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'c8660182fb2c46119f9a67c947a11c6c', NULL, '无。', NULL, NULL, '不需要停电。');
