INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('996312e5d02d4553bb0c51e7f35a54dc', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-09 16:02:16', '0107', '无。', NULL, '1、中央控制室314：分别在运行人员工作站1、运行人员工作站2、运行人员工作站3、运行人员工作站4、运行人员工作站5上悬挂“在此工作！”标示牌；分别在天生桥站图像监控系统、自动功率曲线工作站1/2上悬挂“运行设备”标示牌及红布；\\r\\n2、暂态故障录波室306：在工程师工作站上悬挂“在此工作！”标示牌；分别在保护信息工作站、电能计量工作站上悬挂“运行设备”标示牌及红布； \\r\\n3、中控楼三楼控制设备室301：分别在P2 极1换流变保护屏2、P4 极1极控屏A、P29 直流场远动RTU屏、P46 辅助系统接口屏、P54 辅助系统控制屏A、P55辅助系统控制屏B、P58 服务器屏1、P59 服务器屏2、P65 通讯接口屏A、P66 通讯接口屏B上悬挂“在此工作！”标示牌；分别在P1极1换流变保护屏1、 P5极1极控屏B、P45 直流站控屏B、P47 故障录波主机屏、P56 直流线路行波测距屏、P60 极2阀厅红外测温系统屏、P64 直流场就地控制屏、P67 视频图像监控系统控制A屏上悬挂“运行设备”标示牌；\\r\\n4、中控楼二楼载波光纤通信室209：分别在B07烽火780B光设备屏、C04调度数据网设备屏、C07中兴ASON光传输设备屏上悬挂“在此工作！”标示牌；分别在B06 马百线保护通信接口屏、C03 二次安防设备屏、C05 华为PCM设备屏、C06 中兴ASON光传输网超长距离设备屏、C08 中兴ASON光设备DDF配线屏上悬挂“运行设备”标示牌；\\r\\n5、中控楼一楼#1充电机室102：在P48 站公用直流主屏A1上悬挂“在此工作！”标示牌；分别在P47 站公用直流主屏A2、P49 站公用#1直流充电机屏上悬挂“运行设备”标示牌；\\r\\n6、中控楼一楼#2充电机室105：在P61 站公用直流主屏B1上悬挂“在此工作！”标示牌；分别在P60 站公用直流主屏B2、P62 站公用#2直流充电机屏上悬挂“运行设备”标示牌；\\r\\n7、在主控楼电缆层、主控楼电缆竖井门口悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '1、已开展补充安全交代：陈光武、王小吉 2021.12.18 09:11\\r\\n2、已开展补充安全交代：罗绍才  2021.12.19 09:29\\r\\n3、已开展补充安全交代：曾诚、熊尧 2021.12.19 14:42\\r\\n4、已开展补充安全交代：胡如丰 2021.12.20 09:38\\r\\n\\r\\n', '01070102', '2022-01-09 16:02:16', NULL, '51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '22c36e2a267e44e587c9b0644d564884', NULL, '无。', NULL, NULL, '不需要停电。');
