INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('99ffe66c61b649299fdfad0d27b721e2', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '±500kV宝安换流站侧：05105隔离开关、05121隔离开关、 05205隔离开关、05122隔离开关。 ±500kV兴仁换流站侧：05105隔离开关、05121隔离开关、 05205隔离开关、05122隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-13 09:49:41', '0101', NULL, NULL, '在±500kV宝安换流站侧：05105隔离开关、05121隔离开关、05205隔离开关、05122隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； 在±500kV兴仁换流站侧：05105隔离开关、05121隔离开关、05205隔离开关、05122隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人及电话：焦海龙13922773436。广州换流站联系电话：020-38123156，020-86398686-3131。广东能源发展有限公司工作负责人：毛扬文13416502058（工作任务1：对±500kV兴安直流及35kV安侧接地极污秽绝缘子进行清扫;工作任务2:对±500kV兴安直流及安侧接地极本体缺陷进行消缺；工作任务3：对±500kV兴安直流交叉跨越隐患治理项目进行施工；工作任务4：对兴安直流2416#-2417#（同塔架设安侧接地极93#-92#）档导地线接头补强。）、朱国明电话：13602860165(工作任务：对±500kV兴安直流2074#-2075#迁改段跨越汕湛高速（惠清段）迁改项目施工)、刀剑（13759042117）工作任务：清远220千伏白庙输变电工程220kV白庙至库湾双回线路工程）穿越±500kV兴安线改造项目施工）', '0101100201', '2022-01-13 09:49:41', NULL, '52', NULL, NULL, NULL, NULL, NULL, NULL, '±500kV宝安换流站侧：051217接地刀闸、 051227接地刀闸。 ±500kV兴仁换流站侧： 051217接地刀闸、 051227接地刀闸。', NULL, '2de575a0916146d088c73dee2cce6f51', NULL, '1、高空作业人员不得失去安全带的保护，工作现场应有专人监护； 2、严禁上下抛掷物品；3、现场所有作业人员必须正确佩戴安全帽； 4、线路作业应在良好的天气下进行，遇有雷雨、6级及以上大风、强对流等恶劣气象条件时，应停止工作； 5、邻近或交叉跨越带电线路施工需满足安全作业距离：10kV不小于1米，35kV不小于2.5米，110kV不小于3米，220kV不小于4米，500kV不小于6米，±500kV不小于7.8米；6、±500kV兴安直流交叉跨越信息：±500kV兴安直流1858#-1859#跨越110kV玉翠甲线100#-101#等32处交叉跨越（见附件）；7、±500kV兴安直流2032#-2079+1#为绝缘架空地线，工作人员与绝缘架空地线之间的距离应不小于0.4m。若需在绝缘架空地线上作业，应先将地线可靠接地。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('9a1855742414444db2a287d5fa6fe8b1', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 21:00:48', '0101', '拔出极一直流保护系统3（=21R03+R1）屏内SIMADYN D保护MM4板卡的X3端子。', NULL, '在主控楼三楼极一及公用电子设备室（303室）：极一直流保护系统3（=21R03+R1）前后悬挂“在此工作”标示牌，并在相邻运行设备粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, '工作过程中需多次分合极一直流保护系统3（=21R03+R1）内-F3空开。', '01012010', '2022-01-25 21:00:48', NULL, '72', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cf8436c123bc428db2c33f4ddb539d95', NULL, '无。', NULL, NULL, '不需要停电。');
