INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('a2fec745fb9347b09e64dbae2a1e041c', NULL, NULL, '50221、50232、05205、00202、00202A。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 01:03:48', '0107', '1、分别断开50221、50232隔离开关电机电源QF1，05205隔离开关操作电源F184-1、00202隔离开关操作电源F184-3、00202A隔离开关操作电源F184-1； 2、#2继电器室：分别断开P30 500kV 5022断路器保护屏（=10B02.B+R1）内第一路操作箱电源4K1、第二路操作箱电源4K2，P31 500kV 5023断路器保护屏（=10B02.C+R1）内5023操作箱电源1空开4K1、5023操作箱电源2空开4K2； 3、分别断开500kV极2换流变进线电压互感器端子箱内F711（至极2直流保护屏1电压回路）、F712（至极2换流变压器保护屏1电压回路）、F713（至极2控制系统屏1 电压回路）、F714（至500kV 5023开关保护屏1电压回路）、F721（至极2直流保护屏2电压回路）、F722（至极2换流变压器保护屏2电压回路）、 F723（至极2控制系统屏2电压回路）、F724（至 500kV第二串就地控制接口屏电压回路）、F731（至极2直流保护屏3电压回路）、F732（至极2故障录波屏电压回路）、F733（至交流谐波监视屏电压回路）、F734（极2换流变电度表屏电压回路）、F735（极2套管在线监测电压回路）空开。', NULL, '1、分别在50221、50232隔离开关电机电源QF1，05205隔离开关操作电源F184-1、00202隔离开关操作电源F184-3、00202A隔离开关操作电源F184-1上悬挂“禁止合闸，有人工作！”标示牌；2、#2继电器室：分别在P30 500kV 5022断路器保护屏（=10B02.B+R1）内第一路操作箱电源4K1、第二路操作箱电源4K2，P31 500kV 5023断路器保护屏（=10B02.C+R1）内5023操作箱电源1空开4K1、5023操作箱电源2空开4K2上悬挂“禁止合闸，有人工作！”标示牌；3、分别在500kV极2换流变进线电压互感器端子箱内F711（至极2直流保护屏1电压回路）、F712（至极2换流变压器保护屏1电压回路）、F713（至极2控制系统屏1 电压回路）、F714（至500kV 5023开关保护屏1电压回路）、F721（至极2直流保护屏2电压回路）、F722（至极2换流变压器保护屏2电压回路）、F723（至极2控制系统屏2电压回路）、F724（至 500kV第二串就地控制接口屏电压回路）、F731（至极2直流保护屏3电压回路）、F732（至极2故障录波屏电压回路）、F733（至交流谐波监视屏电压回路）、F734（极2换流变电度表屏电压回路）、F735（极2套管在线监测电压回路）空开上悬挂“禁止合闸，有人工作！”标示牌； 4、分别在5023、5022断路器，50222、50231隔离开关，502227、502317、502367接地刀闸四周设置围栏，并在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏出入口悬挂“在此工作！”和“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '补充 安全交代：魏六刚、刘仕权 2021.12.28 14:50', '01070103', '2022-01-22 01:03:48', NULL, '45', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '82a54dc630724eeeb5f5002358560e4d', NULL, '无。', '502327、050217、050227。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('a303f314a12c42db8a8071dcaf31f1d3', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-08 10:51:31', '0108', '无。', NULL, '1、在220kV保护室19P 500kV保护信息采集系统屏上悬挂“在此工作！”标示牌；\\r\\n2、在220kV保护室与19P 500kV保护信息采集系统屏相邻的屏柜前后悬挂“运行设备！”标示牌并粘贴“运行设备！”红色胶带；\\r\\n3、在主控室保信子站工作站上悬挂“在此工作！”标示牌；\\r\\n4、在主控室与保信子站工作站相邻的工作站前后悬挂“运行设备！”标示牌并粘贴“运行设备！”红色胶带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01080800', '2022-01-08 10:51:31', NULL, '32', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ea323a0dcfdf4cb884ef4f535f0379b5', NULL, '无。', NULL, NULL, '不需要停电。');
