INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('a966ca0a3aeb4b77ae58cb8c1c4caf6d', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 12:13:21', '0101', '无。', NULL, '在主控楼309通信设备室：A01 通信直流配电柜1、A05 通信直流配电柜2、C03 ODF配线柜3（站内互联）、C09 综合数据网设备柜前后悬挂“在此工作”标示牌，并在相邻屏柜粘贴“运行设备”警示带；在综合楼119通信室： 1P 局域网设备柜、2P 综合配线柜1、3P 综合配线柜2、4P 综合配线柜3前后悬挂“在此工作”标示牌，并在相邻屏柜粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-003]', 'EXtClmnt', '2022-01-20 12:13:21', NULL, '53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '36c1643abca94aafae9c7e918e6505aa', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('a9945e167a1944b7a30e4be2bc5c346d', NULL, NULL, '1、500kV徐闻开关站：50031、5001DK1、5001DK2；\\r\\n2、500kV福山变电站：50512、50521、5051DK1、5051DK2。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 10:53:30', '0101', '1、500kV福山变电站：退出500kV 福徐甲线#2M侧50512刀闸、500kV第五串联络#1M侧50521刀闸、500kV福徐甲线#1高抗5051DK1刀闸、500kV福徐甲线#2高抗5051DK2刀闸控制电源开关QF2、电机电源开关QF1；\\t\\r\\n2、500kV徐闻开关站：退出500kV福徐甲线线路50031刀闸、500kV福徐甲线#1高抗5001DK1刀闸、500kV福徐甲线#2高抗5001DK2刀闸控制电源开关QF2、电机电源开关QF1。', NULL, '1、500kV福山变电站：\\r\\n（1）在500kV福山变电站：500kV 福徐甲线#2M侧50512刀闸、500kV第五串联络#1M侧50521刀闸、500kV福徐甲线#1高抗5051DK1刀闸、500kV福徐甲线#2高抗5051DK2刀闸操作机构箱把手上悬挂“禁止合闸，线路有人工作！”标示牌，在操作员工作站的显示屏上的相应操作处，设置“禁止合闸，线路有人工作！”标示牌；\\r\\n（2）在500kV福山变电站：500kV 福徐甲线#2M侧50512刀闸、500kV第五串联络#1M侧50521刀闸、500kV福徐甲线#1高抗5051DK1刀闸、500kV福徐甲线#2高抗5051DK2刀闸控制电源开关QF2、电机电源开关QF1处悬挂“禁止合闸，线路有人工作！”标示牌；\\r\\n2、500kV徐闻开关站：\\r\\n(1)在500kV福徐甲线线路50031刀闸、500kV福徐甲线#1高抗5001DK1刀闸、500kV福徐甲线#2高抗5001DK2刀闸操作机构箱把手上悬挂“禁止合闸，线路有人工作！”标示牌，在操作员工作站的显示屏上的相应操作处，设置“禁止合闸，线路有人工作！”标示牌；\\r\\n(2)在500kV福徐甲线线路50031刀闸、500kV福徐甲线#1高抗5001DK1刀闸、500kV福徐甲线#2高抗5001DK2刀闸控制电源开关QF2、电机电源开关QF1处悬挂“禁止合闸，线路有人工作！”标示牌。\\r\\n3、500kV南岭终端站：（1）在500kV福徐甲线龙门架爬梯处设置“从此上下”标识牌，在500kV福徐乙线龙门架爬梯处设置“禁止攀登，高压危险!”标识牌，在500kV福徐甲线龙门架悬垂绝缘子、500kV福徐甲线避雷器、500kV福徐甲线A、B、C三相终端头处悬挂“在此工作！”标示牌；在500kV福徐甲乙线龙门架间悬挂“止步，高压危险!”标示牌。\\r\\n（2）在500kV福徐甲线龙门架龙门架下方、500kV福徐甲线避雷器、500kV福徐甲线A、B、C三相终端头周围分别装设安全遮栏，并向内悬挂“止步，高压危险！”标示牌，在安全遮栏入口处悬挂“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-001]', 'EXtClm04', '2022-01-12 10:53:30', NULL, '23', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '085d1f5cfab9485b9cd7fa2a611c85ac', NULL, '无。', '1、500kV徐闻开关站：5003617；\\r\\n2、500kV福山变电站：505167；\\r\\n3、500kV南岭终端站：在500kV福徐甲线避雷器A、B、C三相上端引线处分别装设接500kV地线一组。', NULL, NULL);
