INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa2bbbd989c743158891db88dd75652a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 13:18:49', '0102', '无。', NULL, '1、分别在通信机房B04 综合数据网安防设备屏、B10 综合数据网设备屏上悬挂“在此工作！”标示牌； \\r\\n2、分别在通信机房B03 录音系统设备屏、B05 马可尼C-MUX2屏、B09 南方安稳装置通信接口屏、B11 贵州省网光传输设备屏前后悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13984102084。', '01020704', '2022-01-19 13:18:49', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '72233cc80e3946e78a1d39045ef7a412', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa75b943126b413e8665432150a9e24f', NULL, '1、作业人员必须具备相应的作业资质，并经相关管理机构考核合格，取得法定特种作业人员证书，且无妨碍工作的病症。 2、作业前与工作许可人联系，得到许可后方可开始作业。 3、现场作业前工作负责人要召开班前会，交代工作任务、地点、安全措施及注意事项，工作结束后召开班后会进行总结。 4、现场所有工作人员必须正确佩戴安全帽，攀登杆塔及在杆塔上作业时必须按要求使用双保险安全带，在上、下塔、转位、作业过程中交替使用，并且尽量缩短使用安全带，任何时刻均不得失去安全带的保护。安全带应高挂低用，系在牢固的构件上，防止被尖锐物割伤，且随时检查安全带是否拴牢。5、登塔作业人员作业过程中与带电导线保持不小于10.1米的安全距离 。6、监护人全过程做好监护，及时纠正不安全行为。7、工作结束后，认真清理现场，清点人数，确认塔上无遗留物，负责人组织列队召开班后会，总结现场作业开展情况和经验，向工作许可人汇报工作结束。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-13 12:04:31', '0110', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01100552', '2022-01-13 12:04:31', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f5cec8a1ede04bbb9088d71da8d4f53d', NULL, '无。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa7f5a8619d64ba3b2e802c9ffe66bb0', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '±800kV新松换流站侧：极1中性母线0010开关、极2中性母线0020开关、极1母线08105刀闸、极1转换母线08121刀闸、极2母线08205刀闸、极2转换母线08122刀闸；±800kV东方换流站侧：极1中性母线0010开关、极2中性母线0020开关、极1母线08105刀闸、极1转换母线08121刀闸、极2母线08205刀闸、极2转换母线08122刀闸。 ', NULL, NULL, '0.000000000000000', '2022-01-25 11:56:37', '0110', NULL, NULL, '1、在±800kV新松换流站侧：极1中性母线0010开关、极2中性母线0020开关、极1母线08105刀闸、极1转换母线08121刀闸、极2母线08205刀闸、极2转换母线08122刀闸操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。 2、在±800kV东方换流站侧：极1中性母线0010开关、极2中性母线0020开关、极1母线08105刀闸、极1转换母线08121刀闸、极2母线08205刀闸、极2转换母线08122刀闸操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。 ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01100552', '2022-01-25 11:56:37', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, '±800kV新松换流站侧：极1线路081217地刀、极2线路081227地刀；±800kV东方换流站侧：极1线路081217地刀、极2线路081227地刀。', NULL, 'bbd2cbb01ca94de7af568c8cad134f91', NULL, '1、作业人员必须具备相应的作业资质，并经相关管理机构考核合格，取得法定特种作业资质证书，且无妨碍工作的病症。 2、作业前与许可人联系，得到许可后方可开始作业。 3、现场作业前工作负责人要召开班前会，交代工作任务、地点、安全措施及注意事项。 4、现场所有工作人员必须正确佩戴安全帽，攀登杆塔及在杆塔上作业时必须按要求使用双保险安全带，在上下塔、转位、作业过程中交替使用，任何时刻均不得失去安全带或长腰绳的保护，安全带应高挂低用，系在牢固的构件上，防止被尖锐物割伤；且随时检查安全带是否拴牢。 5、监护人全过程做好监护，及时纠正不安全行为。 6、作结束后，认真清理现场，清点人数，确认塔上无遗留物。 ', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa8e1ddfa56947da87d4680732361108', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 18:11:21', '0106', '无。', NULL, '1、在主控楼计算机室保信子站后台管理机放置“在此工作”标示牌。\\r\\n2、在主变及35kV保护小室28P 保护信息管理子站A屏、29P 保护信息管理子站B屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。\\r\\n 3、在220kV保护小室20P 220kV百松Ⅱ线主一保护屏、21P 220kV百松Ⅱ线主二保护屏、23P 故障信息处理屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '补充安全交代：梁兴海 2022.01.10 09:04', '01060406', '2022-01-10 18:11:21', NULL, '39', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a43bd57277524f098136bb3e7c6eea00', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa92379b934143d08fbd008412362bb9', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 14:45:45', '0101', '无。', NULL, '在±800kV直流场区域、±800kV双极高低端换流变压器区域、500kV交流滤波器场区域、500kV交流场区域、#2主变区域、#3主变区域、220kV GIS交流室、35kV区域、110kV站用变区域、10kV站用变区域、400V低压配电室、消防系统设备区域以及空调系统设备区域分别悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012005', '2022-01-30 14:45:45', NULL, '27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ad187d455bac4a0b8af0274985b01894', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('aa94a4413200469495de999f9ff096bd', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 21:45:00', '0110', '无。', NULL, '1、在极1高端阀冷设备间E1.PIS02氮气瓶上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01100310', '2022-01-18 21:45:00', NULL, '33', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '71072d54d5184e2cabfe9bd986af34f8', NULL, '1、工作结束后，将阀门恢复至初始位置，检查更换后压力正常。', NULL, NULL, '不需要停电。');
