INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ad82e466fbaf499bb2a50fdf63265cdf', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 15:49:26', '0101', '无', NULL, '在主控楼极1低端阀厅控制保护设备室204：=22R00+R1 极2直流系统保护屏1、=22R00+R2 极2直流系统保护屏2、主控楼站及双极控制保护设备室203：=20XX20+X1 通信屏一、=20XX20+X2 通信屏二、站公用辅助设备间201：=20Q10+Q00 电能采集屏前后悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带；在主控楼302室：=20XJ01-P1控制保护工程师工作站、主控室：电能计量工作站处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电', NULL, '0.000000000000000', NULL, NULL, '工作中需多次分合=20XX20+X2 通信屏二内U37路由器电源开关。', '01012001', '2022-01-18 15:49:26', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '35d0226843b748518cc26eab6254e2f9', NULL, '无', NULL, NULL, '不需要停电');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adaca1f5c7cd4b349ab60ddac1218fa3', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 12:33:23', '0104', '1、站公用控制保护室1：31P 站公用直流充电机屏2：断开21ZK #2充电机输出转换开关。', NULL, '1、在站公用控制保护室1：31P 站公用直流充电机屏2前后悬挂“在此工作”标示牌，并在相邻运行屏柜设置“运行设备”标识。2、在站公用控制保护室1：31P 站公用直流充电机屏2：21ZK #2充电机输出转换开关上悬挂“禁止合闸，有人工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040802', '2022-01-27 12:33:23', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '3753ef6cbae84882bfaa9f23579ecd01', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adaed498c62549bda21cda37c181f66b', NULL, NULL, '50311、50322、将11DL断路器摇至试验位置。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 23:51:06', '0107', '1、分别断开500kV #1B站用变500kV侧进线CVT端子箱内：至站用变保护屏1 =10T01+RJ1电源空开F721、至500kV断路器保护=10B03.A+R1电源空开F722、至站用变保护屏2 =10T01+RJ2电源空开F731、至交流就地接口屏电源空开F732；2、分别断开50311、50322隔离开关电机电源QF1。', NULL, '1、分别在50311、50322隔离开关电机电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；2、在11DL断路器上悬挂“禁止合闸，有人工作！”标示牌；3、分别在500kV #1B站用变500kV侧进线CVT端子箱内至站用变保护屏1 =10T01+RJ1电源空开F721、至500kV断路器保护=10B03.A+R1电源空开F722、至站用变保护屏2 =10T01+RJ2电源空开F731、至交流就地接口屏电源空开F732上悬挂“禁止合闸，有人工作！”标示牌；4、在500kV #1B站用变四周设置围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏出入口处悬挂“从此进出！”和“在此工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '陈建中 2022.01.08 09:35    任永强 2022.01.09 09:25', '01070104', '2022-01-21 23:51:06', NULL, '40', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '5fc143518ec2413c8e72ffaf57d2331d', NULL, '无', '503117、503227、117。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adbbd878188b4d98b5fbb50fde560495', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 15:33:46', '0109', '无。', NULL, '在主控楼202室通信机房A02调度程控交换机屏、A05直流配电屏二、A06直流配电屏一前后分别悬挂“在此工作！”标示牌，并在相邻屏柜围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交待：已完成调度程控交换机定检，定检后设备工作正常，现场已恢复至作业前状态。', '01090605', '2022-01-10 15:33:46', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'c3708977947544e9af57e5c065c2e262', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adc944d99b4b45c5ba67294ef43903c9', NULL, NULL, '50111、50122、50221、50232、05105、00102、00102A、05205、00202、00202A。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 10:38:01', '0107', '1、分别断开50111、50122、50221、50232刀闸的电机电源空开QF1；2、分别断开11B00+V1 直流场极1就地汇控箱1内05105刀闸电机电源F184-2、10B10+V1 直流场中性母线就地汇控箱1内00102刀闸电机电源F184-3、10B10+V1 直流场中性母线就地汇控箱1内00102A刀闸电机电源F184-4、10B10+V2直流场中性母线就地汇控箱2内00202刀闸操作电机电源开关F184-3、10B10+V2 直流场中性母线就地汇控箱2内00202A刀闸操作电机电源开关F184-1、12B00+V1直流场极2就地汇控箱1内05205刀闸操作电机电源开关F184-1；3、极1阀冷却设备间101：分别断开P1极1阀冷系统电源屏1内极1阀冷交流电源进线总电源QF111、QF112；4、极2阀冷却设备间102：分别断开P3极2阀冷系统电源屏1内极2阀冷交流电源进线总电源QF111、QF112。', NULL, '1、分别在50111、50122、50221、50232刀闸操作电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；2、分别在11B00+V1 直流场极1就地汇控箱1内05105刀闸电机电源F184-2、10B10+V1 直流场中性母线就地汇控箱1内00102刀闸电机电源F184-3、10B10+V1 直流场中性母线就地汇控箱1内00102A刀闸电机电源F184-4、10B10+V2直流场中性母线就地汇控箱2内00202刀闸操作电机电源开关F184-3、10B10+V2 直流场中性母线就地汇控箱2内00202A刀闸操作电机电源开关F184-1、12B00+V1直流场极2就地汇控箱1内05205刀闸操作电机电源开关F184-1上悬挂“禁止合闸，有人工作！”标示牌；3、极1阀冷却设备间101：分别在P1极1阀冷系统电源屏1内极1阀冷交流电源进线总电源QF111、QF112上悬挂“禁止合闸，有人工作！”标示牌；4、极2阀冷却设备间102：分别在P3极2阀冷系统电源屏1内极2阀冷交流电源进线总电源QF111、QF112上悬挂“禁止合闸，有人工作！”标示牌；5、分别在极1、极2阀冷系统#1、#2、#3、#4冷却塔上悬挂“在此工作！”标示牌；6、分别在极1、极2阀冷系统喷淋水池观察口处悬挂“在此工作！”标示牌；7、在工业水池观察口处悬挂“在此工作！”标示牌；8、在新建水泵房门上悬挂“在此工作！”标示牌；9、分别在#1、#2、#3工业泵上悬挂“在此工作！”标示牌；10、分别在#1、#2、#3工业泵进出水管道上悬挂“在此工作！”标示牌；11、在工业水泵控制屏上悬挂“在此工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-016]\\r\\n补充安全交代：冷思勇2021-12-30 10:50；秦诗杨、吴成银2022-01-02 15:10', '0126', '2022-01-22 10:38:01', NULL, '70', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '7e8d6d1224164919aa9b90a697e311a4', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('add531a161154761a5ecba80075ecfe1', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-17 11:28:09', '0101', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-17 11:28:09', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '94f6103a64f14740a3a7deffe80dfa43', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ade5a29c09ce4a31b6e712c1b88e06cc', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '±500kV宝安换流站侧：05105隔离开关、05121隔离开关、 05205隔离开关、05122隔离开关。 \\r\\n±500kV兴仁换流站侧：05105隔离开关、05121隔离开关、 05205隔离开关、05122隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-11 16:16:33', '0101', NULL, NULL, '在±500kV宝安换流站侧：05105隔离开关、05121隔离开关、05205隔离开关、05122隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌； \\r\\n在±500kV兴仁换流站侧：05105隔离开关、05121隔离开关、05205隔离开关、05122隔离开关远方控制把手和现场操作机构箱上悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、工作票负责人：张光洪，电话：13640889480； \\r\\n2、运行单位现场负责人： 焦海龙，电话：13922773436；廖鹏，电话:19925840339\\r\\n3、广州换流站020-36359186、020-86398686-3131。[交底单号：2022-01-S0-001]', 'EXtClm04', '2022-01-11 16:16:33', NULL, '32', NULL, NULL, NULL, NULL, NULL, NULL, '±500kV宝安换流站侧：051217接地刀闸、 051227接地刀闸。\\r\\n±500kV兴仁换流站侧： 051217接地刀闸、 051227接地刀闸。', NULL, '0cbe4b65ae1d4a8e90a47234550e691a', NULL, '1、高空作业人员不得失去安全带的保护，工作现场应有专人监护； \\r\\n2、严禁上下抛掷物品；\\r\\n3、现场所有作业人员必须正确佩戴安全帽； \\r\\n4、线路作业应在良好的天气下进行，遇有雷雨、6级及以上大风、强对流等恶劣气象条件时，应停止工作； \\r\\n5、邻近或交叉跨越带电线路施工需满足安全作业距离：10kV不小于1米，35kV不小于2.5米，110kV不小于3米，220kV不小于4米，500kV不小于6米，±500kV不小于7.8米；\\r\\n6、±500kV兴安直流交叉跨越信息：±500kV兴安直流1906#-2076#跨越500kV贺罗I线365#-366#等21处交叉跨越（见附件）；\\r\\n7、±500kV兴安直流2032#-2079+1#为绝缘架空地线，工作人员与绝缘架空地线之间的距离应不小于0.4m。若需在绝缘架空地线上作业，应先将地线可靠接地。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adf1756a270e4513aaa6d5a7a0994233', NULL, NULL, '50521、50532、50536、5053DK1。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 21:31:23', '0104', '1、断开50521隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n2、断开50532隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n3、断开50536隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n4、断开5053DK1隔离开关控制电源空气开关QF2、电机电源空气开关QF1。\\r\\n5、断开500kV平来Ⅱ线线路CVT端子箱内：第一套主保护空气开关MCB1、第二套主保护空气开关MCB2、开口三角空气开关MCB3、计量A相空气开关MCB4、计量B相空气开关MCB5、计量C相空气开关MCB6。', NULL, '1、在50521、50532、50536、5053DK1隔离开关现场操作机构处悬挂“禁止合闸，有人工作”标示牌，并在监控界面对应位置作“禁止合闸，有人工作”标识；\\r\\n2、在500kV平来Ⅱ线线路CVT端子箱内：第一套主保护空气开关MCB1、第二套主保护空气开关MCB2、开口三角空气开关MCB3、计量A相空气开关MCB4、计量B相空气开关MCB5、计量C相空气开关MCB6上粘贴“禁止合闸，有人工作”标识；\\r\\n3、在工作区域装设安全围栏，围栏内的设备包括：500kV平来Ⅱ线线路CVT三相本体，围栏向内悬挂“止步，高压危险！”标示牌，围栏内面向围栏入口明显处悬挂“在此工作”标示牌，在围栏入口处悬挂“从此进出”标示牌。\\r\\n4、将50521、50532、50536、5053DK1隔离开关机构箱常规锁更换为“检修隔离”锁。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-004]', 'EXtCuSGl', '2022-01-22 21:31:23', NULL, '45', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'd623c3b026164d70acb9e809efa946c1', NULL, '无。', '1、5053617接地刀闸，共1把。 2、在500kV平来Ⅱ线线路CVT出线侧导线处装设1组500kV接地线，共1组。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('adfa24da151c45beb231f954de160d82', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 18:02:35', '0107', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-014]', '0126', '2022-01-10 18:02:35', NULL, '20', NULL, '分别在以下地点；1、主控楼一楼、二楼、三楼、电缆夹层的灭火器箱、消防栓处分别悬挂“在此工作！”指示牌； 2、主控楼一楼微型消防站处悬挂“在此工作！”指示牌； 3、综合楼一楼、二楼、三楼的灭火器箱、消防栓处分别悬挂“在此工作！”指示牌； 4、#1、#2、#3、#4继电器小室的灭火器箱处分别悬挂“在此工作！”指示牌； 5、#1消防小屋、#2消防小屋、#3消防小屋、#4消防小屋、#5消防小屋、#6消防小屋处分别悬挂“在此工作！”指示牌； 6、室外消防栓处分别悬挂“在此工作！”指示牌； 7、门卫室灭火器箱处分别悬挂“在此工作！”指示牌； 8、综合水泵房、新建水泵房的的灭火器箱处分别悬挂“在此工作！”指示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'b57e684a034d4ab4a04e9c8b1e092868', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ae062243c9c64bfca5e1300315cec3f8', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 12:00:25', '0101', '无。', NULL, '在500kV福徐乙线海底电缆油泵站PLC控制屏处悬挂“在此工作！”标示牌；。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '0101111203', '2022-01-26 12:00:25', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4586adfec8df4987abb9f255ac6ab24a', NULL, '工作负责人必须严格执行工作票制度,现场对安全措施、技术措施和作业任务及操作危险点和控制措施交底，按规定填写工作票。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ae20b4493d5f4386a6632ef84b8c3ea7', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 00:13:11', '0108', '无。', NULL, '1、在牛从甲直流极1控制保护室、牛从甲直流极2及公用控制保护室、牛从乙直流极1及公用控制保护室、牛从乙直流极2控制保护室、站公用控制保护室、牛从甲直流极1阀厅巡视走廊、牛从甲直流极2阀厅巡视走廊、牛从乙直流极1阀厅巡视走廊、牛从乙直流极2阀厅巡视走廊、牛从甲直流极2阀冷控制保护室、牛从乙直流极1阀冷系统控制保护室、牛从乙直流极2阀冷系统控制保护室、牛从乙直流场继电器室、牛从甲直流场继电器室、RH1继电器室、RH2继电器室、RH3继电器室处分别悬挂“在此工作！”标示牌；2、在牛从甲直流极1阀冷设备间大门上及#1冷却塔、#2冷却塔、#3冷却塔及缓冲水池处分别悬挂“在此工作！”标示牌；3、在牛从甲直流极2阀冷设备间大门上及#1冷却塔、#2冷却塔、#3冷却塔及缓冲水池处分别悬挂“在此工作！”标示牌；4、在牛从乙直流极1阀冷设备间大门上及#1冷却塔、#2冷却塔、#3冷却塔及缓冲水池处分别悬挂“在此工作！”标示牌；5、牛从乙直流极2阀冷设备间大门上及#1冷却塔、#2冷却塔、#3冷却塔、缓冲水池处分别悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01080806', '2022-01-30 00:13:11', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '59e15f973ceb4cb1a55a4c79e5c73d9f', NULL, '无。', NULL, NULL, '不需要停电。');
