INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('af13d907279b49d7ad56df897fce7151', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-17 18:21:01', '0103', '退出21保护小室29P 220kV #C1M/#C2M母线第一套母差保护屏#C1M/#C2M第一套母差保护RCS-915AS跳C2013 #1线圈1FLP1压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2024 #1线圈2FLP1压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2051 #1线圈TLP2压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2052 #1线圈TLP3压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2055 #1线圈TLP6压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2056 #1线圈TLP7压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2057 #1线圈TLP8压板、#C1M/#C2M第一套母差保护RCS-915AS跳C2012 #1线圈MLP1压板。', NULL, '1、在31保护小室4P #C1B主变第一套电气量保护屏（新增) 、5P #C1B主变第二套电气量保护屏（新增)、6P #C1B主变非电量保护屏（新增）前后分别悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带；\\r\\n2、在21保护小室29P 220kV #C1M/#C2M母线第一套母差保护屏前后悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-017]', 'EXtCuSGl', '2022-01-17 18:21:01', NULL, '32', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2490b4d4b0ca486cb7383cf9c997c32b', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('af1b32e00ebf4e74950a4bcc2f179282', NULL, NULL, '20112、20212、20312、20412、20512、20612、20712、20812。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-20 10:22:07', '0107', '1、分别断开20112、20212、20412、20612、20712、20812隔离开关电机电源空开QF1和控制电源空开QF2；2、分别断开20312、20512隔离开关机构箱内操作电源Q1；3分别断开220kV #1M母线电压互感器端子箱内至直流站控屏A、第四串测控屏A空开MCB1，至第四串测控屏A、第五串测控屏A空开MCB2，至直流站控屏B、第四串测控屏B、第五串测控屏B、2041断路器保护屏、2051断路器保护屏空开MCB4。', NULL, '1、分别在20112、20212、20412、20612、20712、20812隔离开关电机电源空开QF1和控制电源空开QF2上悬挂“禁止合闸，有人工作！”标示牌；2、分别在20312、20512隔离开关机构箱内操作电源Q1上悬挂“禁止合闸，有人工作！”标示牌；3、分别在监控系统20112、20212、20312、20412、20512、20612、20712、20812隔离开关上装设“禁止合闸，有人工作!”电子标示牌；4、分别在220kV #1M母线电压互感器端子箱内至直流站控屏A、第四串测控屏A空开MCB1，至第四串测控屏A、第五串测控屏A空开MCB2，至直流站控屏B、第四串测控屏B、第五串测控屏B、2041断路器保护屏、2051断路器保护屏空开MCB4上悬挂“禁止合闸，有人工作！”标示牌；5、分别在20111、20211、20311、20411、20511、20611、20711、20811隔离开关，201117、202117、203117、204117、205117、206117、207117、208117、2117、2127接地刀闸四周设置围栏，在围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏出入口处悬挂“在此工作！”和“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '01070103', '2022-01-20 10:22:07', NULL, '40', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'a22cb2a442b14989884ff1706e75d171', NULL, '无。', '1、201127、202127、203127、204127、205127、206127、207127、208127； 2、分别在220kV #1M母线避雷器A、B、C相上装设1组220kV单相接地线。', NULL, NULL);
