INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('b411a94b587d472c92c8040958531b8c', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 13:18:08', '0101', '无。', NULL, '在 ±500kV从西换流站：±500kV直流场、500kV换流变广场、500kV交流场、500kV交流滤波器场、500kV站用变区域、110kV站用变区域、500kV主变及35kV配电区域、机器人充电房及主控室机器人工作站、220kVGIS区域悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-001]', 'EXtClm44', '2022-01-24 13:18:08', NULL, '88', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '6b523662dcd7410a9ea5e5a3260fdc52', NULL, '无', NULL, NULL, '不需要停电。');
