INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('b8a45f8f16da4a8ea88de555ab4df14a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 11:49:48', '0103', '无。', NULL, '在204二楼通信机房B06 南网ASON设备光路子系统屏、B07 南网ASON设备屏、B17 网B烽火780B光端机屏、A03 天三ODF光配线屏、C14 南网网B烽火780B光设备（二）前后分别悬挂“在此工作！”标示牌，将工作屏柜内非工作设备的面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01031105', '2022-01-07 11:49:48', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1b52ee34ca8646de8c355ceabdddbc83', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('b8c1eb22f1f4410d88e2ee5ada839a00', NULL, NULL, '5711、5721、5731、5741、5811、5821、5831、5841。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 10:01:06', '0101', '1、断开5711刀闸控制电源空开F231和刀闸电机电源空开F183；\\r\\n2、断开5721刀闸控制电源空开F232和刀闸电机电源空开F183；\\r\\n3、断开5731刀闸控制电源空开F233和刀闸电机电源空开F183；\\r\\n4、断开5741刀闸控制电源空开F234和刀闸电机电源空开F183；\\r\\n5、断开5811刀闸控制电源空开F23和1刀闸电机电源空开F183；\\r\\n6、断开5821刀闸控制电源空开F232和刀闸电机电源空开F183；\\r\\n7、断开5831刀闸控制电源空开F233和刀闸电机电源空开F183；\\r\\n8、断开5841刀闸控制电源空开F234和刀闸电机电源空开F183。', NULL, '1、分别在5711、5721、5731、5741、5811、5821、5831、5841刀闸就地操作机构箱上悬挂“禁止合闸，有人工作”标示牌；\\r\\n2、分别在5711刀闸控制电源空开F231和刀闸电机电源空开F183；5721刀闸控制电源空开F232和刀闸电机电源空开F183；5731刀闸控制电源空开F233和刀闸电机电源空开F183；5741刀闸控制电源空开F234和刀闸电机电源空开F183；5811刀闸控制电源空开F23和1刀闸电机电源空开F183；5821刀闸控制电源空开F232和刀闸电机电源空开F183；5831刀闸控制电源空开F233和刀闸电机电源空开F183；5841刀闸控制电源空开F234和刀闸电机电源空开F183上悬挂“禁止合闸，有人工作”标示牌；\\r\\n3、分别在500kV第二大组交流滤波器区域：500kV 571交流滤波器组(=20BF21）、500kV 572交流滤波器组(=20BF22）、500kV 573交流滤波器组(=20BF23）、500kV 574交流滤波器组(=20BF24）围栏内；500kV第三大组交流滤波器区域：500kV500kV 581交流滤波器（=20BF31）、500kV 582交流滤波器（=20BF32）及500kV 583交流滤波器（=20BF33）、500kV 584交流滤波器（=20BF34）围栏内门上悬挂“在此工作”、“从此进出”标示牌；在500kV 571交流滤波器571开关间隔T1电流互感器；500kV 572交流滤波器572开关间隔T1电流互感器；500kV 573交流滤波器573开关间隔T1电流互感器；500kV 574交流滤波器573开关间隔T1电流互感器；500kV 582交流滤波器582开关间隔T1电流互感器；500kV 583交流滤波器583开关间隔T1电流互感器处四周装设围栏，围栏向内悬挂“止步，高压危险”标示牌，围栏设置入口并在入口处悬挂“从此进出”及“在此工作”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-061]', 'EXtClm04', '2022-01-18 10:01:06', NULL, '89', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '4fa4f6b682ca4e4aba47178f66e4a20d', NULL, '无。', '57117、57217、57317、57417、57127、57227、57327、57427、58117、58217、58317、58417、58127、58227、58327、58427。', NULL, NULL);
