INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('b9c25fa2c4d4470d91c61ea324b4c061', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 16:16:46', '0101', '无。', NULL, '分别在500kV #2 继保室：500kV 线路故障测距屏（=20X31+S1）；通信机房：500kV故障测距通信接口屏（=20X31+TX1）、C02 广东传输网DDF屏前后悬挂“在此工作”标示牌，并在相邻屏柜粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作过程中需多次重启500kV交流故障测距装置。', '01012010', '2022-01-28 16:16:46', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a6cc22c568634162a444cae500f4d285', NULL, '无。', NULL, NULL, '不需要停电。');
