INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ba93b19e07e24d878ca4d6b665014c8b', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 14:39:15', '0109', '无', NULL, '1、在主控楼一楼极2暖通设备室门口处悬挂“在此工作！”标示牌；2、在主控楼一楼极2高端阀组380V配电室门口处悬挂“在此工作！”标示牌；3、在主控楼一楼极2低端阀组380V配电室门口处悬挂“在此工作！”标示牌；4、在主控楼一楼极2高端阀组阀冷却设备间门口处悬挂“在此工作！”标示牌；5、在主控楼一楼极2低端阀组阀冷却设备间门口处悬挂“在此工作！”标示牌；6、在主控楼二楼站公用充电机室门口处悬挂“在此工作！”标示牌；7、在主控楼二楼极2充电机室门口处悬挂“在此工作！”标示牌；8、在主控楼二楼极2低端阀组及公用控制保护设备室门口处悬挂“在此工作！”标示牌；9、在主控楼二楼通信机房门口处悬挂“在此工作！”标示牌；10、在主控楼二楼站公用控制保护设备室门口处悬挂“在此工作！”标示牌；11、在主控楼二楼极2高端阀组控制保护设备室门口处悬挂“在此工作！”标示牌；12、在主控楼三楼主控室门口处悬挂“在此工作！”标示牌； 13、在主控楼电缆竖井和走线槽悬挂“在此工作！”标示牌；14、在主控楼一楼走道和过厅悬挂“在此工作！”标示牌；15、在主控楼二楼走道和过厅悬挂“在此工作！”标示牌；16、在站公用蓄电池室门口处悬挂“在此工作！”标示牌；17、在极2蓄电池室门口处悬挂“在此工作！”标示牌；18、在通信机房48V蓄电池室门口处悬挂“在此工作！”标示牌，19、在主控室室内机器人后台工作站悬挂“在此工作！”标识牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-007]\\r\\n陈进海、李双龙、杨红德、李籍寿', 'EXtClm44', '2022-01-15 14:39:15', NULL, '96', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '3e56ea48a352494695ca133166553ced', NULL, '无。', NULL, NULL, '不需要停电。');
