INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('c21d4e3fecfd466fb7a280fd297b2877', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-06 16:26:36', '0107', '无。', NULL, '1、站公用及二次设备室211：在49P保护及故障录波信息子站主机屏上悬挂“在此工作！”标示牌；\\r\\n2、站公用及二次设备室211：在49P保护及故障录波信息子站主机屏相邻屏前后悬挂“运行设备”标示牌；\\r\\n3、主控楼二楼通信机房221：在A01调度数据网接入设备屏上悬挂“在此工作！”标示牌；\\r\\n4、主控楼二楼通信机房221：在A01调度数据网接入设备屏相邻屏前后悬挂“运行设备”标示牌；\\r\\n5、#1继电器室：分别在11P #1继电器室交流线路故障测距屏、33P #1继电器室保护及故障录波信息子站采集屏上悬挂“在此工作！”标示牌；\\r\\n6、#1继电器室：分别在11P #1继电器室交流线路故障测距屏、33P #1继电器室保护及故障录波信息子站采集屏相邻屏前后悬挂“运行设备”标示牌；\\r\\n7、#3继电器室：分别在75P #3继电器室交流线路故障测距屏、76P #3继电器室保护及故障录波信息子站采集屏上悬挂“在此工作！”标示牌；\\r\\n8、#3继电器室：分别在75P #3继电器室交流线路故障测距屏、76P #3继电器室保护及故障录波信息子站采集屏相邻屏前后悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01070101', '2022-01-06 16:26:36', NULL, '25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '25a7a271f3e8459491486b1d35910268', NULL, '无。', NULL, NULL, '不需要停电。');
