INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ce8c43a2f92d479b9fe1883550d069aa', NULL, NULL, '1、5651；2、将10kV 12DL断路器操作到试验位置。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 22:22:38', '0107', '1、分别断开5651隔离开关电机电源QM1和操作电源空开QF1；\\r\\n2、#2继电器室：断开P28 35/10kV站用变压器保护屏内的直流电源空开4K。', NULL, '1、分别在5651隔离开关电机电源QM1和操作电源空开QF1上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n2、#2继电器室：在P28 35/10kV站用变压器保护屏内的直流电源空开4K上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、在10kV 12DL断路器操作把手上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、在329断路器四周设置安全围栏，并向内悬挂“止步，高压危险！”标示牌，在围栏出入口处悬挂“从此进出！”和“在此工作！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-026]\\r\\n补充安全交代：李典成、安正江、刘科情、彭衍、王晨、陈亮，2022-01-01 08:40。', 'EXtCIf40', '2022-01-21 22:22:38', NULL, '46', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '5ddccf71c87c456dbc5683ec9ff3743f', NULL, '无。', '32927、32967。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ce979e3aa53845719705b85c260d4f0a', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 12:11:07', '0108', '无。', NULL, '在51保护室、52保护室、53保护室、主变及35kV保护室、融冰保护室、220kV保护室门上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01080800', '2022-01-28 12:11:07', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'e31a770529644ce68efdfa3fd9f9553a', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('ce9e987ef7624ac2ad57bffb4eaa34ad', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-09 16:59:19', '0109', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '检修交代：已完成通信机房环境定检，内容为检查机房环境，地面清扫、屏柜清灰，查看机房环境温湿度是否正常。经现场检查，机房环境良好，温湿度适中。', '01090605', '2022-01-09 16:59:19', NULL, '12', NULL, '1、分别主控楼202室通信机房、208通信蓄电池室1、209通信蓄电池室2门口处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, 'fc21c6847fa64f229c1066e22756a0ae', NULL, NULL, NULL, NULL, NULL);
