INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D522DE039870C7BBE05302C0790A81B7', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 19:37:13', '0106', '无。', NULL, '1、在500kV武平变电站保护及通信室门口放置“在此工作”标示牌； \\r\\n2、在500kV武平变电站主控室门口放置“在此工作”标示牌； \\r\\n3、在500kV武平变电站#1蓄电池室：48V #1蓄电池组构架上悬挂“在此工作”标示牌，并在110V #1蓄电池组四周围红色“运行设备”警示带； \\r\\n4、在500kV武平变电站#2蓄电池室：48V #2蓄电池组构架上悬挂“在此工作”标示牌，并在110V #2蓄电池组四周围红色“运行设备”警示带； \\r\\n5、在500kV武平变电站500kV设备区、220kV设备区入口处放置“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'd25ebf1f4c8f4d86a9746964bdb50e33', '2022-01-10 19:37:13', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ed635ce550aa4d5c9ee24d614112fffb', NULL, '无。', NULL, NULL, '不需要停电。');
