INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D52656AA3A5A7CB5E05301C0790A68CE', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 23:48:19', '0104', '1、退出9P 220kV#1融冰及SVC装置控制B屏内以下连接片：21LP1（#5换流变20.5kV侧0251断路器保护分闸）、21LP2（#6换流变20.5kV侧0261断路器保护分闸）。', NULL, '1、在31保护小室：9P 220kV #1融冰及SVC装置控制B屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；\\r\\n2、在主控室：220kV#1融冰及SVC装置监控机一、220kV#1融冰及SVC装置监控机二放置“在此工作”标示牌。 ', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '9c38a29a9def4f22bcee75543e3a9c0c', '2022-01-11 23:48:19', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '77239e0c5e744f588e0e7e7c3eae5af5', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D526E19E7558987CE05301C0790A8687', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 18:43:31', '0110', '无。', NULL, '在系统分析室工程师工作站悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '7b44d7f1086747b4b04612edcd8c211c', '2022-01-11 18:43:31', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1ad9e2b7fe84467d8ababae7aab061ba', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D528EB2AC0F37CF2E05301C0790A24D4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-10 22:10:27', '0104', '1、退出7P 220kV#1融冰及SVC装置控制A屏内以下连接片：21LP1（#5换流变20.5kV侧0251断路器保护分闸）、21LP2（#6换流变20.5kV侧0261断路器保护分闸）。\\r\\n', NULL, '1、在31保护小室：7P 220kV #1融冰及SVC装置控制A屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；\\r\\n2、在主控室：220kV#1融冰及SVC装置监控机一、220kV#1融冰及SVC装置监控机二放置“在此工作”标示牌。 ', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'ce80b597c6344e4bbf9a78af71e2b3aa', '2022-01-10 22:10:27', NULL, '36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '9c38a29a9def4f22bcee75543e3a9c0c', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D529B2FDBEFB9905E05301C0790ACAA7', NULL, ' 本工作不需退出±800kV柳龙段直流线路、±800kV新东直流线路再启动装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-11 16:11:14', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '工作负责人：蓝日吉13640789891\\r\\n工作许可人：梁伟昕13710080709', '358d4d9978264d0aa7e7031acdd55595', '2022-01-11 16:11:14', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a320f1ba42df45978189124a2dd15d45', NULL, '1、登塔人员应穿全套合格的静电防护服，且各部分连接可靠；2、工作人员、工具和材料与带电体之间的安全距离不得小于10.1m；3、工作人员在高空作业过程中不得失去安全带的保护，现场所有工作人员必须戴安全帽； 4、作业应在良好天气下进行，遇雷、雨、雾、5级及以上大风时，不得进行作业。5、汛期期间，注意行车和人行安全、做好人员防暑、防小动物伤害及疫情期间个人防护工作。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D529B2FDBEFF9905E05301C0790ACAA7', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 22:06:17', '0104', '无。', NULL, '在主控楼交直流室：1P油色谱在线监测综合处理单元屏前后悬挂“在此工作！”标示牌，并在相邻屏柜设置“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '15a1d9b03c1141b3910fe23abdbfa29e', '2022-01-14 22:06:17', NULL, '31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'dffbf2e2c6f9435db5715a452b9f9073', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D529B2FDBF049905E05301C0790ACAA7', NULL, '本次工作无需退出线路重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-13 11:05:07', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '运行单位负责人：谢守辉电话：13825195019；施工单位现场负责人陈继申 电话15014644391。[交底单号：2022-01-S0-013]', '7f65a68b058c4b618af1d8cfaf6e6845', '2022-01-13 11:05:07', NULL, '43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '902cb674c9c14473a60579625f762c2d', NULL, '1、线路作业应在良好的天气下进行，遇有恶劣气象条件时（工作过程中如遇雷电（听见雷声、看见闪电）、雪、雹、雨、雾等（湿度大于80%）、风力大于5级或其他威胁人员及设备安全的情况时），应停止工作。 2、施工人员必须得到工作负责人的通知后，方可组织开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路。 3、登塔前必须检查导电鞋和全套静电感应防护服本体及连接是否完好，确保身体各部位均得到保护后方可登塔工作。 4、所有作业塔位工作人员及工器具使用必须与带电体保持大于500kV交流线路5米的安全距离， 在地线支架上维护设备时人员与地线的距离必须大于0.4米。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D529B2FDBF3F9905E05301C0790ACAA7', NULL, ' 本工作不需退出±800kV柳龙段直流线路线路再启动装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 15:06:03', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作许可人：梁伟昕13710080709     工作负责人：冯宇18122358270', 'ad0c81165e9648889a18704b59862746', '2022-01-18 15:06:03', NULL, '30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'e11054e4e48a4218a2d1bea947b98eab', NULL, '1、登塔人员应穿全套合格的屏蔽防护服，且各部分连接可靠；2、工作人员、工具和材料与带电体之间的安全距离不得小于10.1m；3、工作人员在高空作业过程中不得失去安全带的保护，现场所有工作人员必须戴安全帽； 4、作业应在良好天气下进行，遇雷、雨、雾、5级及以上大风时，不得进行作业。5、注意行车和人行安全、做好人员三防措施、防小动物伤害及疫情期间个人防护工作。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530B4778BEC990BE05301C0790A1E7B', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 02:48:23', '0106', '退出220kV保护小室21P 220kV百松Ⅱ线主二保护屏内以下压板：1LP1（跳S2061开关A相出口Ⅱ)、1LP2（跳S2061开关B相出口Ⅱ)、1LP3（跳S2061开关C相出口Ⅱ)、1LP4（重合闸出口Ⅱ）、1LP5（三相不一致跳S2061开关三相出口Ⅱ）、1LP7（闭锁主一保护重合闸）、1LP10（跳A启动220kV第二套母线保护失灵）、1LP11（跳B启动220kV第二套母线保护失灵）、1LP12（跳C启动220kV第二套母线保护失灵）、1LP19（纵联差动保护）、1LP20（光纤通道一）、1LP21（光纤通道二）、1LP22（距离保护）、1LP23（零序过流保护）、1LP26（远跳开入）。', NULL, '在220kV保护小室21P 220kV百松Ⅱ线主二保护屏正面悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '05932bed77a740f0928ab02088abf895', '2022-01-11 02:48:23', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2c505f74b2594bde9a5426e80f5a5f14', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530B4778BF8990BE05301C0790A1E7B', NULL, '本次工作无需退出±500kV天广直流线路再启动功能。\\r\\n', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-13 09:11:12', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '运行单位现场负责人：赵付亮电话：13539890007 ；施工单位现场负责人：陈继申电话：15014644391。[交底单号：2022-01-S0-010][交底单号：2022-01-S0-010]', '2c216e6de18346319325332e447c36db', '2022-01-13 09:11:12', NULL, '32', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a81e81d7a29042d588033b9c4aa58664', NULL, '1、线路作业应在良好的天气下进行，如遇雷、雪、雹、雨、雾、湿度大于80%、风力大于5级或其他威胁人员及设备安全的情况时，应停止工作。 2、施工人员必须得到工作负责人的通知后，方可组织开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路。 3、登塔前必须检查导电鞋和全套静电防护服本体及连接是否完好，确保身体各部位均得到保护后方可登塔工作。 4、所有作业人员及工器具必须与±500kV直流线路带电体保持大于6.8米的安全距离， 在地线支架上安装设备时人员与地线的距离必须大于0.4米。5、现场作业人员正确佩戴安全帽。6、高空作业人员应使用全身式安全带，上下塔及塔上作业过程中，不得失去安全带保护，安全带应经外观检查合格及在试验有效期内。7、作业点下方不得有人逗留。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530B4778BFC990BE05301C0790A1E7B', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 15:12:49', '0101', '无。', NULL, '在#1继保室、#2继保室、#3继保室、#4继保室、#5继保室、主控楼一楼极一阀冷室、主控楼一楼极二阀冷室、主控楼一楼充电机2室107、主控楼二楼通信设备室201、综合楼一楼101、综合楼一楼102、综合楼一楼103、综合楼一楼104、综合楼一楼105、综合楼一楼106、综合楼一楼107、综合楼一楼113、综合楼一楼114、综合楼一楼115、综合楼一楼食堂、综合楼一楼健身房、综合楼二楼201、综合楼二楼202、综合楼二楼203、综合楼二楼204、综合楼二楼205、综合楼二楼206、综合楼二楼207、综合楼二楼208、综合楼二楼209、综合楼二楼210、综合楼二楼211、综合楼二楼212、综合楼二楼213、综合楼二楼214、综合楼二楼215、综合楼二楼216、综合楼三楼301、综合楼三楼302、综合楼三楼303、综合楼三楼304、综合楼三楼305、综合楼三楼306、综合楼三楼307、综合楼三楼308、巡视机器人小室、保安室、二号备品库二楼二次库房、二号备品库二楼二次库房分体式空调室内机、室外机处分别悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-003]', 'deee1fccceed4121a913021d2c02d18a', '2022-01-14 15:12:49', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f40ecfbe837c464093d6415937fdc102', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530C62D41E5CA14E05302C0790AA65D', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 15:29:29', '0102', '无。', NULL, '1、在通信室E10智能网关设备屏处悬挂“在此工作！”标示牌；2、在通信室E11智能摄像机设备屏处悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13424561670', '9de9b32ca1914932bff929464c680382', '2022-01-21 15:29:29', NULL, '49', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '640555d0526a46e68bf34089128f076b', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530CD2BE6C7CB21E05302C0790A005F', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 16:46:35', '0102', '无。', NULL, '分别在#0站用变、#1站用变、#3站用变本体取样阀处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：18786707830。', 'e668a1a8df714e00b1063f8e6e1bc445', '2022-01-11 16:46:35', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1b876b31332341a5acb701357ee744c9', NULL, '高压试验班对工作过程中产生的废油进行收集，并报送生技部进行报废处理。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D530F04EF8C4CA0AE05302C0790AE11E', NULL, NULL, '2091、2092、2093。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 21:45:01', '0102', '分别断开220kV 岩威线2091、2092、2093隔离开关机构箱电机电源K1空气开关。', NULL, '1、分别在220kV 岩威线2091、2092、2093隔离开关机构箱门锁处悬挂“禁止合闸，有人工作！”标示牌；2、在220kV 岩威线209断路器机构箱、端子箱，2091、2092、2093隔离开关机构箱，20929、20939、2099接地刀闸机构箱处悬挂“在此工作！”标示牌，并向内装设带有“止步，高压危险！”警示语的安全围栏，在围栏入口处悬挂“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：13595067355。', '784153a9911e42c7ad485c1e61000b62', '2022-01-12 21:45:01', NULL, '21', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'a808af8387a84161a0e1af49cf2d91e4', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5313D2F437498EBE05301C0790A21D5', NULL, NULL, '20015、20515、20525、20535、20545、20565、20575、20585、20252、20253、20255。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-10 09:27:25', '0104', '1、断开20015、20515、20525、20535、20545、20565、20575、20585、20252、20253、20255隔离开关控制电源QF2及电机电源QF1。 \\r\\n2、断开220kV旁母CVT端子箱内MCB 同期电压空气开关。\\r\\n3、退出133P 220kV专旁保护屏以下连接片：1LP10 纵联距离保护PSL602UC A相启动第一套母线保护失灵、1LP11 纵联距离保护PSL602UC B相启动第一套母线保护失灵、1LP12 纵联距离保护PSL602UC C相启动第一套母线保护失灵、4LP1 2025断路器操作箱PCX-ALF三跳启动第一套母线失灵。', NULL, '1、分别在20015、20515、20525、20535、20545、20565、20575、20585、20252、20253、20255隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，并在监控界面处作“禁止合闸，有人工作”标识。\\r\\n2、在220kV旁母CVT端子箱内：MCB 同期电压空气开关设置“禁止合闸，有人工作”标识。 \\r\\n3、在继电保护室：10P保护信息子站管理屏、133P 220kV专旁保护屏、54P 220kV故障录波器一、190P 220kV 母联及专旁测控屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识，在190P 220kV 母联及专旁测控屏屏内220kV 母联测控装置RCS-9705C前后粘贴“运行设备”标识。\\r\\n4、在主控室：#2操作员机处放置“在此工作”标示牌。\\r\\n5、在相关停电设备工作区域周围装设安全围栏，围栏内设备包括：220kV专旁2025断路器三相本体及其汇控箱、220kV专旁2025CT端子箱，220kV旁母CVT端子箱，并在围栏上向内悬挂“止步 高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌。\\r\\n6、将20015、20515、20525、20535、20545、20565、20575、20585、20252、20253隔离开关机构箱常规锁更换为“检修隔离”锁。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '陆武杰 2021.07.08 10:40', '27b495bb9c1448e690cfbdedd07a821f', '2022-01-10 09:27:25', NULL, '1', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '90b8102ad853483fa8175ff994a9d1f8', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5313D2F43E498EBE05301C0790A21D5', NULL, '本次工作不需退出500kV桂山乙线线路自动重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-13 18:26:58', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '6c34bde548ea4a4db8d02cb477f37b38', '2022-01-13 18:26:58', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '15029c0c192e4a3282ce6de29531c3de', NULL, '1、注意行车安全，注意山体滑坡；2、登塔人员应穿全套合格的屏蔽服或静电防护服，且各部分连接可靠； 3、塔上作业人员与绝缘架空地线的安全距离不得小于0.6m； 4、塔上作业人员、工具、材料与带电体安全距离不得小于5m； 5、塔上作业人员转移及作业过程中不得失去安全带的保护，现场所有工作人员须正确佩戴安全帽； 6、作业应在良好天气下进行，遇雷、雨、雾、5级及以上大风时，不得进行作业；7、在绝缘架空地线上作业，应用接地线或个人保安地线将其可靠接地，应在杆塔上接触或接近架空地线的作业开始前装设，作业结束且人体脱离架空地线后拆除，挂、拆时正确穿戴良好绝缘手套；8、如发现缺陷在无需更改安全措施的情况下，应由工作负责人征得工作票签发人和工作票许可人同意，在原工作票上增加工作项目，并签名确认；9、做好疫情期间个人防护工作、行车安全及应急药品准备。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5317ED74F1698FBE05301C0790A4791', NULL, NULL, '5611。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 22:15:36', '0107', '1、断开5611隔离开关电机电源QF1空开。', NULL, '1、在5611隔离开关电机电源QF1空开上悬挂“禁止合闸，有人工作！”标示牌；2、在561交流滤波器围栏上向内悬挂“止步，高压危险！”标示牌，并在围栏出入口处悬挂“在此工作！”和“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '根据《天生桥局检修方案编写及审批业务指导书（2021年第二版）》有关规定，一次设备发热处理（无需特种车辆）的作业不需要编制工作方案。', 'a2e89ef445ec41bfa591c1f426f3383b', '2022-01-21 22:15:36', NULL, '23', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '9a8aea3ccd8c4d08b91b8f1200d85958', NULL, '无。', '56127。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5317ED74F2698FBE05301C0790A4791', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 11:47:12', '0105', '无。', NULL, '在通信机房、通信蓄电池室门口悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '所有设备运行正常。', '017cdb066273457da91c68c52b42ce09', '2022-01-11 11:47:12', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '3fe21350ba0d4747a36bd3cc9f26efce', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5317ED750D098FBE05301C0790A4791', NULL, NULL, 'S20552、S20551。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-11 17:07:40', '0106', '1、断开S20552、S20551刀闸机构箱内电机电源QF1空气开关。\\r\\n2、断开220kV百老Ⅱ线CVT端子箱内二次侧空气开关：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关、有电闭锁S2055617 QF4空气开关。', NULL, '1、在220kV百老Ⅱ线S20552、S20551刀闸机构箱分别悬挂“禁止合闸，有人工作”标示牌，并在主控室计算机监控系统220kV百老Ⅱ线S20552、S20551刀闸操作处分别设置“禁止合闸，有人工作”标示。\\r\\n2、在S20552、S20551刀闸机构箱内电机电源QF1空气开关分别粘贴“禁止合闸，有人工作”警示标签。\\r\\n3、在220kV百老Ⅱ线CVT端子箱内二次侧空气开关：计量电压QF1空气开关、主一保护电压QF2空气开关、主二保护电压QF3空气开关、有电闭锁S2055617 QF4空气开关分别粘贴“禁止合闸，有人工作”警示标签。 \\r\\n4、在计算机室NS3000监控系统服务器1、NS3000监控系统服务器2、保信后台管理机、故障录波后台管理机、保信系统后台管理机分别放置“在此工作”标示牌，在18P 南宁监控中心远动装置屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。\\r\\n5、在220kV保护小室：6P 110V #1直流分屏，7P 110V #2直流分屏， 23P 故障信息处理屏，26P 220kV #1、#2、#3母线故障录波器二屏，27P  220kV #1、#2、#3母线故障录波器一屏，28P 220kV百老Ⅱ线主一保护屏，29P 220kV百老Ⅱ线主二保护屏，30P  220kV百文I线/百老Ⅱ线测控屏，38P 220kV第一套母线保护屏，39P 220kV第二套母线保护屏， 42P  220kV #S1M/#S2M电压并列及S2012开关操作屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。\\r\\n6、在通信室：H05 220kV线路保护光电接口屏，A04 220kV线路保护光电接口屏，G03 广西ODF、DDF综合配线柜，E04 500kV线路ODF配线柜， A05 -48V直流配电H屏，G01-48V直流配电G屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带，同时将H05 220kV线路保护光电接口屏内除220kV百老Ⅱ线主一保护通信接口装置、220kV百老Ⅱ线主二保护通信接口装置外的所有装置面板、背板用红色“运行设备”警示带密封。\\r\\n7、在通信室：A04 220kV线路保护光电接口屏内所有通信接口装置面板、背板用红色“运行设备”警示带密封。\\r\\n8、在220kV设备区：220kV百老Ⅱ线S2055开关汇控箱、220kV百老Ⅱ线CVT端子箱、220kV百老Ⅱ线S2055CT端子箱、220kV百老Ⅱ线S20552刀闸机构箱、220kV百老Ⅱ线S20551刀闸机构箱、220kV百老Ⅱ线综合端子箱分别悬挂“在此工作”标示牌，并在其四周装设向内标示“止步，高压危险”的安全遮栏，在安全遮栏的出入口处悬挂“从此进出”标示牌。\\r\\n9、在220kV设备区：220kV保护小室电缆夹层，220kV保护小室至220kV百老Ⅱ线间隔设备区电缆沟、220kV保护小室至主控楼之间电缆沟分别放置“在此工作”标示牌。\\r\\n10、在主变及35kV保护小室：28P保护信息管理子站A屏、29P保护信息管理子站B屏正面、背面分别悬挂“在此工作”标示牌，并在相邻屏柜围红色“运行设备”警示带。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '9ecd4a214a964b888ee194d44cb9fc3a', '2022-01-11 17:07:40', NULL, '1', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '7039598cb19947e4b7d14b3fbcc28bd9', NULL, '无。', 'S2055617。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D531FF4306657934E05302C0790AABA8', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 19:03:30', '0107', '分别断开#4配电箱内总开关电源空开、500kV交流场1（云南侧）、500kV交流场2（云南侧）、500kV交流场3（云南侧）电源空开。', NULL, '1、在#1继电器室：#1继电器室电缆夹层门把手上悬挂“在此工作！”标示牌；\\r\\n2、在#1继电器室#4配电箱上悬挂“在此工作！”标示牌；\\r\\n3、分别在#1继电器室#4配电箱内总开关电源空开，500kV交流场1（云南侧）、500kV交流场2（云南侧）、500kV交流场3（云南侧）电源空开上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、500kV云南侧交流场：在500kV天西甲线间隔、500kV天西乙线间隔、500kV西罗丙线间隔处悬挂“在此工作！”标示牌；在500kV天西甲线间隔、500kV天西乙线间隔新安装灯杆到#1继电器室#4配电箱所对应的电缆沟处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-008]', 'f8d5b12d7d7845bbad6cda21201f0f00', '2022-01-27 19:03:30', NULL, '63', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '8dabb234c5394c019209d3283520e1fb', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D532203B09DBCA42E05302C0790A7284', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 13:07:01', '0108', '退出220kV保护室23P 220kV罗关II回线主二保护屏主二保护PSL603UZC跳247 A相#2线圈 1LP1压板、主二保护PSL603UZC跳247 B相#2线圈 1LP2压板、主二保护PSL603UZC跳247 C相#2线圈 1LP3压板、主二保护PSL603UZC永跳247出口 1LP5压板、主二保护PSL603UZC重合闸出口合247 1LP6压板、主二保护PSL603UZC通道一差动保护 1LP13压板、主二保护PSL603UZC距离保护 1LP16压板、主二保护PSL603UZC零序保护 1LP17压板、主二保护PSL603UZC闭锁主一保护PSL603GCM重合闸 1LP20压板、主二保护PSL603UZC启动远跳 1LP21压板、A相跳闸启动220kV第二套母差失灵 1LP25压板、B相跳闸启动220kV第二套母差失灵 1LP26压板、C相跳闸启动220kV第二套母差失灵 1LP27压板。', NULL, '1、在220kV保护室23P 220kV罗关II回线主二保护屏前后悬挂“在此工作！”标示牌；\\r\\n2、在220kV保护室23P 220kV罗关II回线主二保护屏相邻屏柜前后悬挂“运行设备！”标示牌，并粘贴红色“运行设备！”胶带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '620df9421fd0493a9b540b58365ae5a6', '2022-01-11 13:07:01', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'c0edb3c5a16340e78f0d4bfd12e8786f', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D532203B0A20CA42E05302C0790A7284', NULL, NULL, '22592、22591、22596。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 21:45:16', '0101', '1、退出24P 220kV福泉Ⅱ线线路保护A屏2259第一组控制电源开关4K1、第二组控制电源开关4K2；\\r\\n2、退出220kV福泉Ⅱ线2259开关电机储能电源空气开关F1；\\r\\n3、退出220kV福泉Ⅱ线开关#2M侧22592刀闸、220kV福泉Ⅱ线开关#1M侧22591刀闸、220kV福泉Ⅱ线开关线路侧22596刀闸电机电源空气开关QF1、控制电源空气开关QF2。\\r\\n4、断开220kV福泉Ⅱ线CVT端子箱内1MCB-a计量回路交流电压A相空开、1MCB-b计量回路交流电压B相空开、1MCB-c计量回路交流电压C相空开、3MCB第一套保护回路交流电压空开、2MCB第二套保护回路交流电压空开。', NULL, '1、在220kV福泉Ⅱ线CVT本体、220kV福泉Ⅱ线2259CT本体处、220kV福泉Ⅱ线2259开关本体及就地控制柜处、220kV福泉Ⅱ线避雷器本体处、220kV福泉Ⅱ线线路侧刀闸22596本体周围装设安全遮栏，并向内悬挂“止步，高压危险！”标示牌，在遮栏入口处悬挂“从此进出！”标示牌； 2、在220kV福泉Ⅱ线开关#2M侧22592刀闸、220kV福泉Ⅱ线开关#1M侧22591刀闸、220kV福泉Ⅱ线开关线路侧22596刀闸机构箱把手处悬挂“禁止合闸，有人工作！”标示牌，同时在主控室操作员工作站显示屏的相应操作处，设置“禁止合闸，有人工作！”标示牌； 3、在220kV福泉Ⅱ线开关#2M侧22592刀闸、220kV福泉Ⅱ线开关#1M侧22591刀闸、220kV福泉Ⅱ线开关线路侧22596刀闸电机电源、控制电源空气开关上悬挂“禁止合闸，有人工作！”标示牌；在220kV福泉Ⅱ线CVT端子箱内1MCB-a计量回路交流电压A相空开、1MCB-b计量回路交流电压B相空开、1MCB-c计量回路交流电压C相空开、3MCB第一套保护回路交流电压空开、2MCB第二套保护回路交流电压空开处悬挂“禁止合闸，有人工作！”标示牌；在24P 220kV福泉Ⅱ线线路保护A屏2259第一组控制电源开关4K1、第二组控制电源开关4K2处悬挂“禁止合闸，有人工作！”标示牌。 4、在220kV福泉Ⅱ线CVT本体、220kV福泉Ⅱ线2259CT本体处、220kV福泉Ⅱ线2259开关本体及就地控制柜处、220kV福泉Ⅱ线避雷器本体处、220kV福泉Ⅱ线线路侧刀闸22596本体处悬挂“在此工作！”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'fbe8f361bf7c4b12a6e3b4ce3c58639e', '2022-01-14 21:45:16', NULL, '41', NULL, NULL, NULL, NULL, '2259。', NULL, NULL, NULL, '65267c2bc78641ef842b8592b7798581', NULL, '1、工作负责人必须严格执行工作票制度,现场对工作班成员进行安全措施、技术措施和作业任务及操作危险点和控制措施交底；\\r\\n2、必须在得到工作许可人通知，确认安全措施后，检修工作人员方能进入工作现场；\\r\\n3、进入工作现场后必须认真核对设备名称和编号，防止走错间隔；\\r\\n4、工作负责人确认作业人员应具备良好的精神状态,工作时要精力集中，睡眠不好、精神不佳者，禁止作业；\\r\\n5、工作负责人必须严格、认真执行现场监护且不得兼做其它工作；\\r\\n6、登高作业人员必须具备登高作业资质，无登高作业资质者严禁进行登高作业；\\r\\n7、工作开始前须认真检查工器具，发现异常或不满足要求者严禁使用；\\r\\n8、搬运仪器、工具、材料时与带电设备应保持足够安全距离；\\r\\n9、登高/登梯作业人员必须穿软底胶鞋，登高/登梯前必须清除干净鞋底淤泥；\\r\\n10、现场所有人员,必须正确佩戴安全帽，高处作业人员必须正确系好安全带；\\r\\n11、做好疫情防控措施：根据《超高压公司广州局海口分局应对新型冠状病毒感染肺炎疫情安全生产专项方案》和海口分局生产领域应对新型冠状病毒感染肺炎疫情工作措施清单要求做好检修作业过程各项疫情防控措施，每天对全体人员进行2次体温监测，检查工作人员状态有无发热、乏力、干咳等新冠病毒感染症状，核实各工作人员是否存在与确诊、疑似新冠病例近距离接触的情况。作业过程中必须全程戴口罩，必要时戴手套和护目镜，每日作业前后对使用工器具进行消毒。', '225917、225967、2259617。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D532203B0C27CA42E05302C0790A7284', NULL, '本次工作不需退出500kV桂山乙线线路自动重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 15:02:19', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '45d217f354c6454daa568ad07acb6d36', '2022-01-18 15:02:19', NULL, '14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '6c34bde548ea4a4db8d02cb477f37b38', NULL, '1、注意行车安全，注意山体滑坡；2、登塔人员应穿全套合格的屏蔽服或静电防护服，且各部分连接可靠； 3、塔上作业人员与绝缘架空地线的安全距离不得小于0.6m； 4、塔上作业人员、工具、材料与带电体安全距离不得小于5m； 5、塔上作业人员转移及作业过程中不得失去安全带的保护，现场所有工作人员须正确佩戴安全帽； 6、作业应在良好天气下进行，遇雷、雨、雾、5级及以上大风时，不得进行作业；7、做好疫情期间个人防护工作、行车安全及应急药品准备。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D532DBEEE1647DF2E05301C0790AE3E4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 15:18:54', '0102', '无。', NULL, '在#1B主变A、B、C三相，#2B主变A、B、C三相，#3B主变A、B、C三相，500kV青山甲线高抗A、B、C三相及中性点电抗器，500kV青山乙线高抗A、B、C三相及中性点电抗器，500kV青八甲线高抗A、B、C三相及中性点电抗器本体取油阀处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：18786707830。', '6ad1ce1af63c4229b386fbded374a340', '2022-01-11 15:18:54', NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cf2c5cc27ced4190be336f0ed7017204', NULL, '高压试验班对工作过程中产生的废油进行收集，并报送生技部进行报废处理。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D534773DA2D37936E05302C0790A5969', NULL, '本次工作无需退出线路重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-18 15:15:03', '0101', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '运行单位现场负责人：廖鹏 电话：13631304362。施工单位现场负责人：陈继申 电话：15014644391。[交底单号：2022-01-S0-017]', '78c81db9edf7456ab9ccbd9bbfe07901', '2022-01-18 15:15:03', NULL, '28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'b4452ced08d4492ea7047f5b0976ae75', NULL, '1、线路作业应在良好的天气下进行，遇有恶劣气象条件时（工作过程中如遇雷电（听见雷声、看见闪电）、雪、雹、雨、雾等（湿度大于80%）、风力大于5级或其他威胁人员及设备安全的情况时），应停止工作。\\r\\n2、施工人员必须得到工作负责人的通知后，方可组织开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路。\\r\\n3、登塔前必须检查导电鞋和全套静电感应防护服本体及连接是否完好，确保身体各部位均得到保护后方可登塔工作。\\r\\n4、所有作业塔位工作人员及工器具使用必须与带电体保持大于500kV交流线路5米的安全距离， 人员到达作业点时，在未挂好接地前，人员严禁触碰架空地线，并与架空地线保持0.6米以上的安全距离，安装地线拉力传感器必须在作业点悬挂临时接地线。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D535FA753E261C14E05302C0790AA2BF', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 11:46:04', '0108', '无。', NULL, '1、在站公用控制保护室S1-302J 保护及故障信息子站控制柜前后悬挂“在此工作！”标示牌，并在与其相邻的屏柜前后悬挂“运行设备！”标示牌并粘贴红色“运行设备！”胶带； 3、在主控室保护信息子站工作站上悬挂“在此工作！”标示牌，并在于其相邻的工作站前放置“运行设备！”标示牌并粘贴红色“运行设备！”胶带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '1df9742481224375ae946e4b618514ef', '2022-01-11 11:46:04', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f264bb23554f440ea97ec718da1a6c7b', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D535FA753E7C1C14E05302C0790AA2BF', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '500kV来宾变电站侧5053、5052断路器；\\r\\n500kV平果变电站侧P5041、P5042断路器；\\r\\n500kV来宾变电站侧50536隔离开关；\\r\\n500kV平果变电站侧P50416隔离开关。\\r\\n', NULL, NULL, '0.000000000000000', '2022-01-20 22:27:46', '0103', NULL, NULL, '在500kV平来Ⅱ线来宾变电站侧50536隔离开关远方控制把手和现场现场操作机构箱上悬挂“禁止合闸，线路有人工作”的安全标示牌；\\r\\n在500kV平来Ⅱ线平果变电站侧P50416隔离开关远方控制把手和现场现场操作机构箱上悬挂“禁止合闸，线路有人工作”的安全标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '00218622D9A93D2A', '2022-01-20 22:27:46', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, '500kV来宾变电站侧5053617接地刀闸；\\r\\n500kV平果变电站侧P5041617接地刀闸。\\r\\n', NULL, 'a0235de522ae461fba7e9c4a0ceb170a', NULL, '1. 登杆塔作业前，应核对线路名称和工作地点杆塔号，确认无误后方可登塔作业，防止误登带电线路； 2.现场所有工作人员必须戴安全帽，高处作业不得失去安全带的保护； 3.同一塔上作业时，不允许同一垂直线多人上、下塔或作业，以防掉物伤人,上下塔过程中及塔上作业严禁吸烟； 4.工作负责人必须对工作人员的安全认真监护，及时纠正不安全行为； 5.在6级及以上的大风以及暴雨、雷电、冰雹、大雾、沙尘暴等恶劣天气下，应停止露天高处作业； 6、在停电的电气设备上接地（装设接地线）前，应先验电，验明电气设备确无电压。高压验电时应戴绝缘手套并有专人监护；7、装设、拆除接地线时，应戴绝缘手套，应有人监护；8、在导（地）线上作业时应采取防止坠落的后备保护措施。在相分裂导线上工作，安全带可挂在一根子导线上，后备保护绳应挂在整组相（极）导线上；9.紧线、松线时按架线施工方案要求采用独立系统的二道保护锚线。10.工作完工后，作业人员布置的安全措施已拆除并恢复至作业前状态，现场已清理，人员已撤离，方可办理作业终结工作；', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D535FAAC84321C24E05302C0790A6143', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 14:08:40', '0104', '无。', NULL, '依次在500kV龙河甲线5041DK高抗A、B、C三相，#1主变A、B、C三相取油阀处悬挂\"在此工作\"标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '无。', 'ebcf26ccaa514c55b1a9f0effb689d9b', '2022-01-11 14:08:40', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '44d2a241e59a4df1a289dc6517ec92d6', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D535FAAC89611C24E05302C0790A6143', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-16 16:02:28', '0103', '退出22小室9P 220kV南利Ⅱ线主一保护屏 跳N2058 A相 #1线圈1LP1压板、跳N2058 B相 #1线圈1LP2压板、跳N2058 C相 #1线圈1LP3压板、重合闸出口1LP4压板、三相不一致跳闸出口1LP5压板、永跳闭锁主二保护重合闸1LP7压板、跳A启动N2058失灵保护1LP10压板、跳B启动N2058失灵保护1LP11压板、跳C启动N2058失灵保护1LP12压板、投光纤差动一1LP19压板、投光纤差动二1LP20压板、投距离保护1LP21压板、投零序保护1LP22压板、投远跳1LP26压板。', NULL, '在22小室9P 220kV南利Ⅱ线主一保护屏前挂“在此工作！”标示牌，将工作屏内的非工作设备面板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-014]', 'a368ca694bb049e1a905a438cd9dcb19', '2022-01-16 16:02:28', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ba37ceeb8cde466db9e4aebf3eca73c8', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5361F62BD3FDCE5E05301C0790A92E8', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-12 17:16:49', '0101', '无。\\r\\n', NULL, '在极1低端阀冷#3冷却塔处悬挂“在此工作”标示牌；分别在极1低端阀冷室极1低端阀冷控制系统主电源屏(=21U21+UT1.A)、极1低端阀冷室极1低端阀冷控制系统变频器屏(=21U21+UT1.B)、极1低端阀冷室极1低端阀冷控制系统DFU400装置屏(=21U21+UT1.C)、极1低端阀冷室极1低端阀冷控制系统S7控制器屏(=21U21+UT1.D)前后悬挂“在此工作”标示牌；并在相邻运行屏柜前后粘贴“运行设备”安全警示带。\\r\\n', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。\\r\\n', NULL, '0.000000000000000', NULL, NULL, '工作工程中需多次分合极1低端阀冷室极1低端阀冷控制系统变频器屏(=21U21+UT1.B)内#3冷却塔风扇变频器交流电源空开-Q48、-Q50，强投空开-Q48A、-Q50A。', 'aada8d631a39451d9490b37374c93eb1', '2022-01-12 17:16:49', NULL, '31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7fb5f471339842ee89cf10e2b6cab1f4', NULL, '无。', NULL, NULL, '不需要停电。\\r\\n');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D536269A11D0030DE05310C0790A5942', NULL, NULL, '50112、50222、50312、50412、50522、50612、50712。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 22:33:00', '0104', '1、断开50112、50312、50412、50522、50612、50712隔离开关电机电源QF1、控制电源QF3；\\r\\n2、断开50222隔离开关控制电源总空开QF1、电机电源空开QM1；\\r\\n3、断开500kV #1M母线CVT端子箱二次侧2ZKK 51/52室同期电压空气开关、3ZKK 53室同期电压空气开关；\\r\\n4、分别断开5031断路器A相电机电源空气开关QF1/A、B相电机电源空气开关QF1/B、C相电机电源空气开关QF1/C，5041断路器A相电机电源空气开关QF1/A、B相电机电源空气开关QF1/B、C相电机电源空气开关QF1/C，5061断路器A相电机电源空气开关QF1/A、B相电机电源空气开关QF1/B、C相电机电源空气开关QF1/C；\\r\\n5、分别断开5031断路器第一组分合闸电源4K1空气开关、第二组分闸电源4K2空气开关，5041断路器第一组分合闸电源4K1空气开关、第二组分闸电源4K2空气开关，5061断路器第一组分合闸电源4K1空气开关、第二组分闸电源4K2空气开关。', NULL, '1、在工作区域装设安全围栏，围栏内的设备包括：500kV换柳乙线50711隔离开关、507117接地刀闸，500kV换柳甲线50611隔离开关、506117接地刀闸，500kV河柳甲线50511隔离开关、505117接地刀闸，500kV柳贺乙线50411隔离开关、504117接地刀闸，500kV柳贺甲线50311隔离开关、503117接地刀闸，#2主变500kV侧50211隔离开关、502117接地刀闸，#1主变500kV侧50111隔离开关、501117接地刀闸，500kV#1M母线5117、5127接地刀闸本体及机构箱 ；500kV柳贺甲线5031断路器、500kV柳贺乙线5041断路器、500kV换柳甲线5061断路器机构箱及汇控箱，围栏向内悬挂“止步，高压危险！”标示牌，围栏内面向围栏入明显处悬挂“在此工作”标示牌。在围栏入口处悬挂“从此进出”标示牌；\\r\\n2、分别在50112、50222、50312、50412、50522、50612、50712隔离开关现场操作机构处悬挂“禁止合闸，有人工作”标示牌，并在监控界面50112、50222、50312、50412、50522、50612、50712隔离开关作“禁止合闸，有人工作”标识；\\r\\n3、在500kV#1M母线CVT端子箱内二次电压空气开关：2ZKK 51/52室同期电压空气开关，3ZKK 53室同期电压空气开关放置“禁止合闸，有人工作”标识；\\r\\n4、将50112、50222、50312、50412、50522、50612、50712隔离开关机构箱加挂检修隔离锁。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'acd9d158e88747508f4a70d87f23e824', '2022-01-15 22:33:00', NULL, '54', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'c5c167fab343468b953934e83c49b44d', NULL, '无。', '5117、5127、501127、502227、503127、504127、505227、506127、507127接地刀闸，共9把。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D53686650F0D1D2FE05302C0790A4BCB', NULL, NULL, '21705、21706、21704。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 09:35:23', '0101', '1、退出12P 220kV 花文甲线第一套保护屏内以下压板：\\r\\n1LP10 PSL-603UWC保护跳A启动#5M、#6M母差1、1LP11 PSL-603UWC保护跳B启动#5M、#6M母差1、1LP12 PSL-603UWC保护跳C启动#5M、#6M母差1、1LP26 PSL-603UWC远跳开入、4LP1 PCX-AFL花文甲线2170开关三跳启动失灵I、4LP2 PCX-AFL花文甲线2170开关三跳启动失灵II，将1QK重合闸方式切换把手切至“停用”状态； \\r\\n2、退出13P 220kV 花文甲线第二套保护屏内以下压板：\\r\\n1LP10 PCS-931N2保护跳A启动#5M、#6M母差2、1LP11 PCS-931N2保护跳B启动#5M、#6M母差2、1LP12 PCS-931N2保护跳C启动#5M、#6M母差2、将1QK重合闸方式切换把手切至“停用”状态； \\r\\n3、断开21705、21706、21704刀闸的控制电源空开F4及电机电源空开F71、F72、F73。', NULL, '1、在21705、21706、21704刀闸操作把手处悬挂“禁止合闸，有人工作”标示牌；\\r\\n 2、在21705刀闸的控制电源空开F4及电机电源空开F71、21706刀闸的控制电源空开F4及电机电源空开F72、21704刀闸的控制电源空开F4及电机电源空开F73处分别悬挂“禁止合闸，有人工作”标示牌；\\r\\n 3、在220kV #2继保室：220kV花文甲线第一套保护屏（12P）、220kV花文甲线第二套保护屏（13P）、220kV故障路波屏2（33P）、220kV线路电度表屏2（35P） 前后悬挂“在此工作”标示牌，并在其相邻的运行屏柜悬挂“运行设备”警示带； \\r\\n4、在220kV交流场：220kV花文甲线2170开关现场汇控柜分别悬挂“在此工作”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险”标示牌，遮栏出入口围至临近道路旁边，并设有“从此进出”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作中需多次分合2170开关及其操作电源4K1、4K2，需多次分合220kV花文甲线2170开关', '5b175ea2b8674e99ab27fa9142a74a0a', '2022-01-19 09:35:23', NULL, '22', NULL, NULL, NULL, NULL, '2170 。', NULL, NULL, NULL, '11e75c1b4a0241e8b3d72ae2220a8980', NULL, '将21705、21706、21704刀闸机构箱上锁。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5368F97C779030BE05310C0790A64F2', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 17:22:25', '0102', '无。', NULL, '1、分别在主控室机器人巡检系统服务器及工作站、视频监控系统工作站处悬挂“在此工作！”标示牌；2、在交接班室智能锁具工作站处悬挂“在此工作！”标示牌；3、分别在通信室E11智能摄像机设备屏、E11智能摄像机设备屏、F04图像监控系统屏前后处悬挂“在此工作！”标示牌；4、分别在智能摄像机500kV开关场#1汇控箱、智能摄像机500kV开关场#2汇控箱、智能摄像机220kV开关场#1汇控箱、智能摄像机220kV开关场#2汇控箱、智能摄像机35kV开关场#1汇控箱处悬挂“在此工作！”标示牌；5、分别在主控室融冰系统工作站、调度指挥网络交互终端处悬挂“运行设备”红布；6、分别在通信室F03动力环境监控系统屏、F05 220kV山都双回保护接口屏、E12广域失步解列子站通信接口屏前后处悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '工作负责人联系电话：13984166421。', '58f3685e9c6f4643b1e7751d714acf70', '2022-01-11 17:22:25', NULL, '45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '736842e2e20b43baabe1951d8d9d6ecf', NULL, '无。', NULL, NULL, '不需要停电。');
