INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D536A3F0F5CBB58DE05301C0790A7D32', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-11 09:59:28', '0102', '无', NULL, '1、在安稳及监控室新增智能网关设备屏柜处悬挂“在此工作！”标示牌； 2、在安稳及监控室新增视频监控存储设备屏柜处悬挂“运行设备”红布； 3、在安稳及监控室 16P 监控系统服务器及工作站主机屏处悬挂“运行设备”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电', NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：134245671670', 'cdef4e94badf4ae9a8c1c7f544e609c3', '2022-01-11 09:59:28', NULL, '11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '149994261c9046ca839eb7a27eb57839', NULL, '无', NULL, NULL, '不需要停电');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D536A3F0F961B58DE05301C0790A7D32', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-14 20:55:27', '0103', '无。', NULL, '1、在51小室：6P 51小室公用测控柜前后分别悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带； \\r\\n2、在计算机室：2P 综合自动化网络屏（一）前后分别悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带；\\r\\n3、在计算机室：监控系统服务器1、监控系统服务器2分别放置“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '33e8eae3d0a4434bae22201471b0fc21', '2022-01-14 20:55:27', NULL, '17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5f1f0e8b64a8408ebab54aded96d26cb', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D536A3F0FA63B58DE05301C0790A7D32', NULL, NULL, 'N20583、N20584、N20586刀闸。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 20:29:06', '0103', '1、退出22小室9P 220kV南利Ⅱ线主一保护屏 跳N2058 A相 #1线圈1LP1压板、跳N2058 B相 #1线圈1LP2压板、跳N2058 C相 #1线圈1LP3压板、重合闸出口1LP4压板、三相不一致跳闸出口1LP5压板、永跳闭锁主二保护重合闸1LP7压板、跳A启动N2058失灵保护1LP10压板、跳B启动N2058失灵保护1LP11压板、跳C启动N2058失灵保护1LP12压板、投光纤差动一1LP19压板、投光纤差动二1LP20压板、投距离保护1LP21压板、投零序保护1LP22压板、投远跳1LP26压板；\\r\\n2、退出22小室10P 220kV南利Ⅱ线主二保护屏 跳N2058 A相 #2线圈1LP1压板、跳N2058 B相 #2线圈1LP2压板、跳N2058 C相 #2线圈1LP3压板、重合闸出口1LP4压板、三相不一致跳闸出口1LP5压板、永跳闭锁主一保护重合闸1LP7压板、跳A启动N2058失灵保护1LP10压板、跳B启动N2058失灵保护1LP11压板、跳C启动N2058失灵保护1LP12压板、投差动保护1LP19压板、投光纤通道一1LP20压板、投光纤通道二1LP21压板、投距离保护1LP22压板、投零序保护1LP23压板、投远跳1LP26压板。', NULL, '在22小室9P 220kV南利Ⅱ线主一保护屏、10P 220kV南利Ⅱ线主二保护屏前挂“在此工作！”标示牌，将工作屏内的非工作设备面板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-016]启动试运行指挥组长通知启动，当天收票。', '2ec8fba88bb242fe998f8f1e68154cc5', '2022-01-15 20:29:06', NULL, '26', NULL, NULL, NULL, NULL, 'N2058开关。', NULL, NULL, NULL, 'e8ddd6050f544437a5599fa003a00834', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D536A3F0FC3BB58DE05301C0790A7D32', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 16:49:16', '0106', '无。', NULL, '在500kV武平变电站：主控楼主控室火灾报警控制器，应急装备间、门卫值班室、门卫休息室、厨房、中央配电室、#1站用变室、#2站用变室、#0站用变及10kV开关室、交流配电室、检修办公室、安全工器具室、#2蓄电池室、#1蓄电池室、电缆层、资料间、主控室、会议室、站长室、保护及通信室、第一休息室、第二休息室感烟探头，主控楼一楼：#2消火栓、#3消火栓、#4消火栓，主控楼二楼：#1消火栓、#5消火栓、#6消火栓，35kV 313电容器组旁#1消火栓、 #1B主变A相旁#2消火栓、中央配电室旁#3消火栓，综合水泵房、泡沫消防设备间，500kV富武甲线高抗A、B、C相消防模块箱，500kV富武乙线高抗A、B、C相消防模块箱， #1B主变A、B、C相消防模块箱， #3B主变A、B、C相消防模块箱分别悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '64665fb5857245848b31bfb6b22222ee', '2022-01-19 16:49:16', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '33f35a35e360411aac4414dae3a7824d', NULL, '无。', NULL, NULL, '不需要停电。');
