INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D574AD9F48868A95E05310C0790A4671', NULL, NULL, '50111、50112、50311、50312。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-15 22:33:58', '0104', '断开50111、50112、50311、50312隔离开关电机电源QF1空气开关、控制电源QF3空气开关。', NULL, '1、在工作区域装设安全围栏，围栏内的设备包括：500kV柳贺甲线5031CT、#1主变500kV侧5011CT本体及端子箱，围栏向内悬挂“止步，高压危险！”标示牌，围栏内面向围栏入明显处悬挂“在此工作”标示牌。在围栏入口处悬挂“从此进出”标示牌；\\r\\n2、分别在50111、50112、50311、50312隔离开关现场操作机构处悬挂“禁止合闸，有人工作”标示牌，并在监控界面50111、50112、50311、50312隔离开关作“禁止合闸，有人工作”标识；\\r\\n3、将50111、50112、50311、50312隔离开关机构箱加挂检修隔离锁。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'c5c167fab343468b953934e83c49b44d', '2022-01-15 22:33:58', NULL, '27', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '1d426986fb384ef38908dae5ca76fadb', NULL, '无。', '501117、501127、503117、503127接地刀闸，共4把。', NULL, NULL);
