INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5958369EE64662EE05310C0790AAA38', NULL, NULL, '将027DL断路器手车摇至试验位置、4bDL断路器手车摇至试验位置。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 11:45:08', '0104', '断开380V公用配电室10P 400V #40bM进线柜进线PT以下空气开关：进线一次侧电压22QF、进线A相测量电压22MCB4a、进线B相测量电压22MCB4b、进线C相测量电压22MCB4c、进线A相计量电压22MCB5a、进线B相计量电压22MCB5b、进线C相计量电压22MCB5c。', NULL, '1、分别在027DL、4bDL断路器现场手车操作把手处悬挂“禁止摇至工作位置”标示牌，并在后台监控界面相应位置设“禁止摇至工作位置”标识。 \\r\\n2、分别在380V公用配电室10P 400V #40bM进线柜进线PT以下空气开关：进线一次侧电压22QF、进线A相测量电压22MCB4a、进线B相测量电压22MCB4b、进线C相测量电压22MCB4c、进线A相计量电压22MCB5a、进线B相计量电压22MCB5b、进线C相计量电压22MCB5c上装设“禁止合闸，有人工作”标识。\\r\\n3、分别在380V公用配电室10kV #1bB干式变本体柜、10P 400V #40bM 进线柜，10kV开关柜室25P 10kV #1bB干式变027DL断路器柜前后悬挂“在此工作”标示牌，在相邻屏柜前后装设“运行设备”标识，分别在10kV开关柜室、380V公用配电室进门处悬挂“从此进出”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '77cb76309d574cc58e2720efdef1ace6', '2022-01-21 11:45:08', NULL, '58', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'd4ffd0cebdcb4243a10b13578b4da130', NULL, '无。', '1、0277接地刀闸，共1把； \\r\\n2、在10kV #1bB干式变400V侧装设400V接地线1组，共1组。', NULL, NULL);
