INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5EDDB8EE8B2768EE05302C0790A7850', NULL, NULL, '95464。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-22 20:08:02', '0101', '1、断开95464刀闸控制电源空开DK23及电机电源空开DK43；2、断开220kV东创甲线电容式互感器T5的二次侧空开DK31。', NULL, '1、在95464刀闸就地操作把手处悬挂“禁止合闸，有人工作”标示牌；\\r\\n2、在95464刀闸控制电源空开DK23及电机电源空开DK43处悬挂“禁止合闸，有人工作”标示牌；\\r\\n3、在220kV东创甲线电容式互感器T5的二次侧空开DK31处悬挂“禁止合闸，有人工作”标示牌；\\r\\n4、在220kV东创甲线GIS出线套管、线路电压互感器、避雷器及出线悬垂绝缘子处分别悬挂“在此工作”标示牌，并在其四周装设围栏，向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '在220kV东创甲线电容式互感器出线侧装设一组220kV临时接地线；[交底单号：2022-01-C0-007]', '6751a591d43b4c0f9c789bc2fcbc1a18', '2022-01-22 20:08:02', NULL, '33', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '5f4004837df64cd3805be17889683455', NULL, '无。', '954640。', NULL, NULL);
