INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5EDF304FB663456E05301C0790A89F9', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '从西换流站侧:15105、15205刀闸\\r\\n牛寨换流站侧:15105、15205刀闸\\r\\n从西换流站侧:25105、25205刀闸\\r\\n牛寨换流站侧:25105、25205刀闸', NULL, NULL, '0.000000000000000', '2022-01-29 01:33:16', '0101', NULL, NULL, '在从西换流站侧：15105、15205刀闸远方控制把手和现场操作机构箱上悬挂设置\"\"禁止合闸，线路有人工作\"\"标示牌。 \\r\\n在牛寨换流站侧：15105、15205刀闸远方控制把手和现场操作机构箱上悬挂设置\"\"禁止合闸，线路有人工作\"\"标示牌。 \\r\\n在从西换流站侧：25105、25205刀闸远方控制把手和现场操作机构箱上悬挂设置\"\"禁止合闸，线路有人工作\"\"标示牌。 \\r\\n在牛寨换流站侧：25105、25205刀闸远方控制把手和现场操作机构箱上悬挂设置\"\"禁止合闸，线路有人工作\"\"标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、广州局牛从直流地线融冰试验线路组组长兼间接许可人：郑武略 联系电话：13925168187；2、广州局工作负责人：罗凯 联系电话：15622108030。', 'd5c17730a18d45eea53cc557e126ba1c', '2022-01-29 01:33:16', NULL, '3', NULL, NULL, NULL, NULL, NULL, NULL, '从西换流站侧:151217、151227接地刀闸 \\r\\n牛寨换流站侧:151217、151227接地刀闸 \\r\\n从西换流站侧:251217、251227接地刀闸 \\r\\n牛寨换流站侧:251217、251227接地刀闸', NULL, 'd284535f64e3488991522d1e4614dcf7', NULL, '1、高空作业人员不得失去安全带的保护，工作现场应有专人监护；2、严禁上下抛掷物品；3、恶劣天气如雷雨、大风、浓雾等应停止工作；4、全部工作完成后清理现场，杆塔上不得遗留物品。', NULL, NULL, NULL);
