INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5EFBC4E1E8A2619E05301C0790A3B07', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 18:03:17', '0103', '退出22P #N1B主变非电气量保护屏#N1B主变非电气量保护投本体重瓦斯跳闸5LP17压板。', NULL, '在#N1B主变A相呼吸器、#N1B主变B相呼吸器、#N1B主变C相呼吸器处分别放置“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '3117c820d0544d4e8269e269d300a78f', '2022-01-24 18:03:17', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'aa0b89761d7c4be3b1068d56f1cadd3b', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5EFBC4E1F972619E05301C0790A3B07', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 21:43:53', '0104', '无。', NULL, '1、在极1低端阀冷设备间门口悬挂“从此进出”标示牌；2、在极1低端换流器外冷水系统石英砂过滤器C65本体处悬挂“在此工作”标示牌。3、在极1低端阀冷控制设备室：3P 极1低端换流阀外冷水处理控制屏前后悬挂“在此工作”标示牌，并在相邻屏柜装设“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'ef693eafeaf140a9a2683cdfdf1454da', '2022-01-25 21:43:53', NULL, '28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'db424b757a7d47108da3c6b416a56e94', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5EFBC4E2AB12619E05301C0790A3B07', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-26 13:16:21', '0103', '无。', NULL, '1、在计算机室：监控系统服务器1、监控系统服务器2分别放置“在此工作！”标示牌；\\r\\n2、在31小室：10P 31小室公用测控柜、15P 110V #1直流充电柜、18P 110V #2直流充电柜、38P 110V #3直流充电柜前后悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, NULL, NULL, NULL, NULL, '041d4b0d5e9b485a9a041c13184995e3', '2022-01-26 13:16:21', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'cad63ea90adb4b2ea32712c70ab0b18c', NULL, '无。', NULL, NULL, '不停电。');
