INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F149D29E265AABE05302C0790AC8F1', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 16:13:54', '0101', '无。', NULL, '分别在牛从甲直流极1阀厅空调A、B单元空气处理机、空气处理机控制屏和A、B单元冷水机组、冷水机组控制屏、牛从甲直流极2阀厅空调A、B单元空气处理机、空气处理机控制屏和A、B单元冷水机组、冷水机组控制屏，牛从乙直流极1阀厅空调A、B单元空气处理机、空气处理机控制屏和A、B单元冷水机组、冷水机组控制屏、牛从乙直流极2阀厅空调A、B单元空气处理机、空气处理机控制屏和A、B单元冷水机组、冷水机组控制屏、主控楼空调A、B单元空气处理机、空气处理机控制屏和A、B单元冷水机组、冷水机组控制屏、主控楼和辅控楼各房间室内空调机组、主控楼主控室空调工作站处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'c4d626fbfcc24255bccb227bd249c8ea', '2022-01-21 16:13:54', NULL, '16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '909fc06e22524888beecf22846741693', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F1A82547F55D1FE05302C0790AC92F', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 20:40:27', '0110', '无。', NULL, '1、在±500kV直流场区域悬挂“在此工作！”标示牌；2、分别在500kV #1站用变区域及35kV #1站用变区域悬挂“在此工作！”标示牌；3、分别在500kV #2站用变区域及35kV #2站用变区域悬挂“在此工作！”标示牌；4、在35kV #3站用变区域悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'edd7e67bdaf44bef9518fa6fdc5dbd89', '2022-01-21 20:40:27', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ec1d4eda084f44fe86bcb57045bcedeb', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F220EF1CCD5BA4E05302C0790A40D4', NULL, NULL, '无。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 09:08:25', '0101', '无。', NULL, '在极1低端阀冷室#1、#2主泵电机处设置“在此工作”标示牌；在极1低端阀冷控制系统主电源屏(=21U21+UT1.A)前后悬挂“在此工作”标示牌，并在相邻运行屏柜上粘贴“运行设备”警示带。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作过程中需多次分合极1低端阀冷控制系统主电源屏(=21U21+UT1.A)内主泵电机空开-Q11、-Q12。', '63eb830bbece4321bdbc2c2b16062408', '2022-01-24 09:08:25', NULL, '31', NULL, NULL, NULL, NULL, '5041、5042。', NULL, NULL, NULL, '1e4715fa4d234a99b16706097918909c', NULL, '无。', '无。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F2DDE29C4225B1E05301C0790A05C3', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 15:23:30', '0105', '无。', NULL, '在500kV来梧Ⅰ线高抗B相油色谱在线监测装置处挂“在此工作！”标示牌。\\r\\n', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交代：500kV来梧Ⅰ线高抗B相油色谱在线监测装置载气更换工作结束。存在问题：无。结论：正常。', 'b46b74e19d304bf6a6b103832993073e', '2022-01-28 15:23:30', NULL, '25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2316939b17e94bd6a0d64e3be8eb64cc', NULL, '工作中不得触碰与工作无关的设备，与带电设备保持足够的安全距离，500kV带电设备安全距离5米。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F60C04F50E347AE05301C0790A820D', NULL, NULL, '50331、50322、08110、04120。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-23 23:40:06', '0101', '1、断开50322刀闸控制电源空开F212 和电机电源空开SA；断开50331 刀闸控制电源空开F213 和电机电源空开SA；断开08110、04120刀闸控制电源空开F231 和电机电源F184；断开极1高端换流变馈线电压互感器端子箱（=20B03.C+UT5）内以下二次电压空开：计量电压至51小室=20Q10+Q11 -F711、测量电压至主控楼=21Q00+Q2 -F721、保护电压至极1辅控楼=21T10+R2 -F722、测量电压至极1辅控楼=21QG11+Q2 -F723、测量电压至51小室=20B03+SW1 -F724、故障录波电压至主控楼=21FX21+X1 -F725、故障录波电压至51小室=20FX61+S2 -F726、测量电压至主控楼=21Q00+Q1 -F731、保护电压至极1辅控楼=21T10+R1 -F732、测量电压至极1辅控楼=21QG11+Q1 -F733、保护电压至51小室=20B03.C+R1 -F734、监控电压至极1辅控楼=21X81+X1 -F735。', NULL, '1、在50322刀闸机构箱操作把手、控制电源空开F212 和电机电源空开SA，50331 刀闸机构箱操作把手、控制电源空开F213 和电机电源空开SA，08110、04120刀闸机构箱操作把手、控制电源空开F231 和电机电源F184，极1高端换流变馈线电压互感器端子箱（=20B03.C+UT5）内以下二次电压空开：计量电压至51小室=20Q10+Q11 -F711、测量电压至主控楼=21Q00+Q2 -F721、保护电压至极1辅控楼=21T10+R2 -F722、测量电压至极1辅控楼=21QG11+Q2 -F723、测量电压至51小室=20B03+SW1 -F724、故障录波电压至主控楼=21FX21+X1 -F725、故障录波电压至51小室=20FX61+S2 -F726、测量电压至主控楼=21Q00+Q1 -F731、保护电压至极1辅控楼=21T10+R1 -F732、测量电压至极1辅控楼=21QG11+Q1 -F733、保护电压至51小室=20B03.C+R1 -F734、监控电压至极1辅控楼=21X81+X1 -F735处分别悬挂“禁止合闸，有人工作”标示牌；在极1高端Y/Y A、B、C相换流变，极1高端Y/△ A、B、C相换流变本体四周装设围栏并向内悬挂“止步，高压危险”标示牌，在围栏入口处悬挂“从此进出”、“在此工作”标示牌。\\r\\n', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '93b1e6467c7243888b87b92d7212fab7', '2022-01-23 23:40:06', NULL, '29', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '1e7cdf551b914c5fb14f2ba89f886b56', NULL, '对50331、50322刀闸机构箱上锁，对08110、04120刀闸实施机构闭锁。', '5033617、080117、080127。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F60C04FA00347AE05301C0790A820D', NULL, NULL, '3111。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 16:12:21', '0104', '断开3111隔离开关电机电源QF1空气开关及控制电源QF2空气开关。 ', NULL, '1、在3111隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，并在监控界面相应位置作“禁止合闸 有人工作”标识。 2、在相关停电设备工作区域装设安全围栏，围栏内设备包括35kV#1电容器组，并在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌。 4、将3111隔离开关机构箱常规锁更换为“检修隔离”锁。 ', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'FCFD8D80B6E21AAE', '2022-01-28 16:12:21', NULL, '35', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '88cccd6d45b840e4aa4da90393e18db1', NULL, '无。', '31117、31127接地刀闸，共2把。\\r\\n', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5F98FBB5EF55B77E05302C0790A3164', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 19:34:15', '0104', '无。', NULL, '1、在计算机室：8P 视频及环境监控系统主机柜1、12P 视频及环境监控系统主机柜2前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识。 2、在主控室：视频监控后台前放置“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'cc051568c0b840dd8c4ade92843b65d4', '2022-01-24 19:34:15', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '3169ee1035dc42b69bbf3fddaf1151da', NULL, '无', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5FA0EA002035AB1E05302C0790A7D7D', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 11:43:42', '0105', '无。', NULL, '在500kV第一保护小室、500kV第二保护小室、500kV第三保护小室、220kV保护小室、35kV第一保护小室、35kV第二保护小室、串补保护小室、110V直流室、站用电室、主控楼计算机室、通讯机房门口悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交待：工作内容：Ⅰ级特维安全稳定控制装置，Ⅱ级特维安全稳定控制装置，Ⅰ级特维交流保护装置，Ⅱ级特维交流保护装置，Ⅱ级特维串补保护装置，Ⅲ级特维交流保护装置，Ⅳ级特维交流保护装置，Ⅱ级特维自动化装置、Ⅲ级特维自动化装置，Ⅲ级特维保信、行波、录波装置，Ⅲ级特维微机防误闭锁装置、Ⅲ级特维直流系统、Ⅳ级特维UPS系统及站用直流系统装置等二次设备专业巡视。存在问题：关联工作票号：2022-01-C2-011 ，已完成贺州站全部二次设备及站用直流系统装置二次巡视。结论：合格。', '0364719582f943659a05f6d33559b459', '2022-01-25 11:43:42', NULL, '35', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1dff4e55be9a4104aa96c802cfc5e59a', NULL, '巡视作业及检查的所有对象均为运行设备及其回路，工作中防止误触电，防止误碰保护出口，防止误松动端子。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5FA63C6E5CC47F3E05302C0790A7A09', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 15:52:14', '0103', '无。', NULL, '1、在#P1B主变A相油色谱在线监测装置、#P1B主变B相油色谱在线监测装置、#P1B主变C相油色谱在线监测装置处分别悬挂“在此工作！”标示牌；2、在计算机室5P MGA2000系列变压器色谱在线监测系统屏前后悬挂“在此工作！”标示牌，并将工作屏柜内非工作设备的面板、背板用绝缘胶带封贴，同时将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, 'fabd727ed153493a8a5770778f1a1f2e', '2022-01-25 15:52:14', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f72ad7a931bf4da59d6298615a7f8555', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5FB0CE6484A23DFE05301C0790A306C', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 10:33:09', '0109', '无。', NULL, '1、分别在主控楼二楼极1低端阀组控制保护设备室、极2低端阀组控制保护设备室、站及双极控制保护设备室、通信机房门口悬挂“在此工作！”标示牌；2、分别在主控楼三楼主控室、系统分析室门口悬挂“在此工作！”标示牌；3、分别在主控楼一楼极1低端阀组冷却控制设备室、极2低端阀组冷却控制设备室门口悬挂“在此工作！”标示牌；4、在极1辅控楼二楼极1高端阀组控制保护设备室门口悬挂“在此工作！”标示牌；5、在极1辅控楼一楼极1高端阀组阀冷控制室门口悬挂“在此工作！”标示牌；6、在极2辅控楼二楼极2高端阀组控制保护设备室门口悬挂“在此工作！”标示牌；7、在极2辅控楼一楼极2高端阀组阀冷控制室门口悬挂“在此工作！”标示牌；8、在51继电器室门口悬挂“在此工作！”标示牌；9、在52继电器室门口悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交待：1、完成普洱换流站直流测量系统设备、直流控制设备、阀控系统设备、测控装置、电力监控系统设备、阀冷设备专业巡视，设备运行正常；2、完成普洱换流站工作站、服务器、交换机、路由器、二次安防系统设备资产核查工作，列出相应资产清单。存在问题：无。结论：合格。', '1eb4e33670ef44258325239d78276e4e', '2022-01-24 10:33:09', NULL, '35', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fbf2cb4bd6c2459dae078fa9f7886516', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5FB0FBBCA0F32E6E05301C0790A08A2', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-20 10:44:00', '0109', '退出52继电器室=10B05.A+R1 500kV小楚乙线5051断路器保护屏以下压板：3LP1（PRS-721NA-N 跳5051断路器A相#1线圈）、3LP2（PRS-721NA-N 跳5051断路器B相#1线圈）、3LP3（PRS-721NA-N 跳5051断路器C相#1线圈）、3LP4（PRS-721NA-N 5051断路器重合闸出口）、3LP5（PRS-721NA-N 跳5051断路器A相#2线圈）、3LP6（PRS-721NA-N 跳5051断路器B相#2线圈）、3LP7（PRS-721NA-N 跳5051断路器C相#2线圈）、3LP10（PRS-721NA-N 失灵跳5052断路器#1线圈）、3LP11（PRS-721NA-N 失灵跳5052断路器#2线圈）、3LP12（PRS-721NA-N 失灵启动500kV #1M第一套保护1）、3LP13（PRS-721NA-N 失灵启动500kV #1M第一套保护2）、3LP14（PRS-721NA-N 失灵启动500kV #1M第二套保护1）、3LP15（PRS-721NA-N 失灵启动500kV #1M第二套保护2）、3LP16（PRS-721NA-N 失灵至小楚乙线保护A屏远跳1）、3LP17（PRS-721NA-N 失灵至小楚乙线保护A屏远跳2）、3LP18（PRS-721NA-N 失灵至小楚乙线保护B屏远跳1）、3LP19（PRS-721NA-N 失灵至小楚乙线保护B屏远跳2）、8LP1（PRS-789 最后断路器启动ESOF极1高端系统1）、8LP2（PRS-789 最后断路器启动ESOF极1低端系统1）、8LP3（PRS-789 最后线路启动ESOF极1高端系统1）、8LP4（PRS-789 最后线路启动ESOF极I低端系统1）、8LP5（PRS-789 最后断路器启动ESOF极2高端系统1）、8LP6（PRS-789 最后断路器启动ESOF极2低端系统1）、8LP7（PRS-789 最后线路启动ESOF极2高端系统1）、8LP8（PRS-789 最后线路启动ESOF极2低端系统1）、8LP10（PRS-789 最后断路器启动ESOF极1高端系统2）、8LP11（PRS-789 最后断路器启动ESOF极1低端系统2）、8LP14（PRS-789 最后断路器启动ESOF极2高端系统2）、8LP15（PRS-789 最后断路器启动ESOF极2低端系统2）、8LP19（PRS-789 第一组直流跳5051断路器A相#1线圈）、8LP20（PRS-789 第一组直流跳5051断路器B相#1线圈）、8LP21（PRS-789 第一组直流跳5051断路器C相#1线圈）、8LP22（PRS-789 第二组直流跳5051断路器A相#2线圈）、8LP23（PRS-789 第二组直流跳5051断路器B相#2线圈）、8LP24（PRS-789 第二组直流跳5051断路器C相#2线圈）。', NULL, '分别在52继电器室=10B05.A+R1 500kV小楚乙线5051断路器保护屏前后门处悬挂“在此工作!”标识牌，并在相邻屏柜围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, NULL, NULL, NULL, '[交底单号：2021-12-C0-013]。检修交代：已执行5051断路器保护临时定值，定值单编号为《(总调)启-2021-楚雄站-02》，定值打印核对无误，具备投入条件。', '028039e692e0424f88f13ed7968cee8d', '2022-01-20 10:44:00', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ec762b3ec56543cebff500db91e21e92', NULL, '无。', NULL, NULL, '不需要停电。');
