INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D5FF3EF8D9265AE9E05302C0790AB53D', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-29 10:02:23', '0103', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[交底单号：2022-01-C0-022]', '7ce1404ef73b4bf69be0bf42506d5f8d', '2022-01-29 10:02:23', NULL, '1', NULL, '在500kV南宁变电站500kV设备区、220kV设备区、35kV设备区、主控楼、备品楼、门卫室周围区域处放置“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '06b9349d64e84c619dcf7a9342d9a500', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60005EFD64D5978E05302C0790A7CEC', NULL, '不需退出±800kV新东极1、极2直流线再启动功能\\r\\n', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 11:18:34', '0105', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人邓诗聪联系电话：15078165561。', '6244e2e67ea645e48b45511edc302c30', '2022-01-24 11:18:34', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fc8a019e232047dbaad7038064a090a2', NULL, '1、作业前应召开现场工前会，由工作负责人（监护人）对现场作业人员进行安全交代。交代内容包括工作任务及分工、作业地点及范围、作业环境及风险、安全措施及注意事项，并签名确认；2、作业应在良好天气下进行，如遇雷、雨、雾等天气不得进行带电登塔作业；风力大于5级，或湿度大于80%时，不宜进行带电作业；3、工作前必须检查工器具、资料等，确保准备齐全，工器具检查合格后可使用；4、登塔前，必须核对线路名称、塔号无误后，方可登塔作业，防止误登杆塔；5、登塔前，应观察塔上有无危及人员安全的隐患，若有需采取安全措施后才能作业；6、塔上人员必须穿戴整套完好合格的屏蔽服，并将衣服、裤子、鞋、袜、帽、手套各部件连接良好、牢固可靠；7、现场所有工作人员必须正确佩戴安全帽，并使用全身式高空安全带，在转位或作业过程中时，不得失去安全带的保护；安全带应采用环绕主材方式系在牢固的构件上，采用高挂低用的方式进行作业；8、工作过程中，严格执行工作监护制度：作业时，监护人必须对工作人员的安全认真监护，及时纠正、制止不安全行为；9、同一塔上作业时，不允许同一垂直线多人上、下塔或作业，以防掉物伤人；10、工作过程中如遇到雷、雨、雪、雾、风力大于5级等恶劣天气、塔上有蜂窝或其他威胁人员及设备安全的情况时，必须立即停止工作并向工作负责人汇报；11、杆塔上作业时必须与带电体保持10.1米以上的安全距离；12、杆塔上作业时必须与绝缘架空地线保持0.4米以上的安全距离，如需在绝缘架空地线上作业，应用接地线将其可靠接地，装设架空地线接地线时，必须先安装接地端，后装架空地线端；13、工作结束后，工作负责人必须确认工作人员已全部下塔，架空地线接地线已拆除且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60005EFD96F5978E05302C0790A7CEC', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 11:34:42', '0103', '无。', NULL, '在220kV保护小室：21P 220kV第一、二串故障录波器屏前后分别悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '6734798c02cf48b2814cd4e7aa1168d5', '2022-01-25 11:34:42', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '85f38a4330bd4752b31c0264889c77ce', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60005EFD9AD5978E05302C0790A7CEC', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 16:46:53', '0104', '退出146P 500kV来梧II线第一套保护屏以下连接片：9LP3（辅A保护RCS-925AMM跳5033三相#1线圈）、9LP4（辅A保护RCS-925AMM跳5032三相#1线圈）。', NULL, '1、继电保护室：146P 500kV来梧II线第一套保护屏前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识，并在同屏内 500kV来梧II线主一保护RCS-931DSMM前后粘贴“运行设备”标识。 2、微波机室：G01 500kV来梧I、II线光纤保护通道接口柜、D03 烽火光纤DDF配线架前后悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识；在同屏内500kV来梧I线主二通道二接口装置MUX-2MD、500kV来梧I线辅A通道二接口装置MUX-2MD、500kV来梧I线辅B通道二接口装置MUX-2MD、500kV来梧II线主三通道二接口装置MUX-2MD、500kV来梧II线辅B通道二接口装置MUX-2MD前后粘贴“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '6d86f366b88843f49921ee9a58fa72f0', '2022-01-26 16:46:53', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '18b1f67f74ff4165ba06dd9451c394f5', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60426F3F3FCD562E05310C0790A64B5', NULL, '安全措施： 1、分别在主控楼三楼主控室=10P01-P1运行人员工作站1、=10P01-P2运行人员工作站2、=10P02-P1交/直流工作站1、=10P02-P2交/直流工作站2前放置“在此工作！”标示牌。 2、在主控楼三楼系统分析室 =10XJ01-P1 控制保护工程师工作站、=10P05-P1工程师工作站前放置“在此工作！”标示牌。\\r\\n注意事项：1、严禁擅自修改控制保护工程师工作站程序；2、修改客户端程序配置时，做好备份；3、工作过程中出现非计划现象时，不得继续工作，待排查清楚后再考虑工作是否进行。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-21 10:12:50', '0109', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, '40a1686481ab4a7581d92f8b0f376da6', '2022-01-21 10:12:50', NULL, '12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '658de6fe8e89430aab332006350d6240', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60D29F034D94B13E05310C0790A0C35', NULL, '本次作业不需退出500kV沙柳乙线自动重合闸装置。', NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 12:43:27', '0104', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '1、工作负责人：蒋晖，联系电话：13977276917； 2、输电管理所值班电话：0772-2692037；3、工作票签发人：黄运兴，联系电话：13633089013；4、工作许可人：赵斌，联系电话：13597025557；5、参加工作的班组：线路五班。 ', '8b1f166642c44d7bb741979b055f869d', '2022-01-25 12:43:27', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1d37ca86ccca4b89899d62d289c533c6', NULL, '1、按规定办理线路第二种工作票。2、工作负责人得到输电管理所值班员的许可工作通知，到现场核对线路名称及塔号与工作票相符后，方可开始工作。3、工作前，工作负责人应向全体工作人员讲解工作存在的风险，交待安全措施，填写班前会记录表并签字确认。4、线路作业应在良好的天气下进行 ，遇有恶劣气象条件和时，应停止工作；在 6 级及以上的大风以及暴雨、雷电、冰雹、大雾、沙尘暴等恶劣天气下，应停止露天高处作业。5、塔上作业人员必须穿全套合格的屏蔽服，且各部件连接良好。6、在带电线路杆塔上工作时，作业人员应与带电导线保持不得小于5m的安全距离。7、高处作业应使用全身式安全带，安全带应采用高挂低用的方式，不应系挂在移动或不牢固的构件上，高空作业任何时刻不得失去安全带保护。8、工作负责人认真做好现场监护，及时纠正不安全的行为。9、攀登杆塔前应检查杆塔、基础是否牢固，检查安全带、脚钉等登高工具、设施完整牢固。上横担工作前，应检查横担联结牢固，检查时安全带应系在主杆或牢固的构件上。10、绝缘架空地线应视为带电体，工作人员与绝缘架空地线之间的距离应不小于0.4m，如需在绝缘架空地线上作业时，须对其接地后方可开展，作业结束后拆除。11、做好疫情防控措施。12、注意交通安全。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D60D29F035B34B13E05310C0790A0C35', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-26 18:29:49', '0104', '无。', NULL, '在500kV继电器小室、主变及35kV继电器小室、35kV开关柜室、10kV开关柜室、极1及低端换流器控制保护设备室、极1高端换流器控制保护设备室、极2及低端换流器控制保护设备室、极2高端换流器控制保护设备室、站公用二次设备室、直流继电器小室、380V公用配电室、极1低端换流器交流配电室、极1高端换流器交流配电室、极2低端换流器交流配电室、极2高端换流器交流配电室、融冰控制保护室、主控楼二楼通信机房、极1低端阀冷控制设备室、极1高端阀冷控制设备室、极2低端阀冷控制设备室、极2高端阀冷控制设备室、极1低端阀冷设备间、极1高端阀冷设备间、极2低端阀冷设备间、极2高端阀冷设备间、融冰阀冷设备室入口处悬挂“在此工作”标示牌。 ', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '6dd80f6775c24d3cb62380edd4916035', '2022-01-26 18:29:49', NULL, '34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '75a690583ff84cdfa1e857528d04747b', NULL, '无。', NULL, NULL, '不需要停电。');
