INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D614261AB08CAAACE05310C0790A42EE', NULL, NULL, '50111、50112。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-25 16:43:57', '0104', '分别断开50111、50112隔离开关电机电源空气开关QF1、控制电源空气开关QF2。', NULL, '1、在50111、50112隔离开关现场操作机构处悬挂“禁止合闸 有人工作”标示牌，并在监控界面相应位置设“禁止合闸 有人工作”标识； 2、在相关停电设备工作区域装设安全围栏，围栏内设备包括#2主变500kV侧5011断路器A相，并在围栏上向内悬挂“止步，高压危险！”标示牌，在围栏入口处悬挂“从此进出”标示牌，在围栏内显著位置面向围栏入口悬挂“在此工作”标示牌； 3、将50111、50112隔离开关机构箱常规锁更换为“检修隔离”锁。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, 'b866f0a15f1141e48c31ea6a1a9d52a0', '2022-01-25 16:43:57', NULL, '33', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'a791589598364e7bb5f40249d5273fe6', NULL, '无。', '无。', NULL, NULL);
