INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D6621595A5BBEBDAE05310C0790A61C1', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 12:15:50', '0104', '无。', NULL, '分别在主控楼：继电保护室、317计算机室、305载波机室、313微波机室、112直流室、110交流配电室；设备区：中央配电室大门把手处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '无。', '746e1cec21174e7fb375c5ec3e2dc50e', '2022-01-28 12:15:50', NULL, '24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'f49a20ea4f8944c885b15885697cb722', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D6656E9391E52C54E05310C0790A8C74', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 18:11:56', '0101', '无。', NULL, '分别在500kV牛从甲极1YYA相、YYB相、YYC相、YDA相、YDB相、YDC相，500kV牛从甲极2YYA相、YYB相、YYC相、YDA相、YDB相、YDC相，500kV牛从乙极1YYA相、YYB相、YYC相、YDA相、YDB相、YDC相，500kV牛从乙极2YYA相、YYB相、YYC相、YDA相、YDB相、YDC相换流变，500kV #1站用变、500kV #2站用变及500kV#4主变A相、#4主变B相、#4主变C相油色谱在线监测装置本体处悬挂“在此工作”标示牌；在主控楼3楼换流变、站用变油色谱在线监测装置后台电脑处；主控楼二楼站公用控制保护室202：TROM-600变压器油色谱在线监测系统控制屏、油色谱控制主机屏（=AUTO+V1）、 220kVGIS局放监测主机屏（=22JF+V1）处；主控楼二楼通信机房201：油色谱在线监测综合处理单元屏柜（=20X91+X1）、14P长园深瑞油色谱监控系统交换机屏、52P调度数据网接入设备屏处悬挂“在此工作”标示牌并在相邻运行屏柜围“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '7730d71244a04df2918081c8f49569f0', '2022-01-28 18:11:56', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5d50003f10c843b48a5fa49849b73433', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D665A44E670C2C56E05310C0790A993B', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 16:45:10', '0101', '无。', NULL, '在500kV #1主变A、B、C相，500kV #2主变A、B、C相，500kV #3主变A、B、C相，500kV #4主变A、B、C相，500kV山花甲线高抗A、B、C相，500kV山花乙线高抗A、B、C相油色谱在线监测装置处，主控楼二楼主控室油色谱在线监测后台电脑、油色谱在线监测综合处理单元处分别悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '7257c905847c4aadb42c2b691538e67a', '2022-01-28 16:45:10', NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7a15ad28e04a41428ef475fbc9760cc8', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D665A44E67152C56E05310C0790A993B', NULL, NULL, '3611、3621、3631、3641。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 01:01:36', '0102', '分别断开3611、3621、3631、3641隔离开关机构箱内电机电源QF1空气开关。', NULL, '1、分别在3611、3621、3631、3641隔离开关机构箱门锁处悬挂“禁止合闸，有人工作！”标示牌；\\r\\n2、分别在35kV 361滤波电容器组、中性点电流互感器、避雷器、电抗器，35kV 362滤波电容器组、中性点电流互感器、避雷器、电抗器，35kV 363滤波电容器组、中性点电流互感器、避雷器、电抗器，35kV 364滤波电容器组、中性点电流互感器、避雷器、电抗器处悬挂“在此工作！”标示牌，并在其四周装设向内带有“止步，高压危险！”警示语的安全围栏，在围栏入口处悬挂“从此进出！”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人电话：15286075625。', '8bb4141cee4a46bda11fdd2a5d407732', '2022-01-30 01:01:36', NULL, '31', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '6fb430024e2b4870a329d88bf3531b37', NULL, '无。', '1、在35kV 361滤波电容器组电抗器靠361断路器侧装设35kV 接地线1组；\\r\\n2、在35kV 362滤波电容器组电抗器靠362断路器侧装设35kV 接地线1组；\\r\\n3、在35kV 363滤波电容器组电抗器靠363断路器侧装设35kV 接地线1组；\\r\\n4、在35kV 364滤波电容器组电抗器靠364断路器侧装设35kV 接地线1组。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D66A7C40AC7C5A11E05310C0790A6B3F', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 14:32:44', '0103', '无。', NULL, '1、在计算机室：监控系统服务器1、监控系统服务器2分别放置“在此工作！”标示牌；\\r\\n2、在31小室：10P 31小室公用测控柜、15P 110V #1直流充电柜、18P 110V #2直流充电柜、38P 110V #3直流充电柜前后悬挂“在此工作！”标示牌，将工作屏内的非工作设备面板、背板用红色绝缘胶布封贴，将与工作屏柜相邻的非工作屏柜闭锁并围红色“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '041d4b0d5e9b485a9a041c13184995e3', '2022-01-27 14:32:44', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bed76285def9455e9da523a5d4febb8a', NULL, '无。', NULL, NULL, '不停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D66A7C40AF165A11E05310C0790A6B3F', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, '1、±500kV牛寨换流站：±500kV牛从乙直流极1母线25105隔离开关、±500kV牛从乙直流极1转换母线25121隔离开关，±500kV牛从乙直流极2母线25205隔离开关、±500kV牛从乙直流极2转换母线25122隔离开关；\\r\\n2、±500kV从西换流站：±500kV牛从乙直流极1母线25105隔离开关、±500kV牛从乙直流极1转换母线25121隔离开关，±500kV牛从乙直流极2母线25205隔离开关、±500kV牛从乙直流极2转换母线25122隔离开关。', NULL, NULL, '0.000000000000000', '2022-01-29 04:29:19', '0102', NULL, NULL, '1、±500kV牛寨换流站：分别在±500kV牛从乙直流极1母线25105隔离开关、±500kV牛从乙直流极1转换母线25121隔离开关，±500kV牛从乙直流极2母线25205隔离开关、±500kV牛从乙直流极2转换母线25122隔离开关的操作把手上悬挂“禁止合闸，线路有人工作！”标示牌；\\r\\n2、±500kV从西换流站：分别在±500kV牛从乙直流极1母线25105隔离开关、±500kV牛从乙直流极1转换母线25121隔离开关，±500kV牛从乙直流极2母线25205隔离开关、±500kV牛从乙直流极2转换母线25122隔离开关的操作把手上悬挂“禁止合闸，线路有人工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作负责人 陈建：15885807097  ，线路融冰工作组组长 曾遗松:  13885308986。', '548c5c8157e84cbba38f9211d9303b6d', '2022-01-29 04:29:19', NULL, '14', NULL, NULL, NULL, NULL, NULL, NULL, '1、±500kV牛寨换流站：±500kV牛从乙直流极1线路251217接地刀闸，±500kV牛从乙直流极2线路251227接地刀闸；\\r\\n2、±500kV从西换流站：±500kV牛从乙直流极1线路251217接地刀闸，±500kV牛从乙直流极2线路251227接地刀闸。', NULL, '8664430961c94e4b8e50e93d7cc0eff6', NULL, '1、验电及挂、拆接地线时必须戴绝缘手套，人体应保持与验电器连接线、地线接地线1.5m安全距离并有专人监护。验电必须使用±35kV专用闭合式回路合格验电器。挂接地线时应先接接地端，后接导线端，拆接地线时程序与此相反。2、工作负责人必须得到线路融冰工作组组长下达可以开展分闸工作指令后进入工作现场，方可组织工作班人员开展工作。登塔前必须核对线路名称和塔号，核对时应由两名及以上人员进行，确认无误后方可登塔，以防止误登其他带电线路。±500kV牛从甲线与±500kV牛从乙线平行运行，部分杆塔为同塔双回线路；作业人员在同塔双回工作时，应佩戴黄色袖标，且严禁进入带电侧横担，登杆塔和在杆塔上工作时，每基杆塔都应设专人监护；登杆塔至横担处时，应再次核对识别标记与线路名称和位置，确认无误后方可进入检修线路侧横担。3、登塔前必须检查所用安全用具、工器具是否完好，操作是否灵活，严禁使用不合格的安全用具和工器具。4、人体应保持与架空地线（OPGW光缆）、操作机构箱应保持1.5m安全距离。5、高空作业须严格遵守《超高压输电公司防止高空坠落的措施》的规定，工作人员上下塔、进出绝缘子串等必须使用双控全身式高空安全带交叉保护，高空作业任何时刻不得失去安全带（绳）的保护。严格遵守《超高压输电公司防止人身伤亡事故守则》，多人同时登塔或高处作业时，不能有两个及以上人员处于同一垂直面。6、现场人员必须戴安全帽，登塔或在塔上作业时，每基杆塔均设专人监护，监护人必须始终在现场并认真监护，及时纠正不安全的行为。7、其余安全注意事项必须严格按照经批准的《±500kV牛从甲乙直流防冰工作手册-贵阳局管辖段地线融冰（2021-2022年）》所列安全措施执行。8、只需要操作±500kV牛从乙线普通地线第2分段（1118#塔-1272#塔）融冰对应的接线装置和接地刀闸。9、工作结束后，工作负责人必须确认工作人员已全部下塔，且塔上无遗留物，方可办理工作票终结手续。', NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D66A7C40AF345A11E05310C0790A6B3F', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-29 15:40:37', '0106', '1、断开500kV 1号检修电源箱内温度加热控制5MCB空气开关；2、断开500kV 2号检修电源箱内温度加热控制5MCB空气开关。', NULL, '1、在500kV 1号检修电源箱内温度加热控制5MCB空气开关粘贴“禁止合闸，有人工作”警示标签； 2、在500kV 2号检修电源箱内温度加热控制5MCB空气开关粘贴“禁止合闸，有人工作”警示标签；3、在500kV 1号检修电源箱、500kV 2号检修电源箱分别悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '884d4a96e7114452a96e360bc8e793d2', '2022-01-29 15:40:37', NULL, '20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '740c514a47d84a5ab545b8b1704125d9', NULL, '无。', NULL, NULL, '不需要停电。');
