INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D68B2D7F327FCB40E05301C0790A7D06', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 15:33:00', '0101', '无。', NULL, '分别在花都站主控室、计算机室、通信机房、500kV #1继保室、500kV #2继保室、500kV #1蓄电池室1、500kV #1蓄电池室2、500kV #2蓄电池室1、500kV #2蓄电池室2、主控楼蓄电池室、220kV #1继保室、220kV #2继保室、主变继保室、检修办公室、安全工器具室、交接班室、会议室、站长室、专责办公室、值长休息室、综合楼宿舍、综合楼活动室、警传楼、厨房的分体式空调室内机和室外机处悬挂“在此工作”的标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-030]', 'dc53c22106c24c029b9829a5736170d0', '2022-01-30 15:33:00', NULL, '29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '975fc69a27aa471d883dc57c025c48af', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D68EA39977F4FD71E05310C0790AF2B2', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-28 06:04:11', '0108', '退出直流融冰控制保护室3P直流融冰切换柜内314开关跳闸出口LP01压板、314开关遥控合闸出口LP03压板、314开关遥控跳闸出口LP04压板、02105隔离刀闸遥控合闸出口LP05压板、02105隔离刀闸遥控分闸出口LP06压板、02205隔离刀闸遥控合闸出口LP07压板、02205隔离刀闸遥控分闸出口LP08压板、05101隔离刀闸遥控合闸出口LP09压板、05101隔离刀闸遥控分闸出口LP10压板、05201隔离刀闸遥控合闸出口LP11压板、05201隔离刀闸遥控分闸出口LP12压板、05102隔离刀闸遥控合闸出口LP13压板、05102隔离刀闸遥控分闸出口LP14压板、05202隔离刀闸遥控合闸出口LP15压板、05202隔离刀闸遥控分闸出口LP16压板、3141隔离刀闸遥控合闸出口LP17压板、3141隔离刀闸遥控分闸出口LP18压板。', NULL, '1、在直流融冰控制保护室4P 直流融冰 #2控制柜、5P 直流融冰 #1控制柜上悬挂“在此工作！”标示牌； 2、在直流融冰控制保护室与4P 直流融冰 #2控制柜、5P 直流融冰 #1控制柜相邻的屏柜上悬挂“运行设备！”标示牌并粘贴红色“运行设备！”胶带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '183a506c13184946acfff46499694154', '2022-01-28 06:04:11', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7214aefefa234143b16f9352866e2a3a', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D68EA5289E2C4E8FE05310C0790AE8D6', NULL, NULL, '3013。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, NULL, '2022-01-30 12:58:59', '0102', '1、断开3013隔离开关机构箱电机电源K1空气开关；\\r\\n2、812断路器（试验位置）。', NULL, '1、分别在#0站用变，#0站用变35kV侧301断路器端子箱，35小室7P 35kV #2M母、#0站用变、380V分段测控屏，35小室36P #0、#1站用变保护屏，安稳及监控室监控服务器A、监控服务器B处悬挂“在此工作！”标示牌；\\r\\n2、分别在#0站用变，#0站用变35kV侧301断路器端子箱四周装设向内带有“止步，高压危险！”警示语的安全围栏，在围栏入口处悬挂“从此进出！”标示牌；\\r\\n3、在3013隔离开关机构箱门锁处悬挂“禁止合闸，有人工作！”标示牌；\\r\\n4、在812断路器操作机构把手处悬挂“禁止合闸，有人工作！”标示牌；\\r\\n5、分别在35小室6P #1站用变、#3站用变测控屏，8P #2B主变测控屏，35P 323、325低压电抗器测控保护、电压并列装置屏，37P #3站用变保护测控屏上悬挂“运行设备”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '工作负责人电话：18786707830。\\r\\n值班调度员中无法选择田涛，选择田孟涛代替。', '32ef8e2f24ba479fa6ae3ff4d84f4723', '2022-01-30 12:58:59', NULL, '1', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '74db093cedf949a88be47f9f5624e4b0', NULL, '无。', '1、在#0站用变35kV侧301断路器靠#0站用变本体侧装设35kV接地线1组；\\r\\n2、在#0站用变380V侧装设400V接地线1组。', NULL, NULL);
