INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('D692E445EC2635FDE05310C0790AE1D1', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-30 09:36:58', '0107', '1、断开极1阀冷却设备间101内P2极1阀冷系统电源屏2：喷淋泵P322电源开关Q322；\\r\\n2、断开极1阀冷却设备间101内P1极1阀冷系统电源屏1：电机加热器电源空开OF20。', NULL, '1、在极1阀冷却设备间101内P2极1阀冷系统电源屏2：喷淋泵P322电源开关Q322上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n2、在极1阀冷却设备间101内P1极1阀冷系统电源屏1：电机加热器电源空开OF20上悬挂“禁止合闸，有人工作！”标示牌；\\r\\n3、在极1阀冷系统P322喷淋泵处悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '32b746eb166d49418d8835fb8581f087', '2022-01-30 09:36:58', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2fd0905ac7e74dd7b692592d74576aef', NULL, '无。', NULL, NULL, '不需要停电。');
