INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('d9b61658623742948b63656ee714a372', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-17 17:08:36', '0101', '无。', NULL, '分别在±500kV宝安换流站主控三楼主控室（301）、极1及公用设备室（303）、极2及公用设备室（304）、系统分析及培训室（305）、交接班室（306）备班室（307）及走廊区域处悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '[交底单号：2021-12-C0-021]', 'EX0383', '2022-01-17 17:08:36', NULL, '71', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'fe16bf2d68864eb984208522168f8033', NULL, '无。', NULL, NULL, '不需要停电。');
