INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('e6a73b9131d342259df67275d4247a4f', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-29 15:07:52', '0101', '无。', NULL, '在±500kV肇庆换流站500kV交流场、交流滤波器场、±500kV 双极直流场、双极换流变及平抗、站用电区域悬挂“在此工作”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012004', '2022-01-29 15:07:52', NULL, '18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '7341bdcaa8a14fe69db7f8f8e4794eec', NULL, '无。', NULL, NULL, '不需要停电。');
