INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('eace3c90572d4e3f9b8639a186dcab67', NULL, NULL, '1034。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-04 08:48:13', '0101', '断开1034刀闸控制电源F211、电机电源2QA。', NULL, '1、在500kV #1继保室：110kV 站用电就地控制接口屏 （=20E00+SW1 ）前后悬挂“在此工作”标示牌，并在相邻屏柜围“运行设备”警示带；在主控楼3楼：控制保护工程师工作站、远动工作站处悬挂“在此工作”标示牌；2、在隔离开关1034就地操作机构箱把手上悬挂“禁止合闸、有人工作”标示牌； 3、分别在1034刀闸控制电源F211、电机电源2QA处悬挂“禁止合闸，有人工作”标示牌；4、在110kV #3站用变高压侧103开关、110kV #3站用变中性点地刀本体处悬挂“在此工作”标示牌。5、分别在110kV #3站用变高压侧103开关、110kV #3站用变中性点地刀本体处四周装设安全围栏，向内悬挂“止步，高压危险”标示牌，并在安全围栏入口处悬挂“从此进出”、“在此工作”标示牌。', NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '工作过程中需多次分合103开关、103000地刀。', '01012001', '2022-01-04 08:48:13', NULL, '39', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, 'ba8ed6b0f194477cb87adc149e1fbc12', NULL, '无。', '无。', NULL, NULL);
