INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f007c4ae6ad6434eabe4f79d72d28e5f', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-01 10:46:42', '0107', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-01 10:46:42', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', '3125da04b3b34ae2adf8934b011f91f1', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f008507e4509455d81084710b318a9bf', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 19:35:47', '0109', '无。', NULL, '1、在极1低端阀冷却设备室PS11氮气瓶处悬挂“在此工作！”标示牌。\\r\\n', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交代：已完成极1低端阀冷系统PS11氮气瓶压力低异常检查处理，现场已更换新的氮气压力表，更换后信号正常，节点导通正常，可投入使用。', '01090606', '2022-01-19 19:35:47', NULL, '21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'd62f8f9bca1c4fba90553ae36322c525', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f00bef7eed91417c9a5f750e9b5026c4', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-07 21:50:31', '0109', '无。', NULL, '1、分别在51继电器室、主控楼二楼站及双极控制保护室、主控楼二楼通信机房、极1辅控楼二楼极1高端控制保护及辅助设备室、极2辅控楼二楼极2高端控制保护及辅助设备室门口悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '检修交代：已完成1月份第1周稳控系统专业巡视，设备运行正常，各装置模拟量采样、状态量开入正常，无异常报文。', '01090602', '2022-01-07 21:50:31', NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2a62b3c6ee6b47e891771289a9977000', NULL, '无。', NULL, NULL, '不需要停电。');
