INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f521fa40b3504836afacf9ecfaaabe3f', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-06 23:11:38', '0104', '退出继电保护室：132P 220kV宾来Ⅱ线第二套保护屏如下连接片：8LP1（开关保护RCS-923A充电过流保护跳2058#1线圈）、8LP2（开关保护RCS-923A充电过流保护跳2058#2线圈）、8LP3（开关保护RCS-923A非全相保护跳2058#1线圈）、8LP4（开关保护RCS-923A非全相保护跳2058#2线圈）。', NULL, '在继电保护室：132P 220kV宾来Ⅱ线第二套保护屏前悬挂“在此工作”标示牌，并在相邻屏柜设置“运行设备”标识，在132P 220kV宾来Ⅱ线第二套保护屏内220kV宾来Ⅱ线主二保护RCS-931AMMV前粘贴“运行设备”标识。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01040809', '2022-01-06 23:11:38', NULL, '26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '4cbd4ea9459841c4bf70a1915f8cdf7c', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f546825b746e40f88e7a87a185e4abd9', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-27 19:58:00', '0101', '无。', NULL, '分别在+800kV极1高端阀厅、+400kV极1低端阀厅、-800kV极2高端阀厅、-400kV极2低端阀厅、极1冷却塔、极2冷却塔、500kV#1继保室、#2继保室、#3继保室、自耦变及35kV继保室、220kV继保室、极2高端阀组阀冷控制保护设备室、极2辅助设备室、极2低端阀组阀冷控制保护设备室、站及双极控制保护设备室#1、站及双极控制保护设备室#2、主控制室、极2高端阀组控制保护室、极2及其低端阀组控制保护设备室、极1辅助设备室、极1低端阀组阀冷控制保护设备室、极1高端阀组阀冷控制保护设备室、极1高端阀组控制保护室、极1及其低端阀组控制保护设备室及全站蓄电池室控制保护屏柜悬挂“在此工作”标示牌，并在相邻屏柜粘贴“运行设备”警示带。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01012010', '2022-01-27 19:58:00', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a83f8af4b829469bbea727ae155954b2', NULL, '无。', NULL, NULL, '不需要停电。');
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f550b2c97a5340ad848f6501e350bdb3', NULL, NULL, '10kV #1跌落式熔断器、10kV #2跌落式熔断器。', NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-19 22:05:38', '0103', '断开#N0站用变0.4kV侧3ZK开关，并将其摇出至“试验”位置。', NULL, '1、在#N0站用变0.4kV侧3ZK开关、10kV #1跌落式熔断器、10kV #2跌落式熔断器分别悬挂“禁止合闸，有人工作！”标示牌； 2、在#N0站用变、10kV #1跌落式熔断器、10kV #2跌落式熔断器、#N0站用变至10kV #1跌落式熔断器之间新建电缆沟路径分别悬挂“在此工作！”标示牌； 3、在#N0站用变、10kV #1跌落式熔断器、10kV #2跌落式熔断器范围内装设向内标示“止步，高压危险！”的安全遮栏，并在遮栏出入口处悬挂“从此进出！”标示牌。', NULL, NULL, '1', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, '[交底单号：2022-01-C0-005]\\r\\n1、在10kV #1跌落式熔断器来电侧装设1组编号为#12的10kV三相短路接地线；2、在#N0站用变380V出线侧装设1组编号为#15的380V三相短路接地线。\\r\\n补充安全交代：\\r\\n韦秋连  2022.01.12 09:00\\r\\n李显荣  2022.01.13 09:12\\r\\n莫政科、杨盛  2022.01.18 11:05', 'EX0315', '2022-01-19 22:05:38', NULL, '67', NULL, NULL, NULL, NULL, '无。', NULL, NULL, NULL, '09f76f4204124b76886e0b68a8077fb5', NULL, '无。', '1、在10kV #1跌落式熔断器来电侧装设1组10kV三相短路接地线；2、在#N0站用变380V出线侧装设1组380V三相短路接地线。', NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f56bea613b7a4c21a4b0e17421858da4', NULL, NULL, NULL, NULL, '2', NULL, '01', NULL, NULL, NULL, NULL, '2', '0.000000000000000', '2022-01-21 09:42:33', '0107', NULL, NULL, NULL, NULL, NULL, '2', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', NULL, NULL, NULL, NULL, '2022-01-21 09:42:33', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2', 'e316edbb149249ff917de889526f5920', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f57d7efbe58b4fac908658006cfd982e', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-24 15:17:26', '0107', '无。', NULL, '1、分别在50511、50512、50521、50532隔离开关上悬挂“在此工作！”标示牌；\\r\\n2、分别在50911、50912、50921、50922、50931、50932隔离开关上悬挂“在此工作！”标示牌；\\r\\n3、分别在3026、3292、3212、3222、3232隔离开关上悬挂“在此工作！”标示牌；\\r\\n4、在110kV李换线10016隔离开关上悬挂“在此工作！”标示牌；\\r\\n5、在500kV ＃2B站用变500kV侧5651隔离开关上悬挂“在此工作！”标示牌。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, NULL, '01070103', '2022-01-24 15:17:26', NULL, '22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1fb7cfdeeeda404086bba91aaac90cf4', NULL, '无。', NULL, NULL, '不需要停电。');
