INSERT INTO `sp_pd_wticket_saftymeasures` VALUES ('f7a70c82c9e04cc78167b17495a9d5f5', NULL, NULL, NULL, NULL, NULL, NULL, '01', NULL, NULL, NULL, NULL, NULL, '0.000000000000000', '2022-01-06 13:10:57', '0109', '无。', NULL, '无。', NULL, NULL, NULL, NULL, NULL, NULL, '不停电。', NULL, '0.000000000000000', NULL, NULL, '已完成：1、平波电抗器专业巡视；2、直流穿墙套管专业巡视；3、直流分流器专业巡视；4、直流分压器专业巡视；5、直流滤波器专业巡视。设备无异常。', '01090603', '2022-01-06 13:10:57', NULL, '23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ae81ba8261a64224828a811b3c18e530', NULL, '无。', NULL, NULL, '不需要停电。');
