  `is_graph` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否点图成票（枚举：1=是，2=否）',
  `ticket_end_watch_uname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作票终结（值班负责人名称）',
