  `work_permission_oid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作许可人班组ID',
  `out_or_in` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内外网类型（枚举：1=内网，2-=外网；）',
  `power_grid_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电网类型（枚举：1=主网，2=配网，3=发电）',
