  `ticket_counter_sign_uid` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作票会签人ID',
  `major` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '专业类型（枚举：1=变电专业，2=输电专业， 3=配电专业）',
  `ticket_end_time` datetime NULL DEFAULT NULL COMMENT '工作票终结（终结时间）',
  `data_belong_unit_oname` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据归口单位名称',
  `is_key_station` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否关键重要站(1=是，2=否)',
