-- ----------------------------
-- Table structure for sp_pd_wticket_saftymeasures
-- ----------------------------
DROP TABLE IF EXISTS `sp_pd_wticket_saftymeasures`;
CREATE TABLE `sp_pd_wticket_saftymeasures`  (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `per_pull_breaker` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '（许可人填写）应断开的断路器（开关）（双重名称或编号）',
  `safty_and_care` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应采取的安全措施及安全注意事项：线2、配2、带电作业工作票业务表单-应采取的安全措施及安全注意事项',
  `pull_switch` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应拉隔离开关（刀闸）：变电第一种工作票业务表单-应拉隔离开关（刀闸）',
  `earthwire_count_safe` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '保安地线数(现场安全措施)：配1（现场安全措施）工作票业务表单',
  `whether_poweroff` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否停电工作(枚举：1-是； 2-否):配电低压工作单',
  `per_billboard` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '（许可人填写）应装设遮栏、应悬挂标志牌（位置）',
  `province_code` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '省编码',
  `billboard_local` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应设遮拦、应挂标示牌(现场安全措施)：配1（现场安全措施）工作票业务表单',
  `ele_line_device` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '保留的带电线路或带电设备：线1、配1工作票业务表单-保留的带电线路或带电设备',
  `pull_breaker_switch` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应拉断路器（开关）和隔离开关（刀闸）：线路第一种工作票业务表单-应拉断路器（开关）和隔离开关（刀闸）',
  `earthwire_count_work` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作地线数(现场安全措施)：配1（现场安全措施）工作票业务表单',
  `whether_notice` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否通知重要客户:配电低压工作单(枚举：1-是； 2-否)',
  `longitude` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '经度-作业地点',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `bureau_code` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '局编码',
  `dcpower_lowp_circle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应投切相关直流电源、低压及二次回路：变1、配1工作票业务表单-应投切相关直流电源、低压及二次回路',
  `per_dcpower_lowp_circle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '（许可人填写）应投切的相关交直流电源（负荷开关、空气开关、熔断器等）、低压及二次回路（连接片、软压板、转换开关、尾纤等）',
  `billboard` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应设遮拦、应挂标示牌：变1、变2、线1、配1（系统安全措施）工作票业务表单-应设遮拦、应挂标示牌',
  `updator_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人ID',
  `nearby_ele_device` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '邻近的带电设备名称（新安规添加）',
  `whether_line_grounding` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否要求线路对侧接地(枚举：1-是； 2-否)：变电第一种工作票业务表单-是否要求线路对侧接地',
  `disater_repair_guardian_uname` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '灾后抢修专责监护人名称',
  `stop_line` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '需停用重合闸线路：配电作业工作单',
  `creator_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人ID',
  `power_circle_state` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '相关直流低压及二次回路状态：变电第二种工作票业务表单-相关直流低压及二次回路状态',
  `per_switch_ear_insulation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '（许可人填写）应合上的接地刀闸（双重名称或编号）、装设的接地线（装设地点）、装设的绝缘挡板',
  `latitude` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纬度-作业地点',
  `line_state_require` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '线路状态要求',
  `repair_control_uid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '抢修任务布置人ID',
  `remark` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `data_from` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据来源',
  `update_time` datetime NULL DEFAULT NULL COMMENT '数据更新时间',
  `disater_repair_guardian_uid` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '灾后抢修专责监护人id',
  `optimistic_lock_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '乐观锁版本',
  `work_way` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作方式或工作环境(新安规添加)',
  `required_safty` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作要求的安全措施：变电第三种工作票业务表单-工作要求的安全措施-字符型 工作条件及运行方式要求： 配电带电作业工作票',
  `repair_control_uname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '抢修任务布置人名称',
  `per_pull_switch` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '（许可人填写）应拉开的隔离开关（刀闸）（双重名称或编号）',
  `pull_breaker` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应拉断路器（开关）：变1、配1票业务表单-应拉断路器（开关）',
  `work_condition` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作条件及运行方式要求：配电作业工作单',
  `close_switch_earthwire` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应合接地开关、装接地线：线1工作票业务表单-应合接地开关、装接地线',
  `whether_load_adjustment` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否关联低压负荷调整单（低压配网票）：1：是，2：否',
  `wticket_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作票ID',
  `earthwire_count` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应设地线数(现场安全措施)：配1（现场安全措施）工作票业务表单-应设地线数',
  `other_care` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '其他安全注意事项：线1、配1工作票业务表单-其他安全注意事项',
  `switch_earthwire_insulation` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应合接地开关、装设接地线、应设绝缘挡板：变1、配1工作票业务表单-应合接地开关、装设接地线、应设绝缘挡板',
  `job_location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '作业地点',
  `highp_device_state` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '相关高压设备状态：变电第二种工作票业务表单-相关高压设备状态',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工作票-工作应采取的安全措施' ROW_FORMAT = Dynamic;

